            pos = link_value.end;
        }
        try self.plain(value[pos..], style);
    }
    const DecodedEntity = struct { bytes: []const u8, consumed: usize, scratch: bool = false };

    fn decodeEntity(input: []const u8, buf: *[4]u8, visible_text: bool) ?DecodedEntity {
        const end = std.mem.indexOfScalar(u8, input[0..@min(input.len, 64)], ';') orelse return null;
        if (end < 2) return null;
        const name = input[1..end];
        if (name[0] == '#') {
            const hex = name.len > 1 and (name[1] == 'x' or name[1] == 'X');
            const digits = name[if (hex) @as(usize, 2) else 1..];
            if (digits.len == 0) return null;
            for (digits) |digit| {
                if (!(if (hex) std.ascii.isHex(digit) else std.ascii.isDigit(digit))) return null;
            }
            const cp = std.fmt.parseInt(u21, digits, if (hex) 16 else 10) catch return null;
            // Visible text normalizes references; attributes/URLs retain decoding policy.
            if (visible_text and !(cp == 0x09 or cp == 0x0a or
                (cp >= 0x20 and cp <= 0x7e) or (cp >= 0xa0 and cp <= 0xd7ff) or
                (cp >= 0xe000 and cp <= 0xfffd) or (cp >= 0x10000 and cp <= 0x10ffff))) return null;
            const n = std.unicode.utf8Encode(if (cp == 0 or cp > 0x10ffff or (cp >= 0xd800 and cp <= 0xdfff)) 0xfffd else cp, buf) catch return null;
            return .{ .bytes = buf[0..n], .consumed = end + 1, .scratch = true };
        }
        // Renderer text follows MediaWiki's named-reference policy; dump typo
        // aliases belong only to XML recovery. MediaWiki additionally accepts
        // these Hebrew/Arabic spellings of the right-to-left mark.
        const value: []const u8 = if (std.mem.eql(u8, name, "רלמ") or std.mem.eql(u8, name, "رلم"))
            "\u{200f}"
        else
            entities.lookupHtmlNamedEntity(name) orelse return null;
        return .{ .bytes = value, .consumed = end + 1 };
    }
    fn entity(self: *Renderer, input: []const u8, style: Style) Error!?usize {
        var buf: [4]u8 = undefined;
        const decoded = decodeEntity(input, &buf, true) orelse return null;
        var entity_style = style;
        if (entity_style.provenance == .parsed) entity_style.provenance = .entity_literal;
        // References decode after block/Poem line handling. Their LF/HT are
        // ordinary HTML whitespace, not newly authored semantic line breaks.
        // Actual preformatted styles retain both code points unchanged.
        const soft_space = !style.preserve_whitespace and decoded.bytes.len == 1 and
            (decoded.bytes[0] == '\n' or decoded.bytes[0] == '\t');
        const value: []const u8 = if (soft_space) " " else if (decoded.scratch) try self.a.dupe(u8, decoded.bytes) else decoded.bytes;
        try self.text(value, entity_style);
        return decoded.consumed;
    }
    fn protectedLiteral(self: *Renderer, input: []const u8, style: Style) Error!void {
        var literal_style = style;
        literal_style.provenance = .protected_literal;
        try self.literal(input, literal_style);
    }
    fn protectedNowikiLiteral(self: *Renderer, input: []const u8, style: Style) Error!void {
        // Ordinary nowiki is unstripped into HTML text: raw LF is soft space.
        // Parsed pre keeps authored whitespace; Poem dispatches its registered
        // semantic breaks through the existing protected-literal path.
        if (style.preserve_whitespace or self.poem_depth != 0)
            return self.protectedLiteral(input, style);
        var literal_style = style;
        literal_style.provenance = .protected_literal;
        var start: usize = 0;
        while (std.mem.indexOfScalarPos(u8, input, start, '&')) |i| {
            try self.plain(input[start..i], literal_style);
            if (try self.entity(input[i..], literal_style)) |n| {
                start = i + n;
            } else {
                try self.text("&", literal_style);
                start = i + 1;
            }
        }
        try self.plain(input[start..], literal_style);
    }
    fn literal(self: *Renderer, input: []const u8, style: Style) Error!void {
        var start: usize = 0;
        while (std.mem.indexOfScalarPos(u8, input, start, '&')) |i| {
            try self.text(input[start..i], style);
            if (try self.entity(input[i..], style)) |n| {
                start = i + n;
            } else {
                try self.text("&", style);
                start = i + 1;
            }
        }
        try self.text(input[start..], style);
    }
    fn externalUrlTarget(self: *Renderer, value: []const u8) Error![]const u8 {
        if (std.mem.indexOfScalar(u8, value, '&') == null) return value;
        var out: std.ArrayList(u8) = .empty;
        var start: usize = 0;
        while (std.mem.indexOfScalarPos(u8, value, start, '&')) |i| {
            try out.appendSlice(self.a, value[start..i]);
            var buf: [4]u8 = undefined;
            if (decodeEntity(value[i..], &buf, false)) |decoded| {
                // Literal lowercase entities are source delimiters handled by
                // DocIR. Other encoded angles belong to the URL, not its label.
                const delimiter = starts(value[i..], "&lt;") or starts(value[i..], "&gt;");
                if (!delimiter and std.mem.eql(u8, decoded.bytes, "<")) {
                    try out.appendSlice(self.a, "%3C");
                } else if (!delimiter and std.mem.eql(u8, decoded.bytes, ">")) {
                    try out.appendSlice(self.a, "%3E");
                } else if (starts(value[i..], "&#") and std.mem.eql(u8, decoded.bytes, " ")) {
                    try out.append(self.a, '+');
                } else if (starts(value[i..], "&#") and std.mem.eql(u8, decoded.bytes, "\t")) {
                    try out.appendSlice(self.a, "%09");
                } else if (starts(value[i..], "&#") and std.mem.eql(u8, decoded.bytes, "\n")) {
                    try out.appendSlice(self.a, "%0A");
                } else if (starts(value[i..], "&#") and std.mem.eql(u8, decoded.bytes, "\r")) {
                    try out.appendSlice(self.a, "%EF%BF%BD");
                } else if (std.mem.eql(u8, decoded.bytes, "\"")) {
                    try out.appendSlice(self.a, "%22");
                } else if (std.mem.eql(u8, decoded.bytes, "\xc2\xa0")) {
                    try out.appendSlice(self.a, "%C2%A0");
                } else try out.appendSlice(self.a, decoded.bytes);
                start = i + decoded.consumed;
            } else {
                try out.append(self.a, '&');
                start = i + 1;
            }
        }
        try out.appendSlice(self.a, value[start..]);
        return out.toOwnedSlice(self.a);
    }
    fn externalUrlLabel(self: *Renderer, value: []const u8, style: Style) Error!void {
        // Only the proven closing-brace runs are literal. Keep all surrounding
        // visible text parsed, with the same validated action and style.
        var start: usize = 0;
        while (std.mem.indexOfPos(u8, value, start, "}}")) |at| {
            try self.text(value[start..at], style);
            var end = at + 2;
            while (end < value.len and value[end] == '}') : (end += 1) {}
            var literal_style = style;
            literal_style.provenance = .protected_literal;
            try self.text(value[at..end], literal_style);
            start = end;
        }
        try self.text(value[start..], style);
    }
    pub fn link(self: *Renderer, label: []const u8, target: []const u8, style: Style, depth: usize, external: bool) Error!void {
        return self.linkWithMissing(MissingText.untracked(label), target, style, depth, external);
    }
    pub fn linkWithMissing(self: *Renderer, tracked: MissingText, target: []const u8, style: Style, depth: usize, external: bool) Error!void {
        const label = tracked.bytes;
        var s = style;
        const resolved_target = if (external) try self.externalUrlTarget(target) else target;
        if (external and unresolvedExternalActionTarget(resolved_target)) {
            self.fallbacks.rejected_external_target = true;
            // Retain an authored label and all its formatting, but never inherit
            // an outer action or fabricate a replacement destination.
            s.kind = .text;
            s.target = "";
            if (std.mem.eql(u8, label, target)) {
                self.unresolved_templates += 1;
                return error.UncompiledTemplate;
            }
            const label_start = self.spans.items.len;
            try self.inlineTextWithMissing(try missingSlice(self.a, tracked, label), s, depth + 1);
            // Only this rejected action's emitted label is checked. Real
            // protected/entity literals are not deferred source instructions.
            var previous: u8 = 0;
            for (self.spans.items[label_start..]) |span| {
                if (span.kind == .line_break or span.provenance != .parsed) {
                    previous = 0;
                    continue;
                }
                for (span.text) |ch| {
                    if ((ch == '{' or ch == '}') and ch == previous) {
                        self.unresolved_templates += 1;
                        return error.UncompiledTemplate;
                    }
                    previous = ch;
                }
            }
            return;
        }
        if (resolved_target.len != 0 and (!external or safeUrl(resolved_target))) {
            s.kind = if (external) .external_link else .link;
            s.target = resolved_target;
            if (!external) s.poem_independent_parse = false;
        }
        if (external and std.mem.eql(u8, label, target)) {
            const decoded_label = try self.entityText(label);
            // URL text containing encoded controls/whitespace uses its escaped
            // destination spelling, never raw navigation control characters.
            const escaped_label = std.mem.indexOfAny(u8, decoded_label, " \t\n\r\"") != null or
                std.mem.indexOf(u8, decoded_label, "\xc2\xa0") != null;
            const visible = if (escaped_label) resolved_target else decoded_label;
            if (s.kind == .external_link and safeUrl(resolved_target) and
                !unresolvedExternalActionTarget(resolved_target))
                try self.externalUrlLabel(visible, s)
            else
                try self.text(visible, s);
            return;
        }
        try self.inlineTextWithMissing(try missingSlice(self.a, tracked, label), s, depth + 1);
    }
    fn referenceIndex(self: *Renderer, name: []const u8, group: []const u8, body: []const u8) Error!?usize {
        const use_short_name_compare = self.refs.items.len >= 16;
        if (name.len != 0) for (self.refs.items, 0..) |*ref, i| {
            const same_name = if (use_short_name_compare) referenceStringEqual(ref.name, name) else std.mem.eql(u8, ref.name, name);
            if (!same_name or !std.mem.eql(u8, ref.group, group)) continue;
            if (ref.body.len == 0 and body.len != 0) {
                ref.body = body;
                ref.missing = if (self.inline_missing) |parent| try missingSlice(self.a, parent, body) else if (self.body_missing) |parent| try missingSlice(self.a, parent, body) else MissingText.untracked(body);
            }
            return i;
        };
        var resolved_body = body;
        var resolved_missing = if (self.inline_missing) |parent| try missingSlice(self.a, parent, body) else if (self.body_missing) |parent| try missingSlice(self.a, parent, body) else MissingText.untracked(body);
        // Authenticated native phase definitions include opaque Poem bodies
        // in emitted page order. The legacy raw table cannot see those bodies.
        // Ordinary/legacy calls retain the exact previous table and precedence.
        const page_definitions = if (self.poem_definitions_complete) self.ref_defs.items else self.page_reference_definitions;
        if (name.len != 0) for (page_definitions) |definition| {
            if (definition.body.len != 0 and std.mem.eql(u8, definition.name, name) and std.mem.eql(u8, definition.group, group)) {
                resolved_body = definition.body;
                resolved_missing = definition.missing orelse MissingText.transformed(definition.body);
                break;
            }
        };
        if (name.len != 0 and resolved_body.len == 0) for (self.ref_defs.items) |definition| {
            if (std.mem.eql(u8, definition.name, name) and std.mem.eql(u8, definition.group, group)) {
                resolved_body = definition.body;
                resolved_missing = definition.missing orelse MissingText.transformed(definition.body);
                break;
            }
        };
        if (!self.spend()) return null;
        const index = self.refs.items.len;
        var group_number: usize = 1;
        if (group.len == 0) {
            self.default_group_reference_count += 1;
            group_number = self.default_group_reference_count;
        } else {
            for (self.refs.items) |ref| {
                if (std.mem.eql(u8, ref.group, group)) group_number += 1;
            }
        }
        try self.refs.append(self.a, .{ .number = index + 1, .group_number = group_number, .name = name, .group = group, .body = resolved_body, .missing = resolved_missing, .poem = self.poem_depth != 0, .poem_direction = self.poem_direction });
        return index;
    }
    fn reference(self: *Renderer, name: []const u8, group: []const u8, body: []const u8, style: Style) Error!void {
        if (self.in_reference) {
            try self.text("[nested reference]", style);
            return;
        }
        const index = (try self.referenceIndex(name, group, body)) orelse {
            try self.text("[render output truncated]", style);
            return;
        };
        const ref = self.refs.items[index];
        var s = style;
        s.superscript = true;
        s.role = .reference;
        s.kind = .link;
        s.target = try std.fmt.allocPrint(self.a, "#reference-{d}", .{ref.number});
        const marker = if (group.len == 0)
            try std.fmt.allocPrint(self.a, "[{d}]", .{ref.group_number})
        else
            try std.fmt.allocPrint(self.a, "[{s} {d}]", .{ group, ref.group_number });
        try self.text(marker, s);
    }
    fn referenceDefinitions(self: *Renderer, content: []const u8, default_group: []const u8) Error!void {
        try self.referenceDefinitionsInner(content, default_group, 0, false);
    }
    fn referenceDefinitionsInner(self: *Renderer, content: []const u8, default_group: []const u8, depth: usize, list_defined: bool) Error!void {
        if (depth >= max_depth) {
            self.fallbacks.render_limit = true;
            return;
        }
        var pos: usize = 0;
        var opaque_scan: syntax.OpaqueScan = .{};
        var next_tag = std.mem.indexOfScalar(u8, content, '<');
        var next_item = if (self.poem_items.items.len != 0) std.mem.indexOf(u8, content, poem_prefix) else null;
        while (true) {
            if (next_tag) |at| if (at < pos) {
                next_tag = std.mem.indexOfScalarPos(u8, content, pos, '<');
            };
            if (next_item) |at| if (at < pos) {
                next_item = std.mem.indexOfPos(u8, content, pos, poem_prefix);
            };
            const open = next_tag orelse content.len;
            const marker = next_item orelse content.len;
            if (open == content.len and marker == content.len) break;
            if (marker < open) {
                const item = self.poemItemAt(content[marker..]) orelse {
                    pos = marker + poem_prefix.len;
                    continue;
                };
                pos = marker + item.token.len;
                if (item.kind != .literal or !std.mem.eql(u8, item.tag, "poem")) continue;
                if (self.poem_definition_dispatches >= max_nodes) {
                    self.fallbacks.render_limit = true;
                    return;
                }
                self.poem_definition_dispatches += 1;
                const inner_open = std.mem.indexOfScalar(u8, item.body, '<') orelse continue;
                const inner_tag = syntax.tagAt(item.body, inner_open) orelse continue;
                if (!inner_tag.is("poem") or inner_tag.closing or inner_tag.self_closing) continue;
                const inner_pair = syntax.matchingTag(item.body, inner_tag) orelse continue;
                try self.referenceDefinitionsInner(item.body[inner_tag.end..inner_pair.inner_end], default_group, depth + 1, list_defined);
                continue;
            }
            if (starts(content[open..], "<!--")) {
                pos = syntax.protectedEnd(content, open) orelse content.len;
                continue;
            }
            const tag = try self.semanticTagAt(content, open) orelse {
                pos = open + 1;
                continue;
            };
            pos = tag.end;
            if (!tag.closing and tag.is("references")) {
                const pair = opaque_scan.pair(content, tag) orelse continue;
                const own_group = ((try self.semanticAttribute(tag, "group")) orelse "");
                try self.referenceDefinitionsInner(content[tag.end..pair.inner_end], if (own_group.len != 0) own_group else default_group, depth + 1, true);
                pos = pair.end;
                continue;
            }
            if (!tag.closing and tag.isOpaque() and !tag.is("ref")) {
                pos = if (opaque_scan.pair(content, tag)) |pair| pair.end else tag.end;
                continue;
            }
            if (tag.closing or !tag.is("ref")) continue;
            const pair = opaque_scan.pair(content, tag) orelse continue;
            const name = ((try self.semanticAttribute(tag, "name")) orelse "");
            if (name.len == 0) {
                pos = pair.end;
                continue;
            }
            const own_group = ((try self.semanticAttribute(tag, "group")) orelse "");
            const group = if (own_group.len != 0) own_group else default_group;
            const body = if (tag.self_closing) "" else content[tag.end..pair.inner_end];
            var found = false;
            for (self.ref_defs.items) |*definition| {
                if (!std.mem.eql(u8, definition.name, name) or !std.mem.eql(u8, definition.group, group)) continue;
                if (definition.body.len == 0 and body.len != 0) {
                    definition.body = body;
                    definition.missing = if (self.body_missing) |parent| try missingSlice(self.a, parent, body) else MissingText.untracked(body);
                    definition.list_defined = list_defined;
                }
                found = true;
                break;
            }
            if (!found) {
                if (self.ref_defs.items.len >= max_nodes) {
                    self.fallbacks.render_limit = true;
                    return;
                }
                try self.ref_defs.append(self.a, .{ .name = name, .group = group, .body = body, .missing = if (self.body_missing) |parent| try missingSlice(self.a, parent, body) else MissingText.untracked(body), .list_defined = list_defined });
            }
            for (self.refs.items) |*ref| {
                if (std.mem.eql(u8, ref.name, name) and std.mem.eql(u8, ref.group, group) and ref.body.len == 0 and body.len != 0) {
                    ref.body = body;
                    ref.missing = if (self.body_missing) |parent| try missingSlice(self.a, parent, body) else MissingText.untracked(body);
                }
            }
            pos = pair.end;
        }
    }
    pub fn finishReferences(self: *Renderer) Error![]const Reference {
        self.in_reference = true;
        defer self.in_reference = false;
        for (self.refs.items) |*ref| {
            const previous_depth = self.poem_depth;
            const previous_direction = self.poem_direction;
            const previous_style = self.poem_base_style;
            const previous_indent = self.poem_line_indent;
            self.poem_depth = if (ref.poem) 1 else 0;
            self.poem_direction = ref.poem_direction;
            self.poem_base_style = .{};
            self.poem_line_indent = 0;
            defer {
                self.poem_depth = previous_depth;
                self.poem_direction = previous_direction;
                self.poem_base_style = previous_style;
                self.poem_line_indent = previous_indent;
            }
            ref.spans = try self.parseSpansWithMissing(if (ref.body.len != 0) ref.missing orelse MissingText.transformed(ref.body) else MissingText.untracked("Reference text unavailable"), .{});
        }
        return self.refs.items;
    }
    fn gallery(self: *Renderer, input: []const u8, tag: syntax.Tag, style: Style, _: usize) Error!void {
        var lines = std.mem.splitScalar(u8, input, '\n');
        var emitted = false;
        // Gallery-wide captions are separately parsed extension attributes, not
        // filenames or one of the per-item media captions.
        if (try self.semanticAttribute(tag, "caption")) |caption| {
            if (trim(caption).len != 0) {
                if (self.media_depth >= max_depth) {
                    self.fallbacks.render_limit = true;
                    try self.protectedLiteral(caption, style);
                    emitted = true;
                } else {
                    self.media_depth += 1;
                    defer self.media_depth -= 1;
                    const caption_spans = try self.parseSpans(caption, style);
                    try self.spans.appendSlice(self.a, caption_spans);
                    emitted = caption_spans.len != 0;
                }
            }
        }
        while (lines.next()) |raw_line| {
            const line = trim(raw_line);
            if (line.len == 0) continue;
            const pipe = syntax.delimiter(line, "|", 0);
            const raw_file = trim(line[0 .. pipe orelse line.len]);
            const colon = std.mem.indexOfScalar(u8, raw_file, ':');
            const file = if (colon != null and self.namespaceOfTarget(raw_file) == 6) raw_file[colon.? + 1 ..] else raw_file;
            if (media_types.referencedKind(file) == null) continue;
            const options = if (pipe) |at_pipe| trim(line[at_pipe + 1 ..]) else "";
            const selected_label = self.mediaCaptionChoice(options, file, mediaOptionMode(file, true));
            const caption = selected_label.text;
            var media_style = style;
            media_style.classes = try self.mediaCaptionClasses("", style.classes);
            media_style = try self.mediaActionStyle(media_style, file, selected_label.link_target);
            const visible_label = if (caption.len == 0) file else caption;
            const caption_style: ?MediaCaptionCapture = if (std.mem.eql(u8, caption, visible_label)) .{ .style = mediaCaptionStyle(media_style, false, selected_label.authored_caption) } else null;
            const parsed = try self.mediaFileKindWithSpans(file, caption, null, caption_style);
            media_style.classes = try self.mediaCaptionClasses(try self.mediaClasses(file), style.classes);
            if (emitted) try self.lineBreak(style);
            emitted = true;
            try self.mediaLabel(visible_label, media_style, false, selected_label.authored_caption, false, parsed);
        }
    }
    fn imageMap(self: *Renderer, input: []const u8, style: Style, depth: usize) Error!bool {
        var pos: usize = 0;
        var image_seen = false;
        while (pos < input.len) {
            const end = syntax.logicalEnd(input, pos);
            var line = trim(input[pos..end]);
            pos = if (end < input.len) end + 1 else end;
            while (starts(line, "<!--")) {
                const comment_end = syntax.protectedEnd(line, 0) orelse line.len;
                line = trim(line[comment_end..]);
            }
            if (line.len == 0 or line[0] == '#') continue;
            if (!image_seen) {
                const pipe = syntax.delimiter(line, "|", 0) orelse line.len;
                const target = trim(line[0..pipe]);
                if (self.namespaceOfTarget(target) != 6) return false;
                const colon = std.mem.indexOfScalar(u8, target, ':') orelse return false;
                if (media_types.referencedKind(trim(target[colon + 1 ..])) != .image) return false;
                const wrapped = try std.fmt.allocPrint(self.a, "[[{s}]]", .{line});
                const wrapped_pair = syntax.balanced(wrapped, 0) orelse return false;
                if (wrapped_pair.end != wrapped.len) return false;
                try self.inlineText(wrapped, style, depth + 1);
                image_seen = true;
                continue;
            }
            const space = std.mem.indexOfAny(u8, line, " \t") orelse {
                self.fallbacks.unsupported_element = true;
                continue;
            };
            if (std.mem.eql(u8, line[0..space], "desc")) {
                if (!oneOf(trim(line[space..]), &.{ "top-left", "top-right", "bottom-left", "bottom-right", "none" })) self.fallbacks.unsupported_element = true;
                continue;
            }
            if (!oneOf(line[0..space], &.{ "rect", "circle", "poly", "default" })) {
                self.fallbacks.unsupported_element = true;
                continue;
            }
            const link_at = syntax.delimiter(line, "[", space) orelse {
                self.fallbacks.unsupported_element = true;
                continue;
            };
            var coordinates = std.mem.tokenizeAny(u8, line[space..link_at], " \t");
            var count: usize = 0;
            var valid = true;
            while (coordinates.next()) |coordinate| {
                const number = std.fmt.parseFloat(f64, coordinate) catch {
                    valid = false;
                    break;
                };
                if (!std.math.isFinite(number)) valid = false;
                count += 1;
            }
            const command = line[0..space];
            valid = valid and (if (std.mem.eql(u8, command, "rect")) count == 4 else if (std.mem.eql(u8, command, "circle")) count == 3 else if (std.mem.eql(u8, command, "poly")) count >= 6 and count % 2 == 0 else count == 0);
            if (!valid) {
                self.fallbacks.unsupported_element = true;
                continue;
            }
            const internal = starts(line[link_at..], "[[");
            var link_end: usize = undefined;
            var inner_end: usize = undefined;
            if (internal) {
                const pair = syntax.balanced(line, link_at) orelse {
                    self.fallbacks.unsupported_element = true;
                    continue;
                };
                link_end = pair.end;
                inner_end = pair.inner_end;
            } else {
                var cursor = link_at + 1;
                while (cursor < line.len and line[cursor] != ']') {
                    if (syntax.protectedEnd(line, cursor)) |protected_end| cursor = protected_end else cursor += 1;
                }
                if (cursor == line.len) {
                    self.fallbacks.unsupported_element = true;
                    continue;
                }
                inner_end = cursor;
                link_end = cursor + 1;
            }
            var trailing = trim(line[link_end..]);
            while (starts(trailing, "<!--")) trailing = trim(trailing[(syntax.protectedEnd(trailing, 0) orelse trailing.len)..]);
            if (trailing.len != 0) {
                self.fallbacks.unsupported_element = true;
                continue;
            }
            const body = line[link_at + (if (internal) @as(usize, 2) else 1) .. inner_end];
            const separator = if (internal) syntax.delimiter(body, "|", 0) orelse body.len else std.mem.indexOfAny(u8, body, " \t") orelse body.len;
            const target = trim(body[0..separator]);
            const label = if (separator < body.len) trim(body[separator + 1 ..]) else target;
            if (if (internal) target.len == 0 or !safeInternalTarget(target) else !safeUrl(try self.entityText(target))) {
                self.fallbacks.unsupported_element = true;
                continue;
            }
            try self.lineBreak(style);
            try self.link(label, target, style, depth + 1, !internal);
        }
        return image_seen;
    }
    // This is a complete, deliberately small TeX subset. An unbraced
    // superscript consumes one token: 10^12 must not become 10^{12}.
    fn numericPower(self: *Renderer, content: []const u8, style: Style) Error!bool {
        var base_end: usize = 0;
        while (base_end < content.len and std.ascii.isDigit(content[base_end])) : (base_end += 1) {}
        if (base_end == 0 or base_end == content.len or content[base_end] != '^') return false;
        const suffix = content[base_end + 1 ..];
        var exponent = suffix;
        if (suffix.len >= 2 and suffix[0] == '{' and suffix[suffix.len - 1] == '}') {
            exponent = suffix[1 .. suffix.len - 1];
            if (exponent.len == 0) return false;
            for (exponent) |digit| if (!std.ascii.isDigit(digit)) return false;
        } else if (suffix.len != 1 or !std.ascii.isDigit(suffix[0])) return false;

        // No output is emitted until the entire input has matched.
        try self.protectedLiteral(content[0..base_end], style);
        var power_style = style;
        power_style.superscript = true;
        try self.protectedLiteral(exponent, power_style);
        return true;
    }
    // Statistics/lexical examples need a product of ASCII variables, not a
    // general TeX interpreter. A bare exponent consumes exactly one digit.
    // Braces admit only a signed integer or a signed numerator/positive denominator.
    fn monomialExponent(content: []const u8, cursor: *usize) ?[]const u8 {
        var at = cursor.*;
        if (at >= content.len) return null;
        if (std.ascii.isDigit(content[at])) {
            cursor.* = at + 1;
            return content[at .. at + 1];
        }
        if (content[at] != '{') return null;
        at += 1;
        const start = at;
        if (at < content.len and (content[at] == '+' or content[at] == '-')) at += 1;
        const digits = at;
        while (at < content.len and std.ascii.isDigit(content[at])) : (at += 1) {}
        if (at == digits) return null;
        if (at < content.len and content[at] == '/') {
            at += 1;
            const denominator = at;
            var nonzero = false;
            while (at < content.len and std.ascii.isDigit(content[at])) : (at += 1) {
                nonzero = nonzero or content[at] != '0';
            }
            if (at == denominator or !nonzero) return null;
        }
        if (at >= content.len or content[at] != '}') return null;
        cursor.* = at + 1;
        return content[start..at];
    }

    fn monomial(self: *Renderer, content: []const u8, style: Style) Error!bool {
        var coefficient_end: usize = 0;
        if (content.len != 0 and (content[0] == '+' or content[0] == '-')) coefficient_end = 1;
        const digits = coefficient_end;
        while (coefficient_end < content.len and std.ascii.isDigit(content[coefficient_end])) : (coefficient_end += 1) {}
        if (digits != 0 and coefficient_end == digits) return false;
        var at = coefficient_end;
        var terms: usize = 0;
        while (at < content.len) {
            if (!std.ascii.isAlphabetic(content[at])) return false;
            at += 1;
            terms += 1;
            if (at < content.len and content[at] == '^') {
                at += 1;
                _ = monomialExponent(content, &at) orelse return false;
            }
        }
        if (terms == 0) return false;

        // Only after the entire monomial validates may any presentation be emitted.
        if (coefficient_end != 0) try self.protectedLiteral(content[0..coefficient_end], style);
        var variable_style = style;
        variable_style.italic = true;
        var power_style = style;
        power_style.superscript = true;
        at = coefficient_end;
        while (at < content.len) {
            try self.protectedLiteral(content[at .. at + 1], variable_style);
            at += 1;
            if (at < content.len and content[at] == '^') {
                at += 1;
                const exponent = monomialExponent(content, &at) orelse unreachable;
                try self.protectedLiteral(exponent, power_style);
            }
        }
        return true;
    }
    const InlineMathScript = enum { normal, sub, super };
    const InlineMathToken = struct { text: []const u8, italic: bool = false, script: InlineMathScript = .normal };
    const InlineMathParser = struct {
        a: std.mem.Allocator,
        input: []const u8,
        at: usize = 0,
        depth: usize = 0,
        tokens: std.ArrayList(InlineMathToken) = .empty,
        const Atom = struct { start: usize, wrap_for_script: bool = false };

        fn space(p: *@This()) void {
            while (p.at < p.input.len and std.ascii.isWhitespace(p.input[p.at])) : (p.at += 1) {}
        }
        fn put(p: *@This(), token_text: []const u8, italic: bool, script: InlineMathScript) Error!bool {
            if (p.tokens.items.len >= 1024) return false;
            try p.tokens.append(p.a, .{ .text = token_text, .italic = italic, .script = script });
            return true;
        }
        fn name(p: *@This()) []const u8 {
            const start = p.at;
            while (p.at < p.input.len and std.ascii.isAlphabetic(p.input[p.at])) : (p.at += 1) {}
            return p.input[start..p.at];
        }
        fn symbol(name_: []const u8) ?[]const u8 {
            const names = [_][]const u8{ "alpha", "beta", "gamma", "pi", "theta", "delta", "lambda", "mu", "Sigma", "Pi", "sum", "prod", "le", "neq", "pm", "dots", "ldots", "rightarrow", "leftrightarrows", "cdot" };
            const values = [_][]const u8{ "α", "β", "γ", "π", "θ", "δ", "λ", "μ", "Σ", "Π", "∑", "∏", "≤", "≠", "±", "…", "…", "→", "⇆", "·" };
            for (names, values) |key, value| if (std.mem.eql(u8, name_, key)) return value;
            return null;
        }
        fn group(p: *@This(), script: InlineMathScript) Error!bool {
            p.space();
            if (p.at == p.input.len or p.input[p.at] != '{') return false;
            p.at += 1;
            const start = p.tokens.items.len;
            return try p.sequence('}', false, script) and p.tokens.items.len != start;
        }
        fn argument(p: *@This(), script: InlineMathScript) Error!bool {
            p.space();
            if (p.at == p.input.len) return false;
            if (p.input[p.at] == '{') return p.group(script);
            // A bare argument is one TeX token, not a balanced visible group.
            // Keep these spellings unsupported rather than changing their scope.
            if (p.input[p.at] == '(' or p.input[p.at] == '[' or std.mem.startsWith(u8, p.input[p.at..], "\\left")) return false;
            if (std.ascii.isDigit(p.input[p.at])) {
                const digit = p.at;
                p.at += 1;
                // Preserve the existing conservative unsupported policy for ^12;
                // never reinterpret it as ^{12}. TeX itself means ^1 then baseline 2.
                if (p.at < p.input.len and std.ascii.isDigit(p.input[p.at])) return false;
                return p.put(p.input[digit..p.at], false, script);
