            if (ch == '(' or ch == '[') {
                p.at += 1;
                if (!try p.put(if (ch == '(') "(" else "[", false, script)) return null;
                if (!try p.sequence(if (ch == '(') ')' else ']', false, script)) return null;
                if (!try p.put(if (ch == '(') ")" else "]", false, script)) return null;
                return .{ .start = start };
            }
            if (ch == '\\') {
                p.at += 1;
                if (p.at == p.input.len) return null;
                if (p.input[p.at] == ',' or p.input[p.at] == ' ') {
                    const thin = p.input[p.at] == ',';
                    p.at += 1;
