    // Common captured inline mathematics, with an explicit linear rendering.
    // Unknown syntax is atomic: no presentation spans escape a failed parse.
    fn commonInlineMath(self: *Renderer, content: []const u8, style: Style) Error!bool {
        if (content.len == 0 or content.len > 4096) return false;
        var parser: InlineMathParser = .{ .a = self.a, .input = content };
        defer parser.tokens.deinit(self.a);
        if (!try parser.sequence(0, false, .normal) or parser.tokens.items.len == 0) return false;
        if (style.superscript or style.subscript) {
            for (parser.tokens.items) |token| if (token.script != .normal) return false;
        }
        var boundary_style = style;
        boundary_style.direction = "";
        boundary_style.italic = false;
        // One scope across all styled atoms; per-span direction isolates would
        // not establish the equation's order inside an RTL paragraph.
        try self.protectedLiteral("\xe2\x81\xa6", boundary_style);
        for (parser.tokens.items) |token| {
            var token_style = style;
            token_style.direction = "";
            token_style.italic = token.italic;
            token_style.superscript = token_style.superscript or token.script == .super;
            token_style.subscript = token_style.subscript or token.script == .sub;
            try self.protectedLiteral(token.text, token_style);
        }
        try self.protectedLiteral("\xe2\x81\xa9", boundary_style);
        return true;
    }

    // Sanitizer escapes unmatched registered extension openers before inline and
    // structural parsing. Matched scopes and nowiki remain opaque; allowed HTML
    // pre keeps its separate parsed whitespace/layout behavior.
    fn prepareUnmatchedOpaque(self: *Renderer, input: []const u8) Error![]const u8 {
        return (try self.prepareUnmatchedOpaqueWithMissing(MissingText.untracked(input))).bytes;
    }
    fn prepareUnmatchedOpaqueWithMissing(self: *Renderer, source: MissingText) Error!MissingText {
        const input = source.bytes;
        var opaque_scan: syntax.OpaqueScan = .{};
        var no_more_nowiki_close = false;
        var out: missing_dependency.Builder = .{};
        var heading_copies: std.ArrayList(HeadingSourceCopy) = .empty;
        defer heading_copies.deinit(self.a);
        errdefer out.deinit(self.a);
        var emitted: usize = 0;
        var scan: usize = 0;
        while (std.mem.indexOfScalarPos(u8, input, scan, '<')) |at| {
            if (starts(input[at..], "<!--")) {
                scan = opaque_scan.protectedEnd(input, at, &no_more_nowiki_close).?;
                continue;
            }
            const tag = opaque_scan.tagAt(input, at, &no_more_nowiki_close) orelse {
                scan = at + 1;
                continue;
            };
            scan = tag.end;
            if (tag.closing) continue;
            if (tag.is("includeonly")) {
                scan = if (syntax.matchingTag(input, tag)) |pair| pair.end else input.len;
                continue;
            }
            if (tag.is("nowiki")) {
                if (syntax.nowikiRegionAtCached(input, at, &no_more_nowiki_close)) |region| scan = region.end;
                continue;
            }
            if (!tag.isOpaque()) continue;
            if (opaque_scan.pair(input, tag)) |pair| {
                scan = pair.end;
                continue;
            }
            if (tag.is("pre")) continue;
            self.markUnclosed(input, tag, "literal-extension-opener");
            try self.appendMissingHeadingSourceCopy(&out, &heading_copies, source, emitted, at);
            try self.appendMissingHeadingSourceEdit(&out, &heading_copies, source, at, "&lt;");
            // The preprocessor made the whole unmatched opener literal before
            // expansion. Do not run fallback templates in its attributes later.
            for (input[at + 1 .. tag.end], at + 1..) |ch, byte_at| switch (ch) {
                '{' => try self.appendMissingHeadingSourceEdit(&out, &heading_copies, source, byte_at, "&#123;"),
                '}' => try self.appendMissingHeadingSourceEdit(&out, &heading_copies, source, byte_at, "&#125;"),
                else => try self.appendMissingHeadingSourceCopy(&out, &heading_copies, source, byte_at, byte_at + 1),
            };
            emitted = tag.end;
        }
        if (out.bytes.items.len == 0) return source;
        try self.appendMissingHeadingSourceCopy(&out, &heading_copies, source, emitted, input.len);
        const result = try out.finish(self.a);
        try self.registerHeadingSourceCopies(result.bytes, heading_copies.items);
        return result;
    }

    fn opaqueExtension(self: *Renderer, input: []const u8, tag: syntax.Tag, style: Style, depth: usize) Error!usize {
        return self.opaqueExtensionWithMissing(MissingText.untracked(input), tag, style, depth);
    }
    fn opaqueExtensionWithMissing(self: *Renderer, tracked: MissingText, tag: syntax.Tag, style: Style, depth: usize) Error!usize {
        const input = tracked.bytes;
        if (tag.self_closing) return tag.end;
        const matched_pair = syntax.matchingTag(input, tag);
        if (tag.html_pre or (tag.is("pre") and matched_pair == null)) {
            if (matched_pair == null) self.markUnclosed(input, tag, "opaque-extension");
            const parsed_pair = matched_pair orelse syntax.Pair{ .inner_end = input.len, .end = input.len };
            var parsed_style = style;
            parsed_style.code = true;
            parsed_style.preserve_whitespace = true;
            try self.inlineTextWithMissing(try missingSlice(self.a, tracked, input[tag.end..parsed_pair.inner_end]), parsed_style, depth + 1);
            return parsed_pair.end;
        }
        const pair = matched_pair orelse {
            self.markUnclosed(input, tag, "opaque-extension");
            const opening = @intFromPtr(tag.name.ptr) - @intFromPtr(input.ptr) - 1;
            try self.literal(input[opening..tag.end], style);
            return tag.end;
        };
        const content = input[tag.end..pair.inner_end];
        if (tag.is("math") and matched_pair != null and trim(tag.attrs).len == 0 and
            (try self.numericPower(content, style) or try self.monomial(content, style) or try self.commonInlineMath(content, style))) return pair.end;
        if (tag.is("hiero") and matched_pair != null and supportedHieroAttributes(tag.attrs)) {
            if (try hieroglyphs.decodeAlloc(self.a, content)) |glyphs| {
                var glyph_style = style;
                glyph_style.code = false;
                glyph_style.provenance = .protected_literal;
                glyph_style.language = "egy";
                glyph_style.direction = "ltr";
                glyph_style.classes = if (style.classes.len == 0) "Egyp" else try std.fmt.allocPrint(self.a, "{s} Egyp", .{style.classes});
                try self.text(glyphs, glyph_style);
                return pair.end;
            }
        }
        if (tag.is("gallery")) {
            try self.gallery(content, tag, style, depth + 1);
        } else if (tag.is("imagemap")) {
            if (!try self.imageMap(content, style, depth + 1)) self.fallbacks.unsupported_element = true;
        } else if (tag.is("poem")) {
            const opening = @intFromPtr(tag.name.ptr) - @intFromPtr(input.ptr) - 1;
            const prepared = if (self.poemItemBefore(input, opening)) |item| item.kind == .scope else false;
            try self.poemWithPhase(content, try self.htmlLanguageDirection(tag, style), depth + 1, prepared);
        } else if (oneOf(tag.name, &.{ "pre", "source", "syntaxhighlight", "math", "ce", "chem", "score", "timeline", "hiero" })) {
            var literal_style = style;
            literal_style.code = true;
            literal_style.preserve_whitespace = oneOf(tag.name, &.{ "pre", "source", "syntaxhighlight" });
            if (tag.is("source") or tag.is("syntaxhighlight")) {
                literal_style.provenance = .protected_literal;
                try self.text(content, literal_style);
            } else try self.protectedLiteral(content, literal_style);
            // Readable source is not rendered formula, score or diagram output.
            if (oneOf(tag.name, &.{ "math", "ce", "chem", "score", "timeline", "hiero" })) self.fallbacks.unsupported_element = true;
        } else if (!oneOf(tag.name, &.{ "indicator", "references", "templatestyles", "section", "charinsert" })) {
            // Registered extensions can render data-backed UI that this data-only
            // compiler cannot reproduce. Do not invent substitute prose; report
            // the omission so the final corpus audit names the affected page.
            self.fallbacks.unsupported_element = true;
        }
        return pair.end;
    }
    fn mediaCaptionClasses(self: *Renderer, owner: []const u8, parsed: []const u8) Error![]const u8 {
        var out: std.ArrayList(u8) = .empty;
        // Caption parsing can occur before or after the generated owner is
        // attached. In either case its inherited visual prefix is retained once.
        var visual = owner;
        while (visual.len != 0) {
            const end = std.mem.indexOfAny(u8, visual, " \t\r\n") orelse visual.len;
            const token = visual[0..end];
            if (!std.mem.eql(u8, token, "wikidict-media") and !std.mem.startsWith(u8, token, "wikidict-media-file-")) break;
