    // Split declarations at top-level semicolons only. Quoted font names,
    // escaped bytes and function bodies cannot create a color declaration.
    fn nextColorDeclaration(self: *Renderer, css: []const u8, pos: *usize) Error!?[]const u8 {
        if (pos.* >= css.len) return null;
        var out: std.ArrayList(u8) = .empty;
        defer out.deinit(self.a);
        var quote: u8 = 0;
        var depth: usize = 0;
        while (pos.* < css.len) {
            const byte = css[pos.*];
            pos.* += 1;
            if (byte == '\\' and pos.* < css.len) {
                try out.append(self.a, byte);
                try out.append(self.a, css[pos.*]);
                pos.* += 1;
                continue;
            }
            if (quote != 0) {
                try out.append(self.a, byte);
                if (byte == quote) quote = 0;
                continue;
            }
            if (byte == '\'' or byte == '"') {
                quote = byte;
                try out.append(self.a, byte);
                continue;
            }
            if (byte == '/' and pos.* < css.len and css[pos.*] == '*') {
                const close = std.mem.indexOfPos(u8, css, pos.* + 1, "*/") orelse {
                    pos.* = css.len;
                    break;
                };
                pos.* = close + 2;
                try out.append(self.a, ' ');
                continue;
            }
            if (byte == '(' or byte == '[' or byte == '{') depth += 1;
            if ((byte == ')' or byte == ']' or byte == '}') and depth != 0) depth -= 1;
            if (byte == ';' and depth == 0) break;
            try out.append(self.a, byte);
        }
        return try out.toOwnedSlice(self.a);
    }

    const AuthoredColor = struct { value: ?[]const u8, specified: bool = false };
    fn authoredColor(self: *Renderer, tag: syntax.Tag, property: []const u8, legacy: ?[]const u8, fallback: ?[]const u8) Error!AuthoredColor {
        var result: AuthoredColor = .{ .value = fallback };
        if (legacy) |attribute| if (try self.semanticAttribute(tag, attribute)) |raw| {
            result = .{ .value = try self.canonicalColor(raw), .specified = true };
        };
        const css = (try self.semanticAttribute(tag, "style")) orelse return result;
        var pos: usize = 0;
        var important_seen = false;
        while (try self.nextColorDeclaration(css, &pos)) |raw| {
            const colon = std.mem.indexOfScalar(u8, raw, ':') orelse continue;
            const name = trim(raw[0..colon]);
            const matches = std.ascii.eqlIgnoreCase(name, property);
            const background_reset = std.ascii.eqlIgnoreCase(property, "background-color") and
                std.ascii.eqlIgnoreCase(name, "background");
            if (!matches and !background_reset) continue;
            var value = trim(raw[colon + 1 ..]);
            var important = false;
            if (std.mem.lastIndexOfScalar(u8, value, '!')) |bang| {
                if (!std.ascii.eqlIgnoreCase(trim(value[bang + 1 ..]), "important")) continue;
                important = true;
                value = trim(value[0..bang]);
            }
            var next: ?[]const u8 = null;
            if (std.ascii.eqlIgnoreCase(value, "inherit") or std.ascii.eqlIgnoreCase(value, "unset") or
                std.ascii.eqlIgnoreCase(value, "currentcolor"))
            {
                next = if (std.ascii.eqlIgnoreCase(property, "color") or !std.ascii.eqlIgnoreCase(value, "currentcolor")) fallback else null;
            } else if (std.ascii.eqlIgnoreCase(value, "transparent") or std.ascii.eqlIgnoreCase(value, "initial") or
                (background_reset and std.ascii.eqlIgnoreCase(value, "none")))
            {
                next = if (std.ascii.eqlIgnoreCase(property, "background-color")) fallback else null;
            } else if (try self.canonicalColor(value)) |color| {
                // A single opaque color is also a complete supported shorthand.
                next = color;
            } else if (unrepresentedColorValue(value) or (background_reset and std.mem.indexOfAny(u8, value, " /\t") != null)) {
                // Valid dynamic/system/alpha or complex background values do
                // not have a supported opaque RGB projection. Suppress stale
                // prior color, without evaluating functions/images/layers.
                next = null;
            } else continue; // An invalid declaration has no cascade priority.
            if (important_seen and !important) continue;
            important_seen = important;
            result.specified = true;
            result.value = next;
        }
        return result;
    }

    fn unrepresentedColorValue(value: []const u8) bool {
        if (std.ascii.eqlIgnoreCase(value, "revert") or std.ascii.eqlIgnoreCase(value, "revert-layer")) return true;
        const system_names = .{ "accentcolor", "accentcolortext", "activetext", "buttonborder", "buttonface", "buttontext", "canvas", "canvastext", "field", "fieldtext", "graytext", "highlight", "highlighttext", "linktext", "mark", "marktext", "selecteditem", "selecteditemtext", "visitedtext", "activeborder", "activecaption", "appworkspace", "background", "buttonhighlight", "buttonshadow", "captiontext", "inactiveborder", "inactivecaption", "inactivecaptiontext", "infobackground", "infotext", "menu", "menutext", "scrollbar", "threeddarkshadow", "threedface", "threedhighlight", "threedlightshadow", "threedshadow", "window", "windowframe", "windowtext" };
        inline for (system_names) |name| if (std.ascii.eqlIgnoreCase(value, name)) return true;
        if (std.mem.indexOfScalar(u8, value, '(')) |open| {
            const name = trim(value[0..open]);
            inline for (.{ "rgb", "rgba", "hsl", "hsla", "hwb", "lab", "lch", "oklab", "oklch", "color", "color-mix", "light-dark", "contrast-color", "device-cmyk", "var", "env", "url", "linear-gradient", "radial-gradient", "conic-gradient", "repeating-linear-gradient", "repeating-radial-gradient", "repeating-conic-gradient" }) |supported_function| {
                if (std.ascii.eqlIgnoreCase(name, supported_function)) return true;
            }
        }
        return false;
    }

    fn tableCellBackground(self: *Renderer, tag: syntax.Tag, fallback: ?[]const u8) Error!?[]const u8 {
        return (try self.authoredColor(tag, "background-color", "bgcolor", fallback)).value;
    }

    fn canonicalSwatchHex(self: *Renderer, raw: []const u8) Error!?[]const u8 {
        const value = trim(raw);
        if (value.len != 7 or value[0] != '#') return null;
        for (value[1..]) |byte| if (!std.ascii.isHex(byte)) return null;
        const result = try self.a.dupe(u8, value);
        for (result) |*byte| byte.* = std.ascii.toLower(byte.*);
        return result;
    }

    // Boolean HTML attributes are present even without '=' or a value.
    // Keep valued-attribute semantics elsewhere unchanged; swatch recognition
    // must refuse hidden containers rather than infer their visible color.
    fn swatchHasAttribute(self: *Renderer, original: syntax.Tag, key: []const u8) Error!bool {
        const tag = try self.normalizedTag(original);
        var i: usize = 0;
        while (i < tag.attrs.len) {
            while (i < tag.attrs.len and (std.ascii.isWhitespace(tag.attrs[i]) or tag.attrs[i] == '/')) : (i += 1) {}
            const start = i;
            while (i < tag.attrs.len and !std.ascii.isWhitespace(tag.attrs[i]) and tag.attrs[i] != '=' and tag.attrs[i] != '/') : (i += 1) {}
            if (i == start) {
                i += 1;
                continue;
            }
            if (std.ascii.eqlIgnoreCase(tag.attrs[start..i], key)) return true;
            while (i < tag.attrs.len and std.ascii.isWhitespace(tag.attrs[i])) : (i += 1) {}
            if (i == tag.attrs.len or tag.attrs[i] != '=') continue;
            i += 1;
            while (i < tag.attrs.len and std.ascii.isWhitespace(tag.attrs[i])) : (i += 1) {}
            if (i == tag.attrs.len) break;
            const quote = tag.attrs[i];
            const quoted = quote == '\'' or quote == '"';
            if (quoted) i += 1;
            while (i < tag.attrs.len and (if (quoted) tag.attrs[i] != quote else !std.ascii.isWhitespace(tag.attrs[i]))) : (i += 1) {}
            if (quoted and i < tag.attrs.len) i += 1;
        }
        return false;
    }

    // Only the explicit literal-hex declarations needed to identify a swatch.
    // Complex CSS, shorthand backgrounds and duplicate relevant declarations
    // are not evidence. Attribute/entity handling stays in the ordinary parser.
    fn swatchCssHex(self: *Renderer, tag: syntax.Tag, property: []const u8) Error!?[]const u8 {
        if ((try self.semanticAttribute(tag, "bgcolor")) != null or (try self.semanticAttribute(tag, "class")) != null or (try self.swatchHasAttribute(tag, "hidden"))) return null;
        const css = (try self.semanticAttribute(tag, "style")) orelse return null;
        if (std.mem.indexOfAny(u8, css, "'\"(){}[]\\!") != null or
            std.mem.indexOf(u8, css, "/*") != null or std.mem.indexOf(u8, css, "*/") != null) return null;
        var color: ?[]const u8 = null;
        var declarations = std.mem.splitScalar(u8, css, ';');
        while (declarations.next()) |raw| {
            const declaration = trim(raw);
            if (declaration.len == 0) continue;
            const colon = std.mem.indexOfScalar(u8, declaration, ':') orelse return null;
            const name = trim(declaration[0..colon]);
            if (std.ascii.eqlIgnoreCase(name, "background") or std.ascii.eqlIgnoreCase(name, "background-image")) return null;
            if (std.ascii.eqlIgnoreCase(property, "color") and
                (std.ascii.eqlIgnoreCase(name, "background-color") or std.ascii.eqlIgnoreCase(name, "background-image"))) return null;
            if (std.ascii.eqlIgnoreCase(name, property)) {
                if (color != null) return null;
                color = (try self.canonicalSwatchHex(declaration[colon + 1 ..])) orelse return null;
            } else if (std.ascii.eqlIgnoreCase(property, "background-color")) {
                // Retain the captured swatch's simple decoration and dimensions;
                // unknown CSS may suppress or transform the visible sample.
                if (!oneOf(name, &.{ "border", "height", "width", "float" })) return null;
            } else {
                const value = trim(declaration[colon + 1 ..]);
                if (std.ascii.eqlIgnoreCase(name, "font-size")) {
                    if (!std.ascii.eqlIgnoreCase(value, "x-large")) return null;
                } else if (std.ascii.eqlIgnoreCase(name, "text-align")) {
                    if (!std.ascii.eqlIgnoreCase(value, "center")) return null;
                } else return null;
            }
        }
        return color;
    }

    fn swatchCellSourceAllowed(self: *Renderer, input: []const u8) Error!bool {
        var cursor: usize = 0;
        while (std.mem.indexOfScalarPos(u8, input, cursor, '<')) |open| {
            const tag = try self.semanticTagAt(input, open) orelse return false;
            if (!tag.is("span") or (try self.semanticAttribute(tag, "class")) != null or (try self.swatchHasAttribute(tag, "hidden"))) return false;
            if (try self.semanticAttribute(tag, "style")) |css| {
                // Inline color/background declarations would override the
                // explicit cell color; do not evaluate their cascade.
                var declarations = std.mem.splitScalar(u8, css, ';');
                while (declarations.next()) |raw| {
                    if (trim(raw).len == 0) continue;
                    const colon = std.mem.indexOfScalar(u8, raw, ':') orelse return false;
                    const name = trim(raw[0..colon]);
                    const value = trim(raw[colon + 1 ..]);
                    if (!std.ascii.eqlIgnoreCase(name, "font-family") or
                        (!std.ascii.eqlIgnoreCase(value, "monospaced") and !std.ascii.eqlIgnoreCase(value, "monospace"))) return false;
                }
            }
            cursor = tag.end;
        }
        return true;
    }

    fn swatchFeature(self: *Renderer, table: Table, background: ?[]const u8, foreground: ?[]const u8) Error!?Feature {
        const bg = background orelse return null;
        const fg = foreground orelse return null;
        if (self.truncated or !std.mem.eql(u8, bg, fg) or table.caption.len != 0 or table.rows.len != 1 or table.rows[0].cells.len != 1) return null;
        const cell = table.rows[0].cells[0];
        if (cell.header or cell.colspan != 1 or cell.rowspan != 1) return null;
        for (cell.spans) |span| if (span.kind != .text or span.target.len != 0) return null;
        const content = (try self.canonicalSwatchHex(try plainText(self.a, cell.spans))) orelse return null;
        if (!std.mem.eql(u8, bg, content)) return null;
        return .{ .kind = "color_swatch", .data = bg };
    }

    fn htmlSwatchFeature(self: *Renderer, tag: syntax.Tag, input: []const u8, table: Table, fostered: []const Block) Error!?Feature {
        if (fostered.len != 0) return null;
        const background = try self.swatchCssHex(tag, "background-color");
        const cell = nextHtmlTableCell(input, 0) orelse return null;
        const cell_pair = optionalTableEnd(input, cell.tag);
        if (!try self.swatchCellSourceAllowed(input[cell.tag.end..cell_pair.inner_end])) return null;
        // Row/group/column or other pre-cell containers can alter the sample.
        // Refuse their attributes rather than evaluate CSS inheritance/cascade.
        var pos: usize = 0;
        while (std.mem.indexOfScalarPos(u8, input[0..cell.open], pos, '<')) |open| {
            const row_tag = try self.semanticTagAt(input, open) orelse {
                pos = open + 1;
                continue;
            };
            if (!row_tag.closing and ((try self.semanticAttribute(row_tag, "style")) != null or (try self.semanticAttribute(row_tag, "bgcolor")) != null or (try self.semanticAttribute(row_tag, "class")) != null or (try self.swatchHasAttribute(row_tag, "hidden")))) return null;
            pos = row_tag.end;
        }
        return self.swatchFeature(table, background, try self.swatchCssHex(cell.tag, "color"));
    }

    const ChemicalStackCss = enum { outer, upper, lower };

    // Exact captured Su layout only. This is not a general CSS layout engine:
    // every declaration, its order, and the absence of other attributes matter.
    fn chemicalStackCss(self: *Renderer, tag: syntax.Tag, kind: ChemicalStackCss) Error!bool {
        if (!tag.is("span") or tag.closing or tag.self_closing) return false;
        const attrs = trim(tag.attrs);
        const eq = std.mem.indexOfScalar(u8, attrs, '=') orelse return false;
        if (!std.ascii.eqlIgnoreCase(trim(attrs[0..eq]), "style")) return false;
        const quoted = trim(attrs[eq + 1 ..]);
        if (quoted.len < 2 or (quoted[0] != '"' and quoted[0] != '\'') or quoted[quoted.len - 1] != quoted[0]) return false;
        if (std.mem.indexOfScalar(u8, quoted[1 .. quoted.len - 1], quoted[0]) != null) return false;
        const css = (try self.semanticAttribute(tag, "style")) orelse return false;
        const expected: []const []const u8 = switch (kind) {
            .outer => &.{ "font-size:80%", "display:-moz-inline-box", "-moz-box-orient:vertical", "display:inline-block", "vertical-align:bottom", "margin-bottom:-0.4em", "min-height:1em", "line-height:1em" },
            .upper => &.{ "display:block", "min-height:1em", "margin-top:-1.4em" },
            .lower => &.{ "display:block", "min-height:1em" },
        };
        var index: usize = 0;
        var alignment = false;
        var declarations = std.mem.splitScalar(u8, css, ';');
        while (declarations.next()) |raw| {
            var declaration = trim(raw);
            while (starts(declaration, "/*")) {
                const close = std.mem.indexOf(u8, declaration[2..], "*/") orelse return false;
                declaration = trim(declaration[close + 4 ..]);
            }
            if (declaration.len == 0) continue;
            const colon = std.mem.indexOfScalar(u8, declaration, ':') orelse return false;
            const name = trim(declaration[0..colon]);
            const value = trim(declaration[colon + 1 ..]);
            if (index == expected.len) {
                if (kind != .outer or alignment or !std.ascii.eqlIgnoreCase(name, "text-align") or
                    (!std.ascii.eqlIgnoreCase(value, "right") and !std.ascii.eqlIgnoreCase(value, "center"))) return false;
                alignment = true;
                continue;
            }
            const wanted = expected[index];
            const separator = std.mem.indexOfScalar(u8, wanted, ':').?;
            if (!std.ascii.eqlIgnoreCase(name, wanted[0..separator]) or !std.ascii.eqlIgnoreCase(value, wanted[separator + 1 ..])) return false;
            index += 1;
        }
        return index == expected.len;
    }

    fn chemicalScriptDigits(value: []const u8) bool {
        if (value.len == 0 or value.len > 64) return false;
        for (value) |ch| if (!std.ascii.isDigit(ch)) return false;
        return true;
    }

    fn chemicalScriptCharge(value: []const u8) bool {
        const sign_len: usize = if (std.mem.endsWith(u8, value, "−")) "−".len else if (std.mem.endsWith(u8, value, "+") or std.mem.endsWith(u8, value, "-")) 1 else return false;
        const magnitude = value[0 .. value.len - sign_len];
        return magnitude.len == 0 or chemicalScriptDigits(magnitude);
    }

    // Captured Module:chemical formula/styles.css defines this exact paired
    // class as a two-line inline stack. Do not interpret arbitrary CSS classes.
    fn chemicalStackClass(self: *Renderer, tag: syntax.Tag) Error!bool {
        if (!tag.is("span") or tag.closing or tag.self_closing) return false;
        const attrs = trim(tag.attrs);
        const eq = std.mem.indexOfScalar(u8, attrs, '=') orelse return false;
        if (!std.ascii.eqlIgnoreCase(trim(attrs[0..eq]), "class")) return false;
        const quoted = trim(attrs[eq + 1 ..]);
        if (quoted.len < 2 or (quoted[0] != '"' and quoted[0] != '\'') or quoted[quoted.len - 1] != quoted[0]) return false;
        if (std.mem.indexOfScalar(u8, quoted[1 .. quoted.len - 1], quoted[0]) != null) return false;
        return std.mem.eql(u8, (try self.semanticAttribute(tag, "class")) orelse return false, "template-chem2-su");
    }

    fn chemicalScriptStack(self: *Renderer, content: []const u8, tag: syntax.Tag, style: Style) Error!bool {
        // The chemical wrapper establishes the count/charge interpretation.
        // Do not reorder actions, arbitrary stacks, or already-scripted scopes.
        if (style.kind != .text or style.target.len != 0 or style.superscript or style.subscript or
            self.block_formatting.superscript or self.block_formatting.subscript) return false;
        var chemical = false;
        var classes = std.mem.tokenizeAny(u8, style.classes, " \t\r\n");
        while (classes.next()) |class| chemical = chemical or std.mem.eql(u8, class, "chemf");
        if (!chemical) return false;
        const class_stack = try self.chemicalStackClass(tag);
        if (!class_stack and !try self.chemicalStackCss(tag, .outer)) return false;
        const children = trim(content);
        const upper = try self.semanticTagAt(children, 0) orelse return false;
        if (class_stack) {
            if (!upper.is("span") or upper.closing or upper.self_closing or trim(upper.attrs).len != 0) return false;
        } else if (!try self.chemicalStackCss(upper, .upper)) return false;
        const upper_pair = syntax.matchingTag(children, upper) orelse return false;
        const rest = trim(children[upper_pair.end..]);
        const lower = try self.semanticTagAt(rest, 0) orelse return false;
        if (class_stack) {
            if (!lower.is("span") or lower.closing or lower.self_closing or trim(lower.attrs).len != 0) return false;
        } else if (!try self.chemicalStackCss(lower, .lower)) return false;
        const lower_pair = syntax.matchingTag(rest, lower) orelse return false;
        if (trim(rest[lower_pair.end..]).len != 0) return false;
        const charge = try self.entityText(children[upper.end..upper_pair.inner_end]);
        const count = try self.entityText(rest[lower.end..lower_pair.inner_end]);
        if (!chemicalScriptCharge(charge) or !chemicalScriptDigits(count)) return false;
        // Conventional chemical linear order is count below, charge above.
        // Existing readers expose these roles; no same-x pixel stack is claimed.
        var count_style = style;
        count_style.subscript = true;
        var charge_style = style;
        charge_style.superscript = true;
        try self.text(count, count_style);
        try self.text(charge, charge_style);
        return true;
    }

    fn htmlInlineStyle(self: *Renderer, tag: syntax.Tag, style: Style) Error!Style {
        var s = style;
        if (!tag.is("table")) s.background = (try self.authoredColor(tag, "background-color", null, style.background)).value;
        if (oneOf(tag.name, &.{ "b", "strong" })) s.bold = true;
        if (oneOf(tag.name, &.{ "i", "em", "cite", "var", "dfn" })) s.italic = true;
        if (tag.is("u") or tag.is("ins")) s.underline = true;
        if (oneOf(tag.name, &.{ "s", "del", "strike" })) s.strike = true;
        if (tag.is("sup")) s.superscript = true;
        if (tag.is("sub")) s.subscript = true;
        if (tag.is("small")) s.small = true;
        if (oneOf(tag.name, &.{ "code", "tt", "kbd", "samp" })) s.code = true;
        if (try self.htmlFontWeight(tag)) |bold| s.bold = bold;
        if (try self.htmlFontStyle(tag)) |italic| s.italic = italic;
        if ((try self.semanticAttribute(tag, "class"))) |classes| {
            const decoded_classes = classes;
            var safe_classes: std.ArrayList(u8) = .empty;
            defer safe_classes.deinit(self.a);
            var tokens = std.mem.tokenizeAny(u8, decoded_classes, " \t\r\n");
            while (tokens.next()) |class| {
                var safe = class.len != 0;
                for (class) |c| if (!(std.ascii.isAlphanumeric(c) or c == '_' or c == '-')) {
                    safe = false;
                    break;
                };
                // Media ownership is compiler-generated metadata, never an authored CSS capability.
                if (!safe or std.mem.startsWith(u8, class, "wikidict-media-file-")) continue;
                if (safe_classes.items.len != 0) try safe_classes.append(self.a, ' ');
                try safe_classes.appendSlice(self.a, class);
                if (std.mem.eql(u8, class, "scribunto-error")) self.fallbacks.rendered_lua_error = true;
                if (std.mem.eql(u8, class, "ext-phonos-error")) self.fallbacks.rendered_extension_error = true;
                if (std.mem.eql(u8, class, "headword-line") or std.mem.eql(u8, class, "headword")) s.role = .headword;
                if (s.role != .headword and (std.mem.eql(u8, class, "label-content") or std.mem.eql(u8, class, "qualifier-content"))) s.role = .label;
                if (std.mem.eql(u8, class, "IPA")) s.role = .pronunciation;
                if (std.mem.eql(u8, class, "e-example")) s.role = .example;
                if (std.mem.eql(u8, class, "nyms")) {
                    if (self.semantic_capture) |hints| hints.relation_note = true;
                }
            }
            if (safe_classes.items.len != 0) {
                s.classes = if (s.classes.len == 0)
                    try self.a.dupe(u8, safe_classes.items)
                else
                    try std.fmt.allocPrint(self.a, "{s} {s}", .{ s.classes, safe_classes.items });
            }
        }
        // Only authored abbreviation titles are semantic explanations. An
        // explicit empty title clears inherited meaning; missing titles inherit.
        if (tag.is("abbr")) if (try self.semanticAttribute(tag, "title")) |explanation| {
            s.explanation = explanation;
            s.explanation_set = true;
        };
        return self.htmlLanguageDirection(tag, s);
    }
    // Module:etymon/tree emits child-first fragments, not nested HTML lists.
    // Validate that small structural grammar before compiling any visible body.
    // The hidden etymon JSON is deliberately not another presentation source.
    const EtymologyTreeNode = struct {
        raw: []const u8,
        prefix: []const u8 = "",
        style: Style = .{},
        scopes: []const syntax.Tag,
        children: []const usize,
        height: usize,
        spans: []const Span = &.{},
        relation_note: bool = false,
        group: bool = false,
    };
    const EtymologyTreePlan = struct {
        renderer: *Renderer,
        nodes: std.ArrayList(EtymologyTreeNode) = .empty,
        limited: bool = false,

        fn hasClass(self: *EtymologyTreePlan, tag: syntax.Tag, wanted: []const u8) Error!bool {
            const classes = (try self.renderer.semanticAttribute(tag, "class")) orelse return false;
            var tokens = std.mem.tokenizeAny(u8, classes, " \t\r\n");
            while (tokens.next()) |value| if (std.mem.eql(u8, value, wanted)) return true;
            return false;
        }
        fn skipSpaceAndComments(input: []const u8, cursor: *usize) bool {
            while (cursor.* < input.len) {
                if (std.ascii.isWhitespace(input[cursor.*])) {
                    cursor.* += 1;
                } else if (starts(input[cursor.*..], "<!--")) {
                    cursor.* = syntax.protectedEnd(input, cursor.*) orelse return false;
                } else break;
            }
            return true;
        }
        fn addNode(self: *EtymologyTreePlan, raw: []const u8, prefix: []const u8, scopes: []const syntax.Tag, children: []const usize, group: bool) Error!?usize {
            var height: usize = 1;
            for (children) |child| height = @max(height, self.nodes.items[child].height + 1);
            if (self.nodes.items.len >= 1024 or height >= max_depth) {
                self.limited = true;
                return null;
            }
            const index = self.nodes.items.len;
            try self.nodes.append(self.renderer.a, .{ .raw = raw, .prefix = prefix, .scopes = scopes, .children = children, .height = height, .group = group });
            return index;
        }
        fn extendScopes(self: *EtymologyTreePlan, scopes: []const syntax.Tag, tag: syntax.Tag) Error![]const syntax.Tag {
            const extended = try self.renderer.a.alloc(syntax.Tag, scopes.len + 1);
            @memcpy(extended[0..scopes.len], scopes);
            extended[scopes.len] = tag;
            return extended;
        }
        fn groupLabel(self: *EtymologyTreePlan, input: []const u8) Error!bool {
            var cursor: usize = 0;
            if (!skipSpaceAndComments(input, &cursor)) return false;
            const tag = try self.renderer.semanticTagAt(input, cursor) orelse return false;
            if (tag.closing or !tag.is("span") or !(try self.hasClass(tag, "etytree-group-label"))) return false;
            const pair = syntax.matchingTag(input, tag) orelse return false;
            cursor = pair.end;
            return skipSpaceAndComments(input, &cursor) and cursor == input.len;
        }
        fn branches(self: *EtymologyTreePlan, input: []const u8, scopes: []const syntax.Tag, depth: usize) Error!?[]const usize {
            if (depth >= max_depth) {
                self.limited = true;
                return null;
            }
            var roots: std.ArrayList(usize) = .empty;
            var cursor: usize = 0;
            var columns: usize = 0;
            while (cursor < input.len) {
                if (!skipSpaceAndComments(input, &cursor)) return null;
                if (cursor == input.len) break;
                const tag = try self.renderer.semanticTagAt(input, cursor) orelse return null;
                if (tag.closing or !tag.is("div") or !(try self.hasClass(tag, "etytree-branch"))) return null;
                const pair = syntax.matchingTag(input, tag) orelse return null;
                const child_scopes = try self.extendScopes(scopes, tag);
                const children = (try self.sequence(input[tag.end..pair.inner_end], child_scopes, depth + 1, true)) orelse return null;
                try roots.appendSlice(self.renderer.a, children);
                columns += 1;
                cursor = pair.end;
            }
            if (columns < 2) return null;
            return try roots.toOwnedSlice(self.renderer.a);
        }
        fn sequence(self: *EtymologyTreePlan, input: []const u8, scopes: []const syntax.Tag, depth: usize, branch_tail: bool) Error!?[]const usize {
            if (depth >= max_depth) {
                self.limited = true;
                return null;
            }
            var roots: std.ArrayList(usize) = .empty;
            var needs_parent = false;
            var tail_stage: enum { none, short, done } = .none;
            var prefix: []const u8 = "";
            var cursor: usize = 0;
            while (cursor < input.len) {
                if (!skipSpaceAndComments(input, &cursor)) return null;
                if (cursor == input.len) break;
                if (tail_stage == .done) return null;
                const at = cursor;
                const tag = try self.renderer.semanticTagAt(input, at) orelse return null;
                if (tag.closing or (!tag.is("div") and !tag.is("span"))) return null;
                const pair = syntax.matchingTag(input, tag) orelse return null;
                const content = input[tag.end..pair.inner_end];
                if (tail_stage == .short and !(tag.is("span") and try self.hasClass(tag, "etytree-branch-mid"))) return null;
                const scoped_tags = try self.extendScopes(scopes, tag);
                if (tag.is("div") and try self.hasClass(tag, "etytree-block")) {
                    if (roots.items.len != 0 and !needs_parent) return null;
                    const children = try roots.toOwnedSlice(self.renderer.a);
                    const child = (try self.addNode(content, prefix, scoped_tags, children, false)) orelse return null;
                    try roots.append(self.renderer.a, child);
                    prefix = "";
                    needs_parent = false;
                } else if (tag.is("div") and try self.hasClass(tag, "etytree-branch-group")) {
                    if (roots.items.len != 0 or prefix.len != 0) return null;
                    const children = (try self.branches(content, scoped_tags, depth + 1)) orelse return null;
                    try roots.appendSlice(self.renderer.a, children);
                    needs_parent = true;
                } else if (tag.is("span") and ((try self.hasClass(tag, "etytree-connector-vertical")) or
                    (try self.hasClass(tag, "etytree-connector-dotted"))))
                {
                    if (roots.items.len == 0 or prefix.len != 0) return null;
                    if (trim(content).len != 0) {
                        if (!(try self.groupLabel(content))) return null;
                        const children = try roots.toOwnedSlice(self.renderer.a);
                        const child = (try self.addNode(content, "", scoped_tags, children, true)) orelse return null;
                        try roots.append(self.renderer.a, child);
                    }
                    needs_parent = true;
                } else if (tag.is("span") and ((try self.hasClass(tag, "etytree-branch-left")) or
                    (try self.hasClass(tag, "etytree-branch-right")) or
                    (try self.hasClass(tag, "etytree-branch-mid")) or
                    (try self.hasClass(tag, "etytree-connector-vertical-short"))))
                {
                    if (!branch_tail or roots.items.len == 0 or trim(content).len != 0) return null;
                    // A container may supply a forest or a labelled group to
                    // the shared parent outside this branch column.
                    if (try self.hasClass(tag, "etytree-connector-vertical-short")) {
                        if (tail_stage != .none) return null;
                        tail_stage = .short;
                    } else {
                        if ((try self.hasClass(tag, "etytree-branch-mid")) != (tail_stage == .short)) return null;
                        tail_stage = .done;
                    }
                } else if (tag.is("div") and try self.hasClass(tag, "etytree-duplicate-connector")) {
                    // This marker means ancestry was hidden. Keep its visible
                    // arrow, never invent the hidden nodes or another edge.
                    if (roots.items.len != 0 or prefix.len != 0) return null;
                    prefix = input[at..pair.end];
                } else return null;
                cursor = pair.end;
            }
            if (prefix.len != 0 or roots.items.len == 0) return null;
            if (branch_tail) {
                if (tail_stage != .done) return null;
            } else if (roots.items.len != 1 or needs_parent) return null;
            return try roots.toOwnedSlice(self.renderer.a);
        }
    };

    fn etymologyTreeSpans(self: *Renderer, node_value: EtymologyTreeNode) Error![]const Span {
        var spans: std.ArrayList(Span) = .empty;
        if (node_value.prefix.len != 0) {
            const parsed_prefix = try self.parseSpans(node_value.prefix, node_value.style);
            var end = parsed_prefix.len;
            while (end != 0 and parsed_prefix[end - 1].kind == .line_break) end -= 1;
            try spans.appendSlice(self.a, parsed_prefix[0..end]);
        }
        const parsed = try self.parseSpans(node_value.raw, node_value.style);
        var prefix_boundary = spans.items.len != 0;
        var separated_label = false;
        for (parsed) |span| {
            var label = false;
            var tokens = std.mem.tokenizeAny(u8, span.classes, " \t\r\n");
            while (tokens.next()) |value| label = label or std.mem.eql(u8, value, "etytree-label-container");
            var separate = label and !separated_label;
            if (prefix_boundary) {
                if (span.kind == .line_break) prefix_boundary = false else if (span.text.len != 0) {
                    separate = separate or !std.ascii.isWhitespace(span.text[0]);
                    prefix_boundary = false;
                }
            }
            if (separate and spans.items.len != 0 and !formattingVisibleEndsSpace(spans.items)) {
                var separator = span;
                separator.kind = .text;
                separator.text = " ";
                separator.target = "";
                try spans.append(self.a, separator);
            }
            if (label) separated_label = true;
            try spans.append(self.a, span);
        }
        return try spans.toOwnedSlice(self.a);
    }
    fn emitEtymologyTree(self: *Renderer, blocks: *std.ArrayList(Block), nodes: []const EtymologyTreeNode, index: usize, parent_path: []const u8) Error!void {
        const node_value = nodes[index];
        const path = try std.fmt.allocPrint(self.a, "{s}*", .{parent_path});
        try self.appendBlockBudgeted(blocks, .{ .kind = .list_item, .depth = @intCast(path.len), .list_path = path, .spans = node_value.spans, .relation_note = node_value.relation_note });
        for (node_value.children) |child| {
            if (self.truncated) break;
            try self.emitEtymologyTree(blocks, nodes, child, path);
        }
    }
    fn appendEtymologyTree(self: *Renderer, blocks: *std.ArrayList(Block), input: []const u8, tag: syntax.Tag) Error!bool {
        if (!tag.is("div") or self.pre_block or self.parsed_pre) return false;
        var plan: EtymologyTreePlan = .{ .renderer = self };
        if (!(try plan.hasClass(tag, "etytree-body"))) return false;
        const roots = (try plan.sequence(input, &.{tag}, 0, false)) orelse {
            if (plan.limited) self.fallbacks.render_limit = true;
            return false;
        };
        // Indices are in source DOM order, including group labels after their
        // terms. Register content effects once before projecting parent-first.
        for (plan.nodes.items) |*node_value| {
            var hints: SemanticHints = .{ .relation_note = self.body_formatting_attributes.relation_note };
            const previous_capture = self.semantic_capture;
            self.semantic_capture = &hints;
            defer self.semantic_capture = previous_capture;
            const parent_italic = self.block_formatting.italic;
            const parent_poem_italic = self.poem_base_style.italic;
            defer self.block_formatting.italic = parent_italic;
            defer self.poem_base_style.italic = parent_poem_italic;
            var node_style = self.bodyFormattingStyle(self.body_language_direction orelse .{});
            for (node_value.scopes) |scope_tag| {
                node_style = try self.htmlInlineStyle(scope_tag, node_style);
                if (try self.htmlFontStyle(scope_tag)) |italic| {
                    self.block_formatting.italic = italic;
                    if (self.poem_depth != 0) self.poem_base_style.italic = italic;
                }
            }
            node_value.style = node_style;
            node_value.spans = try self.etymologyTreeSpans(node_value.*);
            node_value.relation_note = hints.relation_note;
        }
        try self.emitEtymologyTree(blocks, plan.nodes.items, roots[0], "");
        return true;
    }

    const BidiScope = struct { opening: []const u8, closing: []const u8 = "\xe2\x81\xa9", automatic: bool = false };
    const unicode_bidi = @import("unicode_bidi.zig");

    fn firstBidiDirection(spans: []const Span) unicode_bidi.Direction {
        for (spans) |span| {
            if (span.bidi_auto_excluded) continue;
            var characters = (std.unicode.Utf8View.init(span.text) catch continue).iterator();
            while (characters.nextCodepoint()) |cp| if (unicode_bidi.strongDirection(cp)) |direction| return direction;
        }
        return .ltr; // HTML auto/undefined BDI with no strong descendant text.
    }

    fn validBidiDirection(self: *Renderer, tag: syntax.Tag) Error!bool {
        const raw = (try self.semanticAttribute(tag, "dir")) orelse return false;
        return std.ascii.eqlIgnoreCase(raw, "ltr") or std.ascii.eqlIgnoreCase(raw, "rtl") or std.ascii.eqlIgnoreCase(raw, "auto");
    }

    fn compiledBidiScope(self: *Renderer, tag: syntax.Tag) Error!?BidiScope {
        const raw = try self.semanticAttribute(tag, "dir");
        const direction: []const u8 = if (raw) |value|
            if (std.ascii.eqlIgnoreCase(value, "ltr")) "ltr" else if (std.ascii.eqlIgnoreCase(value, "rtl")) "rtl" else if (std.ascii.eqlIgnoreCase(value, "auto")) "auto" else ""
        else
            "";
        if (tag.is("bdo")) {
            if (std.mem.eql(u8, direction, "ltr")) return .{ .opening = "\xe2\x81\xa6\xe2\x80\xad", .closing = "\xe2\x80\xac\xe2\x81\xa9" };
            if (std.mem.eql(u8, direction, "rtl")) return .{ .opening = "\xe2\x81\xa7\xe2\x80\xae", .closing = "\xe2\x80\xac\xe2\x81\xa9" };
            return null; // Do not invent override semantics for an invalid/missing direction.
        }
        // BDI defaults to auto, not its DOM parent's direction. Explicit child
        // dir scopes inside a compiled bidi scope also span all styled atoms.
        if (!tag.is("bdi") and (self.bidi_scope_depth == 0 or direction.len == 0)) return null;
        return .{
            .opening = if (std.mem.eql(u8, direction, "rtl")) "\xe2\x81\xa7" else "\xe2\x81\xa6",
            .automatic = direction.len == 0 or std.mem.eql(u8, direction, "auto"),
        };
    }

    fn bidiBoundary(value: []const u8, neighbor: Span) Span {
        var result = neighbor;
        result.text = value;
        result.kind = .text;
        result.target = "";
        result.direction = "";
        result.explanation = "";
        result.explanation_set = false;
        result.provenance = .protected_literal;
        result.generated_bidi_boundary = true;
        // Retain layout classes (especially Poem) without creating an action.
        return result;
    }

    fn bidiSeparatorLength(value: []const u8) usize {
        if (value.len == 0) return 0;
        if (value[0] == '\n' or value[0] == '\r') return 1;
        if (starts(value, "\xe2\x80\xa8") or starts(value, "\xe2\x80\xa9")) return 3;
        return 0;
    }

    fn wrapBidiSpans(self: *Renderer, start: usize, scope: BidiScope) Error!void {
        const original = self.spans.items[start..];
        // Resolve auto once over the whole element, not once per output line.
        // Descendant text has already been decoded; raw link targets and HTML
        // attributes are not scan input. Authored Unicode isolates are not DOM
        // exclusions: their L/R/AL text still participates in this HTML rule.
        const opening: []const u8 = if (scope.automatic)
            if (firstBidiDirection(original) == .rtl) "\xe2\x81\xa7" else "\xe2\x81\xa6"
        else
            scope.opening;
        var wrapped: std.ArrayList(Span) = .empty;
        defer wrapped.deinit(self.a);
        var opened = false;
        var last: Span = .{ .text = "" };
        // Children have already consumed their normal budget. Build the entire
        // balanced replacement first; shortage preserves those children and
        // reports a limit, rather than dropping a generated PDF/PDI later.
        const maximum = original.len + (max_nodes -| self.nodes);
        for (original) |span| {
            if (span.text.len == 0) try wrapped.append(self.a, span);
            var offset: usize = 0;
            while (offset < span.text.len) {
                const separator = bidiSeparatorLength(span.text[offset..]);
                if (separator != 0 or span.kind == .line_break) {
                    if (opened) {
                        try wrapped.append(self.a, bidiBoundary(scope.closing, last));
                        opened = false;
                    }
                    var part = span;
                    const length = if (span.kind == .line_break) span.text.len - offset else separator;
                    part.text = span.text[offset .. offset + length];
                    try wrapped.append(self.a, part);
                    offset += length;
                } else {
                    var end = offset + 1;
                    while (end < span.text.len and bidiSeparatorLength(span.text[end..]) == 0) : (end += 1) {}
                    if (!opened) {
                        try wrapped.append(self.a, bidiBoundary(opening, span));
                        opened = true;
                    }
                    var part = span;
                    part.text = span.text[offset..end];
                    try wrapped.append(self.a, part);
                    last = part;
                    offset = end;
                }
                if (wrapped.items.len + @intFromBool(opened) > maximum) {
                    self.fallbacks.render_limit = true;
                    return;
                }
            }
        }
        if (opened) try wrapped.append(self.a, bidiBoundary(scope.closing, last));
        self.nodes += wrapped.items.len -| original.len;
        self.spans.items.len = start;
        try self.spans.appendSlice(self.a, wrapped.items);
    }

    fn htmlTag(self: *Renderer, input: []const u8, at: usize, style: Style, depth: usize, no_more_nowiki_close: ?*bool, opaque_scan: *syntax.OpaqueScan) Error!?usize {
        return self.htmlTagWithMissing(MissingText.untracked(input), at, style, depth, no_more_nowiki_close, opaque_scan);
    }
    // Normalize rejected nowiki angles in the complete tracked inline stream.
    // Keep link/quote context continuous across the visible tag boundary.
    fn literalNowikiAnglesSourceWithMissing(self: *Renderer, tracked: MissingText) Error!MissingText {
        const input = tracked.bytes;
        var out: missing_dependency.Builder = .{};
        errdefer out.deinit(self.a);
        var emitted: usize = 0;
        var scan: usize = 0;
        var opaque_scan: syntax.OpaqueScan = .{};
        while (std.mem.indexOfScalarPos(u8, input, scan, '<')) |at| {
            if (opaque_scan.protectedEnd(input, at, null)) |end| {
                scan = end;
                continue;
            }
            var literal_end: ?usize = null;
            if (opaque_scan.tagAt(input, at, null)) |tag| {
                if (tag.is("nowiki") and tag.closing) literal_end = tag.end;
                // Never reinterpret a tag's attributes as independent source.
                scan = tag.end;
            } else {
                scan = at + 1;
                const rest = input[at..];
                // Exactly the adjacent-slash boundary refused by the scanner.
                if (rest.len > "<nowiki/".len and std.ascii.startsWithIgnoreCase(rest, "<nowiki/") and rest["<nowiki/".len] != '>') {
                    if (std.mem.indexOfAny(u8, rest["<nowiki/".len..], "<>")) |relative| {
                        const end = at + "<nowiki/".len + relative + 1;
                        if (input[end - 1] == '>') literal_end = end;
                    }
                }
            }
            if (literal_end) |end| {
                try out.appendSlice(self.a, tracked, emitted, at);
                try out.append(self.a, missingEdit(tracked, at, at + 1, "&lt;"));
                try out.appendSlice(self.a, tracked, at + 1, end - 1);
