                        const generated_label = label_value.len == 0;
                        if (generated_label) label_value = pipeTrickLabel(target);
                        if (safeInternalTarget(target)) {
                            if (self.navigation_target_probe) |result| {
                                // A media caption or malformed outer label can
                                // reach this same branch recursively. Only the
                                // exact candidate root may establish its scope.
                                if (input.ptr == self.navigation_probe_source.ptr and
                                    input.len == self.navigation_probe_source.len and
                                    token_start == 0 and it.cursor == input.len)
                                {
                                    result.* = target;
                                    return;
                                }
                            }
                            const destination = try self.interwikiDestination(target, 0);
                            const action_style = try self.wikiLinkStyle(s, destination);
                            if (!token.link_has_pipe or generated_label) {
                                // Decoded default and generated labels are title text, not another wikitext input.
                                try self.text(label_value, action_style);
                            } else if (destination.external) {
