    fn appendBlockBudgeted(self: *Renderer, list: *std.ArrayList(Block), value: Block) Error!void {
        if (self.spend()) {
            try list.append(self.a, value);
            return;
        }
        if (self.block_limit_reached) return;
        self.block_limit_reached = true;
        try list.append(self.a, value);
    }
    fn protectedBlock(self: *Renderer, list: *std.ArrayList(Block), raw: []const u8, decode_entities: bool) Error!void {
        const parent = self.spans;
        self.spans = .empty;
        defer self.spans = parent;
        if (decode_entities) {
            try self.protectedLiteral(raw, self.bodyFormattingStyle(.{ .code = true, .preserve_whitespace = true }));
        } else try self.text(raw, self.bodyFormattingStyle(.{ .code = true, .provenance = .protected_literal, .preserve_whitespace = true }));
        try self.appendBlockBudgeted(list, .{ .kind = .preformatted, .spans = try self.spans.toOwnedSlice(self.a) });
    }
    fn block(self: *Renderer, list: *std.ArrayList(Block), kind: Kind, raw: []const u8, path: []const u8, number: []const u8, level: u8) Error!void {
        var hints: SemanticHints = .{
            .relation_note = self.body_formatting_attributes.relation_note,
            .ordinary_paragraph = kind == .paragraph and !self.parsed_pre,
        };
        const parent_capture = self.semantic_capture;
        self.semantic_capture = &hints;
        defer self.semantic_capture = parent_capture;
        const spans = if (kind == .preformatted) blk: {
            const parent = self.spans;
            self.spans = .empty;
            defer self.spans = parent;
            try self.literal(raw, self.bodyFormattingStyle(.{ .code = true }));
            break :blk try self.spans.toOwnedSlice(self.a);
        } else try self.parseBodySpans(raw, .{ .heading = kind == .heading });
        // MediaWiki opens list furniture from the authored marker even when
        // comments leave the item body empty. Keep its existing path/number.
        const list_furniture = path.len != 0 and switch (kind) {
            .list_item, .definition, .example, .quotation, .term, .list_detail, .indent => true,
            else => false,
        };
        if (spans.len == 0 and kind != .heading and kind != .blank and kind != .rule and !list_furniture) return;
        const heading_source_offset: ?usize = if (kind == .heading) self.headingSourceOffset(raw) else null;
        try self.appendBlockBudgeted(list, .{ .kind = kind, .text = raw, .spans = spans, .depth = @intCast(@min(path.len, 255)), .list_path = path[0..@min(path.len, 255)], .number = number, .level = level, .relation_note = hints.relation_note, .heading_source_offset = heading_source_offset });
    }
    fn paragraphWithQuoteSeed(self: *Renderer, list: *std.ArrayList(Block), text_value: []const u8, seed: ?QuoteSeed) Error!void {
        const previous = self.next_quote_seed;
        self.next_quote_seed = seed;
        defer self.next_quote_seed = previous;
        try self.paragraph(list, text_value);
    }
    fn paragraph(self: *Renderer, list: *std.ArrayList(Block), text_value: []const u8) Error!void {
        if (self.parsed_pre) {
            if (text_value.len != 0) try self.appendBlockBudgeted(list, .{ .kind = .preformatted, .spans = try self.parseBodySpans(text_value, .{ .code = true, .preserve_whitespace = true }) });
            return;
        }
        if (trim(text_value).len == 0) return;
        var kind: Kind = .paragraph;
        const value = trim(text_value);
        if (starts(value, "{{")) if (syntax.balanced(value, 0)) |pair| {
            if (syntax.Template.parse(self.a, value[2..pair.inner_end])) |t| {
                if (oneOf(t.name, &.{ "ux", "uxi", "uxa", "usex", "co", "coi", "coa" })) kind = .example;
                if (starts(t.name, "quote-")) kind = .quotation;
            } else |err| switch (err) {
                error.RenderLimit => {},
                else => return err,
            }
