        try self.block(list, kind, value, "", "", 0);
    }
    fn blockFormattingFlags(tag: syntax.Tag) ?SpanFlags {
        // Flags identify formatting wrappers; their attributes use the same
        // sanitized style helper as the ordinary inline HTML path.
        if (tag.closing or tag.self_closing) return null;
        if (tag.is("abbr")) return .{};
        if (oneOf(tag.name, &.{ "b", "strong" })) return .{ .bold = true };
        if (oneOf(tag.name, &.{ "i", "em", "cite", "var", "dfn" })) return .{ .italic = true };
        if (oneOf(tag.name, &.{ "u", "ins" })) return .{ .underline = true };
        if (oneOf(tag.name, &.{ "s", "del", "strike" })) return .{ .strike = true };
        if (tag.is("sup")) return .{ .superscript = true };
        if (tag.is("sub")) return .{ .subscript = true };
        if (tag.is("small")) return .{ .small = true };
        if (oneOf(tag.name, &.{ "code", "tt", "kbd", "samp" })) return .{ .code = true };
        return null;
    }
    fn formattingBlankBoundary(input: []const u8, leading: bool) bool {
        var count: usize = 0;
        var offset: usize = 0;
        while (offset < input.len) : (offset += 1) {
            const byte = input[if (leading) offset else input.len - offset - 1];
            if (byte == '\n') {
                count += 1;
                if (count == 2) return true;
            } else if (byte != ' ' and byte != '\t' and byte != '\r') break;
        }
        return false;
    }
    fn formattingAttributes(self: *Renderer) FormattingAttributes {
        var value = self.body_formatting_attributes;
        if (self.body_language_direction) |style| {
            value.language = style.language;
            value.direction = style.direction;
            if (style.foreground_set or style.foreground != null) {
                value.foreground = style.foreground;
                value.foreground_set = style.foreground_set;
            }
            if (style.explanation_set or style.explanation.len != 0) {
                value.explanation = style.explanation;
                value.explanation_set = style.explanation_set;
            }
        }
        return value;
    }
    fn restoreFormattingAttributes(self: *Renderer, value: FormattingAttributes) void {
        self.body_formatting_attributes = value;
        self.body_language_direction = .{ .language = value.language, .direction = value.direction, .explanation = value.explanation, .explanation_set = value.explanation_set, .foreground = value.foreground, .foreground_set = value.foreground_set };
    }
    fn formattingSeparator(self: *Renderer) Span {
        const value = self.formattingAttributes();
        return .{ .text = " ", .flags = self.block_formatting, .classes = value.classes, .role = value.role, .language = value.language, .direction = value.direction, .explanation = value.explanation, .explanation_set = value.explanation_set, .foreground = value.foreground, .foreground_set = value.foreground_set };
    }
    fn formattingVisibleEndsSpace(spans: []const Span) bool {
        var at = spans.len;
        while (at != 0) {
            at -= 1;
            if (spans[at].kind == .line_break) return true;
            const visible_text = spans[at].text;
            if (visible_text.len != 0) return std.ascii.isWhitespace(visible_text[visible_text.len - 1]);
        }
        return false;
    }

    pub fn isPureColorSwatchPrefix(self: *Renderer, source: []const u8) Error!bool {
        var cursor: usize = 0;
        var table_source: ?[]const u8 = null;
        while (cursor < source.len) {
            if (std.ascii.isWhitespace(source[cursor])) {
                cursor += 1;
                continue;
            }
            if (starts(source[cursor..], "<!--")) {
                const end = std.mem.indexOfPos(u8, source, cursor + 4, "-->") orelse return false;
                cursor = end + 3;
                continue;
            }
            const control = if (self.context.behavior_switches) |registry| try registry.matchAt(self.a, source, cursor) else syntax.behaviorSwitchEnd(source, cursor);
            if (control) |end| {
                cursor = end;
                continue;
            }
            if (table_source != null) return false;
            const begin = cursor;
            if (starts(source[cursor..], "{|")) {
                if (cursor != 0 and source[cursor - 1] != '\n') return false;
                var at = syntax.logicalEnd(source, cursor);
                var close: ?usize = null;
                while (at < source.len) {
                    at += 1;
                    const end = syntax.logicalEnd(source, at);
                    if (starts(trim(source[at..end]), "|}")) {
                        const line = trim(source[at..end]);
                        close = @intFromPtr(line.ptr) - @intFromPtr(source.ptr) + 2;
                        break;
                    }
                    at = end;
                }
                cursor = close orelse return false;
            } else {
                const tag = try self.semanticTagAt(source, cursor) orelse return false;
                if (!tag.is("table") or tag.closing or tag.self_closing) return false;
                const pair = syntax.matchingTag(source, tag) orelse return false;
                cursor = pair.end;
            }
            table_source = source[begin..cursor];
        }
        const table = table_source orelse return false;
        const blocks = try self.renderBody(table);
        if (self.fallbacks.any() or self.truncated or self.refs.items.len != 0 or self.media.items.len != 0 or blocks.len != 1 or blocks[0].kind != .table) return false;
        const feature = blocks[0].feature orelse return false;
        return std.mem.eql(u8, feature.kind, "color_swatch");
    }

    pub fn renderBody(self: *Renderer, source: []const u8) Error![]const Block {
        return self.renderBodyWithMissing(MissingText.untracked(source));
    }
    pub fn renderBodyWithMissing(self: *Renderer, tracked: MissingText) Error![]const Block {
