        const previous_pre = self.parsed_pre;
        const previous_block_pre = self.pre_block;
        const previous_formatting = self.block_formatting;
        const previous_attributes = self.formattingAttributes();
        const previous_attribute_storage = self.body_formatting_attributes;
        const previous_language_direction = self.body_language_direction;
        const previous_link = self.body_link_target;
        defer {
            self.body_link_target = previous_link;
            self.parsed_pre = previous_pre;
            self.pre_block = previous_block_pre;
            self.block_formatting = previous_formatting;
            self.body_formatting_attributes = previous_attribute_storage;
            self.body_language_direction = previous_language_direction;
        }
        self.body_link_target = previous_link;
        for (context.initial) |scope| if (scope.kind == .link) {
            self.body_link_target = scope.target;
            break;
        };
        self.pre_block = context.initial_block_pre;
        self.parsed_pre = inherited_pre != 0;
        self.block_formatting = if (context.initial.len != 0) context.initial[0].formatting else previous_formatting;
        if (context.initial.len != 0) self.restoreFormattingAttributes(context.initial[0].attributes);
        if (context.initial.len == 0 and context.trailing.len == 0)
            return self.renderBodySlice(input, false, false, null, context.quote);
        var active_quote: ?QuoteSeed = context.quote;
        for (context.initial) |scope| if (scope.kind == .link) {
            active_quote = scope.quote orelse try labelQuoteSeedWithContext(self.a, input[0..scope.body_end], self.context);
            break;
        };
        var quote_base: usize = 0;
        var quotes = QuoteBoundaryScan.initWithContext(input, active_quote, self.context);
        var blocks: std.ArrayList(Block) = .empty;
        var cursor: usize = 0;
        var initial_at: usize = 0;
        var trailing_at: usize = 0;
        var open_pre = inherited_pre;
        var join_inline = false;
        var join_separator: ?bool = null;
        while (initial_at < context.initial.len or trailing_at < context.trailing.len) {
            const close_at = if (initial_at < context.initial.len) context.initial[initial_at].body_end else input.len;
            const open_at = if (trailing_at < context.trailing.len) context.trailing[trailing_at].opening_start else input.len;
            const closing = initial_at < context.initial.len and close_at <= open_at;
            const boundary = if (closing) close_at else open_at;
            if (boundary == input.len) break; // end/end is a continuing scope, not a real closer.
            self.parsed_pre = open_pre != 0;
            try self.appendFragmentPreSlice(&blocks, input, cursor, boundary, join_inline, join_separator, try quotes.at(self.a, cursor - quote_base, self.context.behavior_switches));
            const resume_at = if (closing) context.initial[initial_at].resume_at else context.trailing[trailing_at].body_start;
            const same_line = boundary != 0 and input[boundary - 1] != '\n' and std.mem.indexOfScalar(u8, input[boundary..resume_at], '\n') == null;
            if (closing) {
                const scope = context.initial[initial_at];
                if (scope.kind == .link) try self.appendLinkContinuation(&blocks, input[scope.body_end + 2 .. scope.resume_at], scope.target);
                initial_at += 1;
                if (scope.kind == .link) {
                    self.body_link_target = previous_link;
                    for (context.initial[initial_at..]) |outer| if (outer.kind == .link) {
                        self.body_link_target = outer.target;
                        break;
                    };
                    // The label's apostrophes cannot alter the surrounding line.
                    quote_base = scope.resume_at;
                    quotes = QuoteBoundaryScan.initWithContext(input[quote_base..], scope.resume_quote, self.context);
                }
                if (scope.kind == .pre) {
                    open_pre -= 1;
                    self.pre_block = false;
                }
                self.block_formatting = if (initial_at < context.initial.len) context.initial[initial_at].formatting else previous_formatting;
                self.restoreFormattingAttributes(if (initial_at < context.initial.len) context.initial[initial_at].attributes else previous_attributes);
            } else {
                const scope = context.trailing[trailing_at];
                trailing_at += 1;
                if (scope.kind == .link) {
                    self.body_link_target = scope.target;
                    quote_base = scope.body_start;
                    const entry = scope.quote orelse try labelQuoteSeedWithContext(self.a, input[quote_base..], self.context);
                    quotes = QuoteBoundaryScan.initWithContext(input[quote_base..], entry, self.context);
                }
                if (scope.kind == .pre) {
                    open_pre += 1;
                    self.pre_block = true;
                }
                self.block_formatting = scope.formatting;
                self.restoreFormattingAttributes(scope.attributes);
            }
            const formatting_scope = if (closing) context.initial[initial_at - 1].kind == .formatting else context.trailing[trailing_at - 1].kind == .formatting;
            const formatting_join = formatting_scope and blocks.items.len != 0 and blocks.items[blocks.items.len - 1].kind == .paragraph and
                !formattingBlankBoundary(input[cursor..boundary], false) and !formattingBlankBoundary(input[resume_at..], true);
            const body_space = boundary > cursor and std.ascii.isWhitespace(input[boundary - 1]);
            cursor = resume_at;
            join_inline = formatting_join or (closing and same_line and (open_pre != 0 or context.initial[initial_at - 1].kind == .link));
            join_separator = if (formatting_join) body_space or (cursor < input.len and std.ascii.isWhitespace(input[cursor])) else null;
            // The actual block closer consumes its following LF. It does not
            // synthesize an ordinary blank paragraph at the fragment boundary.
            if (closing and open_pre == 0 and cursor < input.len and input[cursor] == '\n') {
                cursor += 1;
                if (!formatting_join) join_inline = false;
                if (formatting_join) join_separator = true;
            }
        }
        self.parsed_pre = open_pre != 0;
        try self.appendFragmentPreSlice(&blocks, input, cursor, input.len, join_inline, join_separator, try quotes.at(self.a, cursor - quote_base, self.context.behavior_switches));
        return blocks.toOwnedSlice(self.a);
    }

    fn appendFragmentPreSlice(self: *Renderer, blocks: *std.ArrayList(Block), source: []const u8, start: usize, end: usize, join_inline: bool, join_separator: ?bool, seed: QuoteSeed) Error!void {
        if (start == end) return;
        const initial_inline = start != 0 and source[start - 1] != '\n';
        const terminal_inline = end < source.len and source[end - 1] != '\n';
        const rendered = try self.renderBodySlice(source[start..end], initial_inline, terminal_inline, null, seed);
        var first: usize = 0;
        if (join_inline and blocks.items.len != 0 and rendered.len != 0 and
            (rendered[0].kind == .paragraph or (join_separator == null and rendered[0].kind == .preformatted)))
        {
            const previous = &blocks.items[blocks.items.len - 1];
            if (previous.kind != .heading and previous.kind != .rule and previous.kind != .blank and previous.table == null) {
                const leading = rendered[0];
                const separator = if (join_separator) |requested| requested and !formattingVisibleEndsSpace(previous.spans) else (!self.parsed_pre and start < end and source[start] != '\n' and std.ascii.isWhitespace(source[start]));
                const spans = try self.a.alloc(Span, previous.spans.len + @intFromBool(separator) + leading.spans.len);
                @memcpy(spans[0..previous.spans.len], previous.spans);
                var next = previous.spans.len;
                if (separator) {
                    spans[next] = self.formattingSeparator();
                    next += 1;
                }
                @memcpy(spans[next..], leading.spans);
                previous.spans = spans;
                previous.text = try std.fmt.allocPrint(self.a, "{s}{s}", .{ previous.text, leading.text });
                previous.relation_note = previous.relation_note or leading.relation_note;
                first = 1;
            }
        }
        try blocks.appendSlice(self.a, rendered[first..]);
    }

    const BodyLink = struct { opening_start: usize, body_start: usize, body_end: usize, resume_at: usize, target: []const u8, trail: []const u8, refused: bool = false };

    // Resolve the exact raw candidate through the ordinary internal-link branch.
    // Probe output and namespace/media effects stay in a temporary arena.
    const BodyLinkAdmission = struct { target: ?[]const u8, refused: bool };
    fn bodyLinkAdmission(self: *Renderer, raw: []const u8) Error!BodyLinkAdmission {
        var arena = std.heap.ArenaAllocator.init(self.a);
        defer arena.deinit();
        var resolved: ?[]const u8 = null;
        var refused = false;
        var probe: Renderer = .{ .a = arena.allocator(), .context = self.context, .navigation_target_probe = &resolved, .navigation_refused_probe = &refused, .navigation_probe_source = raw };
        try probe.inlineText(raw, .{}, 0);
        return .{ .target = if (resolved) |target| try self.a.dupe(u8, target) else null, .refused = refused };
    }

    // Only the current root-inline domain may own a block-spanning link.
    // A cell/list parser retains its own source limits; do not search through it.
    fn bodyLinkAt(self: *Renderer, input: []const u8, start: usize, opaque_scan: *syntax.OpaqueScan) Error!?BodyLink {
        const line_end = std.mem.indexOfScalarPos(u8, input, start, '\n') orelse input.len;
        var nesting: [max_depth][]const u8 = undefined;
        var count: usize = 0;
        var at = start;
        while (at < line_end) {
            if (input[at] == '<') {
                if (opaque_scan.protectedEnd(input, at, null)) |end| {
                    at = end;
                    continue;
                }
                if (opaque_scan.tagAt(input, at, null)) |tag| {
                    if (syntax.pairedHtmlTag(tag.name) or tag.html_pre or oneOf(tag.name, &.{ "li", "dt", "dd" })) {
                        if (tag.closing) {
                            if (count != 0 and std.ascii.eqlIgnoreCase(nesting[count - 1], tag.name)) count -= 1;
                        } else if (!tag.self_closing) {
                            if (count == nesting.len) return null;
                            nesting[count] = tag.name;
                            count += 1;
                        }
                    }
                    at = tag.end;
                    continue;
                }
            }
            if (starts(input[at..], "{{") or starts(input[at..], "[[")) {
                if (syntax.balancedWithOpaqueScan(input, at, opaque_scan)) |pair| {
                    if (count == 0 and starts(input[at..], "[[")) {
                        var it: ir.InlineIterator = .{ .input = input[at..], .renderer_boundaries = true, .link_trail = self.context.link_trail };
                        if (it.next()) |token| {
                            if (token.kind == .link and token.link_has_pipe and std.mem.indexOfScalar(u8, token.text, '\n') != null) {
                                const admission = try self.bodyLinkAdmission(input[at .. at + it.cursor]);
                                if (admission.target != null or admission.refused) {
                                    const body_start = @intFromPtr(token.text.ptr) - @intFromPtr(input.ptr);
                                    return .{ .opening_start = at, .body_start = body_start, .body_end = body_start + token.text.len, .resume_at = at + it.cursor, .target = admission.target orelse "", .trail = token.trail, .refused = admission.refused };
                                }
                            }
                        }
                    }
                    at = pair.end;
                    continue;
                }
            }
            at += 1;
        }
        return null;
    }

    // Raw-domain continuation spans grow geometrically and transfer once.
    // Completed paragraphs retain stable slices without cumulative prefix copies.
    const BodyParagraphJoin = struct {
        blocks: ?*std.ArrayList(Block) = null,
        index: ?usize = null,
        spans: std.ArrayList(Span) = .empty,
        fn finish(self: *BodyParagraphJoin, a: A) Error!void {
            if (self.index) |index| self.blocks.?.items[index].spans = try self.spans.toOwnedSlice(a);
            self.blocks = null;
            self.index = null;
        }
    };

    fn appendParagraphSpans(self: *Renderer, blocks: *std.ArrayList(Block), index: usize, extra: []const Span, separator: bool) Error!void {
        if (self.body_paragraph_join) |pending| {
            if (pending.blocks == null or pending.blocks.? != blocks or pending.index == null or pending.index.? != index) {
                try pending.finish(self.a);
                pending.blocks = blocks;
                pending.index = index;
                try pending.spans.appendSlice(self.a, blocks.items[index].spans);
            }
            if (separator) try pending.spans.append(self.a, self.formattingSeparator());
            try pending.spans.appendSlice(self.a, extra);
            blocks.items[index].spans = pending.spans.items;
        } else {
            const previous = blocks.items[index].spans;
            const spans = try self.a.alloc(Span, previous.len + @intFromBool(separator) + extra.len);
            @memcpy(spans[0..previous.len], previous);
            var next = previous.len;
            if (separator) {
                spans[next] = self.formattingSeparator();
                next += 1;
            }
            @memcpy(spans[next..], extra);
            blocks.items[index].spans = spans;
        }
        blocks.items[index].text = "";
    }

    fn joinBodyParagraphs(self: *Renderer, blocks: *std.ArrayList(Block), first: usize, separator: bool) Error!void {
        if (first == 0 or first >= blocks.items.len or blocks.items[first - 1].kind != .paragraph or blocks.items[first].kind != .paragraph) return;
        const leading = blocks.items[first];
        try self.appendParagraphSpans(blocks, first - 1, leading.spans, separator);
        blocks.items[first - 1].relation_note = blocks.items[first - 1].relation_note or leading.relation_note;
        _ = blocks.orderedRemove(first);
    }

    fn rawBodyQuoteSeed(self: *Renderer, source: []const u8, raw: []const u8, quotes: *?QuoteBoundaryScan) Error!?QuoteSeed {
        if (quotes.* == null) return null;
        const base = @intFromPtr(source.ptr);
        const at = @intFromPtr(raw.ptr);
        if (at < base or at - base > source.len or raw.len > source.len - (at - base)) return null;
        return try quotes.*.?.at(self.a, at - base, self.context.behavior_switches);
    }
    fn bodyRawParagraph(self: *Renderer, blocks: *std.ArrayList(Block), source: []const u8, raw: []const u8, fallback: ?QuoteSeed, quotes: *?QuoteBoundaryScan, pending_join: *?bool) Error!void {
        const parsed = if (self.parsed_pre) raw else trim(raw);
        const seed = (try self.rawBodyQuoteSeed(source, parsed, quotes)) orelse fallback;
        try self.bodyParagraph(blocks, raw, seed, pending_join);
    }
    // Primary BlockLevelPass trims prefixed physical-list-line edges, not
    // protected payloads or a logical scope spanning ordinary source lines.
    // Keep the existing leading-space policy; only an outside ASCII suffix
    // can be removed. NBSP and every interior byte remain authored content.
    fn wikiListLineBody(raw: []const u8) []const u8 {
        const body = std.mem.trimStart(u8, raw, " \t");
        const trimmed = std.mem.trimEnd(u8, body, " \t");
        if (trimmed.len == body.len) return body;
        var scan: syntax.OpaqueScan = .{};
        var no_more_nowiki_close = false;
        var at: usize = 0;
        while (at < trimmed.len) {
            if (body[at] == '\n' or body[at] == '\r') return body;
            if (body[at] == '<') if (scan.tagAt(body, at, &no_more_nowiki_close)) |tag| {
                if (!tag.closing and !tag.self_closing and (tag.isOpaque() or tag.html_pre)) {
                    const pair = syntax.matchingTagWithOpaqueScan(body, tag, &scan) orelse return body;
                    if (pair.end > trimmed.len) return body;
                    at = pair.end;
                } else at = tag.end;
                continue;
            };
            if (scan.protectedEnd(body, at, &no_more_nowiki_close)) |end| {
                if (end > trimmed.len) return body;
                at = end;
                continue;
            }
            if (starts(body[at..], "[[") or starts(body[at..], "{{")) {
                const pair = syntax.balancedWithOpaqueScan(body, at, &scan) orelse return body;
                if (pair.end > trimmed.len) return body;
                at = pair.end;
                continue;
            }
            at += 1;
        }
        return trimmed;
    }

    // Project only one physical colon item after an invisible opening line.
    // Protected, mixed and multi-line contents retain their existing ownership.
    fn headingColonListBody(self: *Renderer, raw: []const u8) Error!?[]const u8 {
        const first_end = std.mem.indexOfScalar(u8, raw, '\n') orelse return null;
        const opening = std.mem.trim(u8, raw[0..first_end], " \t\r");
        const matcher = self.behaviorControlMatcher();
        if (syntax.leadingBehaviorControlOffset(opening, matcher) != opening.len) return null;
        const item = std.mem.trimEnd(u8, raw[first_end + 1 ..], "\r");
        if (std.mem.indexOfScalar(u8, item, '\n') != null) return null;
        const prefix = try syntax.controlListPrefixAlloc(self.a, item, matcher);
        if (!std.mem.eql(u8, prefix.path, ":")) return null;
        return wikiListLineBody(item[prefix.body_start..]);
    }

    pub fn renderBodyWithHeadingOffsets(self: *Renderer, tracked: MissingText) Error![]const Block {
        const previous_source = self.heading_source;
        const previous_missing = self.body_missing;
        self.heading_source = tracked.bytes;
        self.body_missing = tracked;
        defer {
            self.heading_source = previous_source;
            self.body_missing = previous_missing;
        }
        try self.loadPoemPhase();
        return self.renderBodySlice(tracked.bytes, false, false, 0, null);
    }

    fn missingSliceWithHeadingSource(self: *Renderer, parent: MissingText, child: []const u8) Error!MissingText {
        const tracked = try missingSlice(self.a, parent, child);
        if (self.heading_source != null and child.len != 0 and tracked.bytes.ptr != child.ptr)
            try self.heading_source_aliases.append(self.a, .{ .copied = tracked.bytes, .original = child });
        return tracked;
    }

    fn headingSourceOffset(self: *const Renderer, raw: []const u8) ?usize {
        const root = self.heading_source orelse return null;
        var address = @intFromPtr(raw.ptr);
        var depth: usize = 0;
        while (depth < max_depth) : (depth += 1) {
            const root_address = @intFromPtr(root.ptr);
            if (address >= root_address and address - root_address <= root.len and (address - root_address < root.len or raw.len == 0))
                return address - root_address;
            var mapped = false;
            for (self.heading_source_aliases.items) |alias| {
                const copied = @intFromPtr(alias.copied.ptr);
                if (address >= copied and address - copied < alias.copied.len) {
                    address = @intFromPtr(alias.original.ptr) + (address - copied);
                    mapped = true;
                    break;
                }
            }
            if (!mapped) return null;
        }
        return null;
    }

    fn appendHeadingSourceCopy(self: *Renderer, output: *std.ArrayList(u8), copies: *std.ArrayList(HeadingSourceCopy), original: []const u8) Error!void {
        const start = output.items.len;
        try output.appendSlice(self.a, original);
        try self.recordHeadingSourceCopy(copies, start, original);
    }

    fn recordHeadingSourceCopy(self: *Renderer, copies: *std.ArrayList(HeadingSourceCopy), start: usize, original: []const u8) Error!void {
        if (self.heading_source == null or original.len == 0) return;
        if (copies.items.len != 0) {
            const previous = &copies.items[copies.items.len - 1];
            if (previous.start + previous.original.len == start and
                @intFromPtr(previous.original.ptr) + previous.original.len == @intFromPtr(original.ptr))
            {
                previous.original = previous.original.ptr[0 .. previous.original.len + original.len];
                return;
            }
        }
        try copies.append(self.a, .{ .start = start, .original = original });
    }

    fn appendMissingHeadingSourceCopy(self: *Renderer, output: *missing_dependency.Builder, copies: *std.ArrayList(HeadingSourceCopy), source: MissingText, start: usize, end: usize) Error!void {
        const output_start = output.bytes.items.len;
        try output.appendSlice(self.a, source, start, end);
        try self.recordHeadingSourceCopy(copies, output_start, source.bytes[start..end]);
    }

    fn appendMissingHeadingSourceEdit(self: *Renderer, output: *missing_dependency.Builder, copies: *std.ArrayList(HeadingSourceCopy), source: MissingText, at: usize, replacement: []const u8) Error!void {
        const output_start = output.bytes.items.len;
        try output.append(self.a, missingEdit(source, at, at + 1, replacement));
        // Only the replacement's first byte identifies its authored source byte.
        // The remaining generated entity spelling has no source identity.
        if (replacement.len != 0) try self.recordHeadingSourceCopy(copies, output_start, source.bytes[at .. at + 1]);
    }

    fn registerHeadingSourceCopies(self: *Renderer, output: []const u8, copies: []const HeadingSourceCopy) Error!void {
        for (copies) |copy| try self.heading_source_aliases.append(self.a, .{
            .copied = output[copy.start .. copy.start + copy.original.len],
            .original = copy.original,
        });
    }

    fn bodyRawBlock(self: *Renderer, blocks: *std.ArrayList(Block), source: []const u8, raw: []const u8, quotes: *?QuoteBoundaryScan, kind: Kind, path: []const u8, number: []const u8, level: u8) Error!void {
        const previous = self.next_quote_seed;
        self.next_quote_seed = try self.rawBodyQuoteSeed(source, raw, quotes);
        defer self.next_quote_seed = previous;
        try self.block(blocks, kind, raw, path, number, level);
    }

    // Table parsing precedes BlockLevelPass. After a wiki list prefix has
    // been consumed, its leading |} is visible item text, not a table close.
    // Isolate only that literal delimiter; the complete suffix stays strict.
    fn literalWikiListTableClose(self: *Renderer, blocks: *std.ArrayList(Block), first_block: usize, raw: []const u8) Error!void {
        if (!starts(raw, "|}") or blocks.items.len != first_block + 1) return;
        const spans = blocks.items[first_block].spans;
        if (spans.len == 0) return;
        const first = spans[0];
        if (first.kind != .text or first.provenance != .parsed or !starts(first.text, "|}")) return;
        const extra: usize = @intFromBool(first.text.len > 2);
        const literal_spans = try self.a.alloc(Span, spans.len + extra);
        literal_spans[0] = first;
        literal_spans[0].text = first.text[0..2];
        literal_spans[0].provenance = .protected_literal;
        if (extra != 0) {
            literal_spans[1] = first;
            literal_spans[1].text = first.text[2..];
        }
        @memcpy(literal_spans[1 + extra ..], spans[1..]);
        blocks.items[first_block].spans = literal_spans;
    }

    fn bodyParagraph(self: *Renderer, blocks: *std.ArrayList(Block), raw: []const u8, seed: ?QuoteSeed, pending_join: *?bool) Error!void {
        const first = blocks.items.len;
        try self.paragraphWithQuoteSeed(blocks, raw, seed);
        if (pending_join.*) |separator| {
            pending_join.* = null;
            try self.joinBodyParagraphs(blocks, first, separator);
        }
    }

    fn appendLinkContinuation(self: *Renderer, blocks: *std.ArrayList(Block), raw: []const u8, target: []const u8) Error!void {
        if (raw.len == 0) return;
        const spans = try self.parseBodySpans(raw, if (target.len != 0) try self.wikiLinkStyle(.{}, .{ .target = target }) else .{});
        if (spans.len == 0) return;
        if (blocks.items.len != 0 and blocks.items[blocks.items.len - 1].kind == .paragraph) {
            try self.appendParagraphSpans(blocks, blocks.items.len - 1, spans, false);
        } else try self.appendBlockBudgeted(blocks, .{ .kind = .paragraph, .spans = spans });
    }

    const BodyPre = struct { opening_start: usize, tag: syntax.Tag, pair: ?syntax.Pair };
    // A root paragraph's pre is a block element. Complete inline/cell domains
    // remain with their existing parsers; never discover a page scope inside
    // attributes, a protected body, a link label, or a template argument.
    // The same conservative hint used by Writer admission. Actual body
    // traversal decides whether a later pre is parsed, protected or literal.
    fn bodyPreCandidate(input: []const u8) bool {
        var at: usize = 0;
        while (std.mem.indexOfScalarPos(u8, input, at, '<')) |opening| {
            at = opening + 1;
            if (input.len - at >= 3 and std.ascii.eqlIgnoreCase(input[at .. at + 3], "pre")) return true;
        }
        return false;
    }
    fn htmlHeadingLevel(tag: syntax.Tag) ?u8 {
        if (tag.name.len != 2 or std.ascii.toLower(tag.name[0]) != 'h' or tag.name[1] < '1' or tag.name[1] > '6') return null;
        return tag.name[1] - '0';
    }
    // Promote only existing ordinary block containers after lexical text.
    // Nested accepted tags, protected bodies and link labels keep their owners.
    fn inlineBodyContainerAt(self: *Renderer, input: []const u8, start: usize, line_end: usize) Error!?usize {
        var at = start;
        var opaque_scan: syntax.OpaqueScan = .{};
        while (at < line_end) {
            at += std.mem.indexOfAny(u8, input[at..line_end], "<[{") orelse return null;
            if (input[at] == '<') {
                if (opaque_scan.protectedEnd(input, at, null)) |end| {
                    at = end;
                    continue;
                }
                if (try self.semanticTagAt(input[at..], 0)) |tag| {
                    if (!tag.closing and syntax.pairedHtmlTag(tag.name)) {
                        const pair = syntax.matchingTag(input[at..], tag) orelse return null;
