        // Reuse semantic attribute/style handling while removing only the list
        // marker tag. Its li identity must not reach the inline bullet path.
        const styled = try std.fmt.allocPrint(self.a, "<span{s}>{s}</span>", .{ item.attrs, input });
        const spans = try self.parseSpans(styled, style);
        if (!keep_empty and trim(try plainText(self.a, spans)).len == 0) return;
        const effective_path = if (kind == .list_detail and (path[path.len - 1] == '*' or path[path.len - 1] == '#')) try std.fmt.allocPrint(self.a, "{s}:", .{path}) else path;
        try self.appendBlockBudgeted(blocks, .{ .kind = kind, .spans = spans, .depth = @intCast(@min(effective_path.len, 255)), .list_path = effective_path, .number = number, .relation_note = self.body_formatting_attributes.relation_note });
    }
    fn htmlTableFostered(self: *Renderer, blocks: *std.ArrayList(Block), input: []const u8, joinable: *bool, formatting: *std.ArrayList([]const u8)) Error!void {
        // HTML moves non-cell table content before the table. Preserve that
        // visible content in ordinary blocks, never in a fabricated caption.
        var source: std.ArrayList(u8) = .empty;
        var heading_copies: std.ArrayList(HeadingSourceCopy) = .empty;
        defer heading_copies.deinit(self.a);
        for (formatting.items) |opening| try self.appendHeadingSourceCopy(&source, &heading_copies, opening);
        var local_blocks: std.ArrayList([]const u8) = .empty;
        var at: usize = 0;
        while (at < input.len) {
            if (input[at] == '<') {
                if (syntax.protectedEnd(input, at)) |end| {
                    try self.appendHeadingSourceCopy(&source, &heading_copies, input[at..end]);
                    at = end;
                    continue;
                }
                if (try self.semanticTagAt(input, at)) |tag| {
                    if (!tag.closing and (tag.is("td") or tag.is("th"))) {
                        at = optionalTableEnd(input, tag).end;
                        continue;
                    }
                    if (!tag.closing and tag.is("caption")) if (syntax.matchingTag(input, tag)) |pair| {
                        at = pair.end;
                        continue;
                    };
                    // Preserve unsupported authored group spellings through the same
                    // literal-tag path as ordinary inline content.
                    if (oneOf(tag.name, &.{ "tr", "td", "th", "caption" })) {
                        at = tag.end;
                        continue;
                    }
                    if (!tag.closing and oneOf(tag.name, &.{ "script", "style", "iframe", "object", "embed" })) {
                        if (syntax.matchingTag(input, tag)) |pair| {
                            try self.appendHeadingSourceCopy(&source, &heading_copies, input[at..pair.end]);
                            at = pair.end;
                            continue;
                        }
                    }
                    const reconstruct = oneOf(tag.name, &.{ "b", "big", "em", "font", "i", "s", "small", "strike", "strong", "tt", "u" });
                    const layout = oneOf(tag.name, &.{ "div", "p", "blockquote", "center" });
                    if (reconstruct or layout) {
                        const stack = if (reconstruct) formatting else &local_blocks;
                        if (tag.closing) {
                            var index = stack.items.len;
                            while (index != 0) {
                                index -= 1;
                                const opening = (try self.semanticTagAt(stack.items[index], 0)).?;
                                if (std.ascii.eqlIgnoreCase(opening.name, tag.name)) {
                                    stack.shrinkRetainingCapacity(index);
                                    break;
                                }
                            }
                        } else if (!tag.self_closing and stack.items.len < max_depth) try stack.append(self.a, input[at..tag.end]);
                    }
                    try self.appendHeadingSourceCopy(&source, &heading_copies, input[at..tag.end]);
                    at = tag.end;
                    continue;
                }
            }
            try self.appendHeadingSourceCopy(&source, &heading_copies, input[at .. at + 1]);
            at += 1;
        }
        // Cell entry pops layout wrappers; active HTML formatting elements
        // are reconstructed for subsequent fostered text, not for cell text.
        var closing = local_blocks.items.len;
        while (closing != 0) {
            closing -= 1;
            const tag = (try self.semanticTagAt(local_blocks.items[closing], 0)).?;
            try source.appendSlice(self.a, try std.fmt.allocPrint(self.a, "</{s}>", .{tag.name}));
        }
        closing = formatting.items.len;
        while (closing != 0) {
            closing -= 1;
            const tag = (try self.semanticTagAt(formatting.items[closing], 0)).?;
            try source.appendSlice(self.a, try std.fmt.allocPrint(self.a, "</{s}>", .{tag.name}));
        }
        var explicit_blocks = false;
        var lines = std.mem.splitScalar(u8, source.items, '\n');
        while (lines.next()) |line| {
            if (line.len != 0 and (std.mem.indexOfScalar(u8, "*#;:=", line[0]) != null or starts(line, "{|"))) explicit_blocks = true;
        }
        var cursor: usize = 0;
        while (std.mem.indexOfScalarPos(u8, source.items, cursor, '<')) |open| {
            if (syntax.protectedEnd(source.items, open)) |end| {
                cursor = end;
                continue;
            }
            const tag = try self.semanticTagAt(source.items, open) orelse {
                cursor = open + 1;
                continue;
            };
            cursor = tag.end;
            if (oneOf(tag.name, &.{ "div", "p", "blockquote", "center", "ul", "ol", "dl", "table", "h1", "h2", "h3", "h4", "h5", "h6" })) explicit_blocks = true;
        }
        try self.registerHeadingSourceCopies(source.items, heading_copies.items);
        const produced = if (explicit_blocks) try self.renderInlineTableBody(source.items) else blk: {
            // Parsing inline character data directly retains source boundary
            // whitespace. Joining adds no separator that was not in source.
            const spans = try self.parseBodySpans(source.items, .{});
            if (spans.len == 0 or (!joinable.* and trim(try plainText(self.a, spans)).len == 0)) break :blk &.{};
            const result = try self.a.alloc(Block, 1);
            result[0] = .{ .kind = .paragraph, .spans = spans };
            break :blk result;
        };
        if (produced.len == 1 and produced[0].kind == .paragraph and !explicit_blocks and joinable.* and blocks.items.len != 0) {
            // Cell boundaries do not introduce paragraph breaks in fostered
            // character data. Join their already-compiled spans without
            // executing references or other source effects a second time.
            const last = &blocks.items[blocks.items.len - 1];
            var spans: std.ArrayList(Span) = .empty;
            try spans.appendSlice(self.a, last.spans);
            try spans.appendSlice(self.a, produced[0].spans);
            last.spans = try spans.toOwnedSlice(self.a);
        } else try blocks.appendSlice(self.a, produced);
        if (produced.len != 0) joinable.* = produced[produced.len - 1].kind == .paragraph and !explicit_blocks;
    }
    const HtmlTableCellStart = struct { open: usize, tag: syntax.Tag };
    fn nextHtmlTableCell(input: []const u8, start: usize) ?HtmlTableCellStart {
        var at = start;
        while (std.mem.indexOfScalarPos(u8, input, at, '<')) |open| {
            if (syntax.protectedEnd(input, open)) |end| {
                at = end;
                continue;
            }
            const tag = syntax.tagAt(input, open) orelse {
                at = open + 1;
                continue;
            };
            at = tag.end;
            if (!tag.closing and (tag.is("td") or tag.is("th")))
                return .{ .open = open, .tag = tag };
        }
        return null;
    }
    // Refuse an unclosed table-level caption before cells or fostered text can
    // register references/media. Mirror htmlTable's row boundaries so captions
    // inside an already consumed cell/row are not a new table-level admission.
    fn htmlTableCaptionsComplete(input: []const u8) bool {
        var pos: usize = 0;
        while (std.mem.indexOfScalarPos(u8, input, pos, '<')) |open| {
            if (syntax.protectedEnd(input, open)) |end| {
                pos = end;
                continue;
            }
            const tag = syntax.tagAt(input, open) orelse {
                pos = open + 1;
                continue;
            };
            pos = tag.end;
            const implicit_row = tag.is("td") or tag.is("th");
            if (tag.closing or !(tag.is("tr") or tag.is("caption") or implicit_row)) continue;
            const pair = if (implicit_row)
                optionalTableEndFrom(input, "tr", open, true)
            else if (tag.is("tr"))
                optionalTableEnd(input, tag)
            else
                syntax.matchingTag(input, tag) orelse return false;
            pos = pair.end;
        }
        return true;
    }

    const HtmlNestedGrid = struct { tag: syntax.Tag, depth: usize = 0 };
    const HtmlNestedChild = struct { tag: syntax.Tag, body: []const u8 };

    fn htmlNestedAttributes(attrs: []const u8, allowed: []const []const u8) bool {
        var at: usize = 0;
        var seen: u32 = 0;
        while (at < attrs.len) {
            while (at < attrs.len and std.ascii.isWhitespace(attrs[at])) : (at += 1) {}
            if (at == attrs.len) break;
            const start = at;
            while (at < attrs.len and !std.ascii.isWhitespace(attrs[at]) and attrs[at] != '=') : (at += 1) {}
            var field: ?u5 = null;
            for (allowed, 0..) |name, i| {
                if (std.ascii.eqlIgnoreCase(attrs[start..at], name)) field = @intCast(i);
            }
            const bit = @as(u32, 1) << (field orelse return false);
            if (seen & bit != 0) return false;
            seen |= bit;
            while (at < attrs.len and std.ascii.isWhitespace(attrs[at])) : (at += 1) {}
            if (at == attrs.len or attrs[at] != '=') return false;
            at += 1;
            while (at < attrs.len and std.ascii.isWhitespace(attrs[at])) : (at += 1) {}
            if (at == attrs.len) return false;
            if (attrs[at] == '\'' or attrs[at] == '"') {
                const quote = attrs[at];
                at += 1;
                while (at < attrs.len and attrs[at] != quote) : (at += 1) {}
                if (at == attrs.len) return false;
                at += 1;
                if (at < attrs.len and !std.ascii.isWhitespace(attrs[at])) return false;
            } else {
                while (at < attrs.len and !std.ascii.isWhitespace(attrs[at])) : (at += 1) {}
            }
        }
        return true;
    }
    fn htmlNestedUnsigned(comptime T: type, raw: []const u8) ?T {
        if (raw.len == 0) return null;
        for (raw) |byte| if (!std.ascii.isDigit(byte)) return null;
        return std.fmt.parseInt(T, raw, 10) catch null;
    }
    // Only typed, integral legacy geometry is admitted. Absence and authored
    // zero remain different values; unrelated CSS stays on the existing path.
    fn htmlNestedGeometry(tag: syntax.Tag) ?TableGeometry {
        if (!htmlNestedAttributes(tag.attrs, &.{ "border", "cellspacing", "cellpadding", "width" })) return null;
        var result: TableGeometry = .{};
        if (tag.attr("border")) |raw| result.border = htmlNestedUnsigned(u16, raw) orelse return null;
        if (tag.attr("cellspacing")) |raw| result.cell_spacing = htmlNestedUnsigned(u16, raw) orelse return null;
        if (tag.attr("cellpadding")) |raw| result.cell_padding = htmlNestedUnsigned(u16, raw) orelse return null;
        if (tag.attr("width")) |raw| {
            const percent = std.mem.endsWith(u8, raw, "%");
            const pixels = std.mem.endsWith(u8, raw, "px");
            const digits = if (percent) raw[0 .. raw.len - 1] else if (pixels) raw[0 .. raw.len - 2] else raw;
            const value = htmlNestedUnsigned(u32, digits) orelse return null;
            if (percent and value > 100) return null;
            result.width = .{ .unit = if (percent) .percent else .px, .value = value };
        }
        return result;
    }
    fn htmlNestedCellAttributes(tag: syntax.Tag) bool {
        if (!htmlNestedAttributes(tag.attrs, &.{ "colspan", "rowspan", "style" })) return false;
        inline for (.{ "colspan", "rowspan" }) |name| {
            if (tag.attr(name)) |raw| {
                const value = htmlNestedUnsigned(u16, raw) orelse return false;
                if (value == 0 or value > 100) return false;
            }
        }
        if (tag.attr("style")) |raw| {
            var declaration = trim(raw);
            if (std.mem.endsWith(u8, declaration, ";")) declaration = trim(declaration[0 .. declaration.len - 1]);
            const colon = std.mem.indexOfScalar(u8, declaration, ':') orelse return false;
            if (!std.ascii.eqlIgnoreCase(trim(declaration[0..colon]), "background")) return false;
            if (!@import("blob_encoder").presentation_types.isCanonicalRgb(trim(declaration[colon + 1 ..]))) return false;
        }
        return true;
    }
    fn htmlNestedChild(input: []const u8) ?HtmlNestedChild {
        const content = trim(input);
        const tag = syntax.tagAt(content, 0) orelse return null;
        if (!tag.is("table") or tag.closing or tag.self_closing) return null;
        const pair = syntax.matchingTag(content, tag) orelse return null;
        if (pair.end != content.len) return null;
        return .{ .tag = tag, .body = content[tag.end..pair.inner_end] };
    }
    fn htmlNestedSpend(remaining: *usize) bool {
        if (remaining.* == 0) return false;
        remaining.* -= 1;
        return true;
    }
    // Admission is read-only over the complete tree, before references, media,
    // or other page-local effects can be registered by a rendered cell.
    fn htmlNestedGridComplete(tag: syntax.Tag, input: []const u8, depth: usize, remaining: *usize, found_child: *bool) bool {
        if (depth >= @import("blob_encoder").presentation_types.max_table_depth or !htmlNestedSpend(remaining)) return false;
        _ = htmlNestedGeometry(tag) orelse return false;
        var at: usize = 0;
        var rows: usize = 0;
        var caption_seen = false;
        while (at < input.len) {
            while (at < input.len and std.ascii.isWhitespace(input[at])) : (at += 1) {}
            if (at == input.len) break;
            const row = syntax.tagAt(input, at) orelse return false;
            if (row.closing or row.self_closing or trim(row.attrs).len != 0) return false;
            const row_pair = syntax.matchingTag(input, row) orelse return false;
            if (row.is("caption")) {
                if (caption_seen or rows != 0 or !htmlNestedSpend(remaining)) return false;
                caption_seen = true;
                if (!htmlNestedLeafComplete(input[row.end..row_pair.inner_end])) return false;
                at = row_pair.end;
                continue;
            }
            if (!row.is("tr") or !htmlNestedSpend(remaining)) return false;
            var cell_at = row.end;
            var cells: usize = 0;
            while (cell_at < row_pair.inner_end) {
                while (cell_at < row_pair.inner_end and std.ascii.isWhitespace(input[cell_at])) : (cell_at += 1) {}
                if (cell_at == row_pair.inner_end) break;
                const cell = syntax.tagAt(input[0..row_pair.inner_end], cell_at) orelse return false;
                if (!(cell.is("td") or cell.is("th")) or cell.closing or cell.self_closing or !htmlNestedCellAttributes(cell) or !htmlNestedSpend(remaining)) return false;
                const pair = syntax.matchingTag(input[0..row_pair.inner_end], cell) orelse return false;
                const body = input[cell.end..pair.inner_end];
                if (htmlNestedChild(body)) |child| {
                    if (!htmlNestedGridComplete(child.tag, child.body, depth + 1, remaining, found_child)) return false;
                    found_child.* = true;
                } else if (!htmlNestedLeafComplete(body)) return false;
                cells += 1;
                cell_at = pair.end;
            }
            if (cells == 0) return false;
            rows += 1;
            at = row_pair.end;
        }
        return rows != 0;
    }
    fn htmlNestedLeafComplete(input: []const u8) bool {
        if (std.mem.indexOf(u8, input, "{|") != null) return false;
        var at: usize = 0;
        while (std.mem.indexOfScalarPos(u8, input, at, '<')) |open| {
            if (syntax.protectedEnd(input, open)) |end| {
                at = end;
                continue;
            }
            const tag = syntax.tagAt(input, open) orelse {
                at = open + 1;
                continue;
            };
            if (oneOf(tag.name, &.{ "table", "tr", "td", "th", "caption" })) return false;
            at = tag.end;
        }
        return true;
    }
    fn htmlNestedGridAdmission(tag: syntax.Tag, body: []const u8) ?HtmlNestedGrid {
        var remaining: usize = 1 << 20;
        var found_child = false;
        if (!htmlNestedGridComplete(tag, body, 0, &remaining, &found_child) or !found_child) return null;
        return .{ .tag = tag };
    }

    fn htmlTable(self: *Renderer, input: []const u8, fostered: *std.ArrayList(Block), defer_zero_rowspans: bool, style: Style, table_background: ?[]const u8, nested_grid: ?HtmlNestedGrid) Error!?Table {
        if (!htmlTableCaptionsComplete(input)) return null;
        var rows: std.ArrayList(Row) = .empty;
        var caption: std.ArrayList(Span) = .empty;
        var pos: usize = 0;
        var processed: usize = 0;
        var foster_joinable = false;
        var foster_formatting: std.ArrayList([]const u8) = .empty;
        while (std.mem.indexOfScalarPos(u8, input, pos, '<')) |open| {
            if (self.truncated) break;
            if (syntax.protectedEnd(input, open)) |end| {
                pos = end;
                continue;
            }
            const tag = try self.semanticTagAt(input, open) orelse {
                pos = open + 1;
                continue;
            };
            pos = tag.end;
            const implicit_row = tag.is("td") or tag.is("th");
            if (tag.closing or !(tag.is("tr") or tag.is("caption") or implicit_row)) continue;
            const pair = if (implicit_row)
                optionalTableEndFrom(input, "tr", open, true)
            else if (tag.is("tr"))
                optionalTableEnd(input, tag)
            else
                syntax.matchingTag(input, tag) orelse return null;
            pos = pair.end;
            if (tag.is("caption")) {
                try self.htmlTableFostered(fostered, input[processed..open], &foster_joinable, &foster_formatting);
                const inherited_formatting = self.block_formatting;
                const inherited_poem_italic = self.poem_base_style.italic;
                defer self.poem_base_style.italic = inherited_poem_italic;
                if (try self.htmlFontWeight(tag)) |bold| self.block_formatting.bold = bold;
                if (try self.htmlFontStyle(tag)) |italic| {
                    self.block_formatting.italic = italic;
                    if (self.poem_depth != 0) self.poem_base_style.italic = italic;
                }
                defer self.block_formatting = inherited_formatting;
                try self.appendTableCaption(&caption, try self.parseSpansWithLanguageDirection(input[tag.end..pair.inner_end], try self.htmlLanguageDirection(tag, style)));
                processed = pair.end;
                continue;
            }
            const row_background = if (implicit_row) table_background else try self.tableCellBackground(tag, table_background);
            const row_style = if (implicit_row) style else try self.htmlLanguageDirection(tag, style);
            var cells: std.ArrayList(Cell) = .empty;
            // Reuse the same cell parser, beginning before the actual first
            // cell when HTML implied the missing row opener.
            var at = if (implicit_row) open else tag.end;
            while (nextHtmlTableCell(input[0..pair.inner_end], at)) |cell| {
                if (self.truncated) break;
                const cell_open = cell.open;
                const cell_tag = cell.tag;
                at = cell_tag.end;
                const cell_pair = optionalTableEnd(input[0..pair.inner_end], cell_tag);
                at = cell_pair.end;
                // Render each source prefix before its next cell so references
                // and other page-local effects retain source traversal order.
