            }
            if (cells.items.len != 0) try rows.append(self.a, .{ .cells = try cells.toOwnedSlice(self.a) });
        }
        try self.htmlTableFostered(fostered, input[processed..], &foster_joinable, &foster_formatting);
        // Unsupported authored group tags do not split the actual table row group.
        if (!defer_zero_rowspans) try self.resolveZeroRowspans(rows.items, 0);
        const geometry = if (nested_grid) |grid| htmlNestedGeometry(grid.tag).? else TableGeometry{};
        return .{
            .caption = try caption.toOwnedSlice(self.a),
            .rows = try rows.toOwnedSlice(self.a),
            .geometry = if (@import("blob_encoder").presentation_types.validTableGeometry(geometry)) geometry else null,
        };
    }
    const TableResult = struct { table: Table, end: usize, body_end: usize, fostered: []const Block, has_caption: bool, feature: ?Feature = null };
    fn appendWikiTableFosteredCopy(self: *Renderer, output: *MissingBuffer, copies: *std.ArrayList(HeadingSourceCopy), tracked: MissingText, bytes: []const u8) Error!void {
        const start = output.items.len;
        try output.appendCopied(self.a, tracked, bytes);
        try self.recordHeadingSourceCopy(copies, start, bytes);
    }
    fn flushWikiTableFostered(self: *Renderer, blocks: *std.ArrayList(Block), source: *MissingBuffer, copies: *std.ArrayList(HeadingSourceCopy)) Error!void {
        if (source.items.len == 0) return;
        // Rendered spans may borrow their input; release the accumulated
        // slice from the mutable buffer before another fostered segment.
        const body = try source.take(self.a);
        try self.registerHeadingSourceCopies(body.bytes, copies.items);
        copies.clearRetainingCapacity();
        try blocks.appendSlice(self.a, try self.renderBodyWithOrphanOrigin(body, true));
    }
    fn wikiTableIndent(line: []const u8) ?[]const u8 {
        var indent: usize = 0;
        while (indent < line.len and line[indent] == ':') : (indent += 1) {}
        var content = indent;
        while (content < line.len and std.ascii.isWhitespace(line[content])) : (content += 1) {}
        if (!starts(line[content..], "{|")) return null;
        return line[0..indent];
    }
    fn indentTableBlocks(self: *Renderer, blocks: []const Block, path: []const u8) Error![]const Block {
        if (path.len == 0 or blocks.len == 0) return blocks;
        const indented = try self.a.dupe(Block, blocks);
        for (indented) |*b| {
            const composed = try std.fmt.allocPrint(self.a, "{s}{s}", .{ path, b.list_path });
            b.list_path = composed[0..@min(composed.len, 255)];
            b.depth = @intCast(b.list_path.len);
        }
        return indented;
    }
    fn appendTableCaption(self: *Renderer, caption: *std.ArrayList(Span), spans: []const Span) Error!void {
        if (spans.len == 0) return;
        if (caption.items.len != 0 and self.spend())
            try caption.append(self.a, .{ .kind = .line_break, .text = "" });
        try caption.appendSlice(self.a, spans);
    }
    fn finishWikiTableCaption(self: *Renderer, caption: *std.ArrayList(Span), source: *MissingBuffer, pending: *bool, style: Style, formatting: SpanFlags) Error!void {
        if (!pending.*) return;
        const inherited_style = self.body_language_direction;
        const inherited_formatting = self.block_formatting;
        const inherited_poem_italic = self.poem_base_style.italic;
        defer self.body_language_direction = inherited_style;
        defer self.block_formatting = inherited_formatting;
        defer self.poem_base_style.italic = inherited_poem_italic;
        self.body_language_direction = style;
        self.block_formatting = formatting;
        if (self.poem_depth != 0) self.poem_base_style.italic = formatting.italic;
        // Parsed spans can borrow source bytes; detach the completed caption.
        const body = try source.take(self.a);
        try self.appendTableCaption(caption, try self.cellSpansWithMissing(body));
        pending.* = false;
    }
    const LayoutTableBody = struct { body: []const u8, end: usize };

    // Heading-free single-cell layout wrappers may expose their original
    // grid body. Semantic cell headings must retain their containing cell.
    // Inspect shape before rendering: references/media must register only once.
    fn layoutBodyHasHeading(self: *Renderer, body: []const u8) bool {
        var opaque_scan: syntax.OpaqueScan = .{};
        var no_more_nowiki_close = false;
        var at: usize = 0;
        while (at < body.len) {
            if (opaque_scan.protectedEnd(body, at, &no_more_nowiki_close)) |end| {
                at = end;
                continue;
            }
            if (body[at] == '<') {
                if (opaque_scan.tagAt(body, at, &no_more_nowiki_close)) |tag| {
                    if (!tag.closing and tag.html_pre) {
                        at = if (syntax.matchingTagWithOpaqueScan(body, tag, &opaque_scan)) |pair| pair.end else body.len;
                        continue;
                    }
                    if (!tag.closing and !tag.self_closing and tag.name.len == 2 and
                        std.ascii.toLower(tag.name[0]) == 'h' and tag.name[1] >= '1' and tag.name[1] <= '6' and
                        syntax.matchingTagWithOpaqueScan(body, tag, &opaque_scan) != null) return true;
                    at = tag.end;
                    continue;
                }
            } else if (starts(body[at..], "{{") or starts(body[at..], "[[")) {
                if (syntax.balancedWithOpaqueScan(body, at, &opaque_scan)) |pair| {
                    at = pair.end;
                    continue;
                }
            } else if (body[at] == '[') {
                // Bracketed external labels are inline domains too.
                var inline_scan: ir.InlineIterator = .{ .input = body[at..], .renderer_boundaries = true, .link_trail = self.context.link_trail };
                if (inline_scan.next()) |token| if (token.kind == .external_link) {
                    at += inline_scan.cursor;
                    continue;
                };
            }
            if (at == 0 or body[at - 1] == '\n') {
                const end = std.mem.indexOfScalarPos(u8, body, at, '\n') orelse body.len;
                if (self.tableCellHeading(std.mem.trimEnd(u8, body[at..end], "\r")) != null) return true;
            }
            at += 1;
        }
        return false;
    }

    fn singleCellLayoutTable(self: *Renderer, input: []const u8, start: usize) Error!?LayoutTableBody {
        var opaque_scan: syntax.OpaqueScan = .{};
        var no_more_nowiki_close = false;
        var pos = start;
        var body_start: ?usize = null;
        var saw_row = false;
        var nested_tables: usize = 0;
        while (pos < input.len) {
            const line_start = pos;
            const end = syntax.logicalEndWithOpaqueScan(input, pos, &no_more_nowiki_close, &opaque_scan);
            const line = trim(input[pos..end]);
            pos = if (end < input.len) end + 1 else end;
            if (wikiTableIndent(line) != null) {
                if (body_start == null or nested_tables >= max_depth) return null;
                nested_tables += 1;
                continue;
            }
            if (nested_tables != 0) {
                if (starts(line, "|}")) nested_tables -= 1;
                continue;
            }
            if (starts(line, "|}")) {
                const first = body_start orelse return null;
                const body = input[first..line_start];
                if (!hasCompleteLayoutGrid(body)) return null;
                if (self.layoutBodyHasHeading(body)) return null;
                return .{
                    .body = body,
                    .end = if (line.len > 2) @intFromPtr(line.ptr) - @intFromPtr(input.ptr) + 2 else pos,
                };
            }
            if (starts(line, "|-")) {
                if (saw_row or body_start != null or trim(line[2..]).len != 0) return null;
                saw_row = true;
            } else if (starts(line, "|+") or starts(line, "!") or starts(line, "<tr")) {
                return null;
            } else if (starts(line, "|")) {
                if (body_start != null) return null;
                const raw = line[1..];
                const physical_end = std.mem.indexOfAny(u8, raw, "\r\n") orelse raw.len;
                if (syntax.delimiter(raw[0..physical_end], "||", 0) != null) return null;
                if (cellAttributePipe(raw)) |pipe| {
                    if (trim(raw[0..pipe]).len != 0) return null;
                }
                const content = (try self.cellContent(raw)).text;
                if (content.len != 0 and (std.mem.indexOfScalar(u8, "#*:;", content[0]) != null or
                    self.tableCellHeading(content[0 .. std.mem.indexOfScalar(u8, content, '\n') orelse content.len]) != null)) return null;
                body_start = @intFromPtr(content.ptr) - @intFromPtr(input.ptr);
            } else if (body_start == null and line.len != 0) {
                // Fostered prefix/caption/header semantics remain on the normal path.
                return null;
            }
        }
        return null;
    }

    fn hasCompleteLayoutGrid(body: []const u8) bool {
        var opaque_scan: syntax.OpaqueScan = .{};
        var no_more_nowiki_close = false;
        var depth: usize = 0;
        var found = false;
        var at: usize = 0;
        while (at < body.len) {
            if (body[at] == '<') {
                const maybe_tag = opaque_scan.tagAt(body, at, &no_more_nowiki_close);
                // An unmatched pre opener owns its remaining body in the
                // renderer, although the shared lexical scan resumes at tag.end.
                if (maybe_tag) |tag| {
                    if (!tag.closing and tag.is("pre")) return false;
                }
                if (opaque_scan.protectedEnd(body, at, &no_more_nowiki_close)) |end| {
                    at = end;
                    continue;
                }
                if (maybe_tag) |tag| {
                    // Do not infer transparency through another HTML grid.
                    if (oneOf(tag.name, &.{ "table", "tr", "td", "th", "code", "tt", "kbd", "samp" })) return false;
                    at = tag.end;
                    continue;
                }
            }
            if (starts(body[at..], "{{") or starts(body[at..], "[[")) {
                if (syntax.balancedWithOpaqueScan(body, at, &opaque_scan)) |pair| {
                    at = pair.end;
                    continue;
                }
            }
            if (at == 0 or body[at - 1] == '\n') {
                const end = std.mem.indexOfScalarPos(u8, body, at, '\n') orelse body.len;
                const line = body[at..end];
                // Leading-space preformatted source is not an active wiki grid.
                if (line.len != 0 and (line[0] == '{' or line[0] == ':') and wikiTableIndent(line) != null) {
                    if (depth >= max_depth) return false;
                    depth += 1;
                    found = true;
                } else if (starts(trim(line), "|}")) {
                    if (depth == 0) return false;
                    depth -= 1;
                } else if (depth == 0 and line.len != 0 and (line[0] == '|' or line[0] == '!')) {
                    return false;
                }
            }
            if (depth == 0 and starts(body[at..], "||")) return false;
            at += 1;
        }
        return found and depth == 0;
    }

    fn parseTable(self: *Renderer, source: []const u8, start: usize, swatch_background: ?[]const u8, table_background: ?[]const u8, table_style: Style) Error!TableResult {
        const tracked = if (self.body_missing) |parent| try self.missingSliceWithHeadingSource(parent, source) else MissingText.untracked(source);
        // Slicing tracked ranges owns a copied byte domain. Derive every cell
        // and caption slice from that same domain before copying provenance.
        const input = tracked.bytes;
        var row_background = table_background;
        var row_style = table_style;
        var cell_style = table_style;
        var swatch_foreground: ?[]const u8 = null;
        var swatch_allowed = true;
        var rows: std.ArrayList(Row) = .empty;
        var fostered: std.ArrayList(Block) = .empty;
        var cells: std.ArrayList(Cell) = .empty;
        var cell_source: MissingBuffer = .empty;
        var cell_copies: std.ArrayList(HeadingSourceCopy) = .empty;
        defer cell_copies.deinit(self.a);
        var outside_source: MissingBuffer = .empty;
        defer outside_source.deinit(self.a);
        var outside_copies: std.ArrayList(HeadingSourceCopy) = .empty;
        defer outside_copies.deinit(self.a);
        var current: ?Cell = null;
        const inherited_formatting = self.block_formatting;
        var row_formatting = inherited_formatting;
        var cell_formatting = inherited_formatting;
        var caption: std.ArrayList(Span) = .empty;
        var caption_source: MissingBuffer = .empty;
        var caption_pending = false;
        var caption_style = table_style;
        var caption_formatting = inherited_formatting;
        var has_caption = false;
        var pos = start;
        var body_end = input.len;
        var nested_tables: usize = 0;
        while (pos < input.len) {
            if (self.truncated) break;
            const line_start = pos;
            const end = wikiTableLineEnd(input, pos);
            const raw_line = std.mem.trimEnd(u8, input[pos..end], "\r");
            const line = trim(raw_line);
            pos = if (end < input.len) end + 1 else end;
            if (wikiTableIndent(line) != null) {
                swatch_allowed = false;
                // Keep a nested table with its caption or cell. With neither owner,
                // retain it as fostered source until the enclosing boundary.
                const nested_source = if (caption_pending) &caption_source else if (current != null) &cell_source else &outside_source;
                if (nested_source.items.len != 0) try nested_source.append(self.a, '\n');
                if (nested_source == &outside_source)
                    try self.appendWikiTableFosteredCopy(&outside_source, &outside_copies, tracked, raw_line)
                else if (nested_source == &cell_source)
                    try self.appendWikiTableFosteredCopy(&cell_source, &cell_copies, tracked, raw_line)
                else
                    try nested_source.appendCopied(self.a, tracked, raw_line);
                nested_tables += 1;
                continue;
            }
            if (nested_tables != 0) {
                const nested_source = if (caption_pending) &caption_source else if (current != null) &cell_source else &outside_source;
                if (nested_source.items.len != 0) try nested_source.append(self.a, '\n');
                if (nested_source == &outside_source)
                    try self.appendWikiTableFosteredCopy(&outside_source, &outside_copies, tracked, raw_line)
                else if (nested_source == &cell_source)
                    try self.appendWikiTableFosteredCopy(&cell_source, &cell_copies, tracked, raw_line)
                else
                    try nested_source.appendCopied(self.a, tracked, raw_line);
                if (starts(line, "|}")) nested_tables -= 1;
                continue;
            }
            if (starts(line, "|}") or starts(line, "|-")) {
                if (starts(line, "|-") and trim(line[2..]).len != 0) swatch_allowed = false;
                try self.finishWikiTableCaption(&caption, &caption_source, &caption_pending, caption_style, caption_formatting);
                try self.finishCell(&cells, &cell_source, &cell_copies, &current, cell_formatting, cell_style);
                if (cells.items.len != 0) try rows.append(self.a, .{ .cells = try cells.toOwnedSlice(self.a) });
                if (starts(line, "|}")) {
                    body_end = line_start;
                    // Preserve text and HTML following the close marker. A
                    // marker-only line still consumes its existing newline.
                    if (line.len > 2)
                        pos = @intFromPtr(line.ptr) - @intFromPtr(input.ptr) + 2;
                    break;
                }
                const row_tag: syntax.Tag = .{ .name = "tr", .attrs = line[2..], .end = 0, .closing = false, .self_closing = false };
                row_background = try self.tableCellBackground(row_tag, table_background);
                row_style = try self.wikiTableForeground(row_tag, table_style);
                row_formatting = try self.wikiTableFontFormatting(line[2..], inherited_formatting);
            } else if (starts(line, "|+")) {
                try self.finishWikiTableCaption(&caption, &caption_source, &caption_pending, caption_style, caption_formatting);
                try self.finishCell(&cells, &cell_source, &cell_copies, &current, cell_formatting, cell_style);
                // Preceding outside text registers references before the caption.
                try self.flushWikiTableFostered(&fostered, &outside_source, &outside_copies);
                const raw_caption = line[2..];
                caption_style = table_style;
                caption_formatting = inherited_formatting;
                if (cellAttributePipe(raw_caption)) |pipe| {
                    const caption_tag: syntax.Tag = .{ .name = "caption", .attrs = raw_caption[0..pipe], .end = 0, .closing = false, .self_closing = false };
                    caption_style = try self.htmlLanguageDirection(caption_tag, caption_style);
                    caption_formatting = try self.wikiTableFontFormatting(raw_caption[0..pipe], inherited_formatting);
                }
                try caption_source.appendCopied(self.a, tracked, (try self.cellContent(raw_caption)).text);
                caption_pending = true;
                has_caption = true;
            } else if (line.len != 0 and (line[0] == '!' or line[0] == '|')) {
                try self.finishWikiTableCaption(&caption, &caption_source, &caption_pending, caption_style, caption_formatting);
                try self.flushWikiTableFostered(&fostered, &outside_source, &outside_copies);
                const header = line[0] == '!';
                var offset: usize = 1;
                while (offset <= line.len) {
                    try self.finishCell(&cells, &cell_source, &cell_copies, &current, cell_formatting, cell_style);
                    // MediaWiki accepts both separators on a header line; both keep header cells.
                    const split_at = if (header)
                        @min(wikiCellDelimiter(line, "!!", offset) orelse line.len, wikiCellDelimiter(line, "||", offset) orelse line.len)
                    else
                        wikiCellDelimiter(line, "||", offset) orelse line.len;
                    const raw_cell = line[offset..split_at];
                    const content = try self.cellContent(raw_cell);
                    cell_formatting = if (cellAttributePipe(raw_cell)) |pipe|
                        try self.wikiTableFontFormatting(raw_cell[0..pipe], row_formatting)
                    else
                        row_formatting;
                    cell_style = if (cellAttributePipe(raw_cell)) |pipe|
                        try self.wikiTableForeground(.{ .name = "td", .attrs = raw_cell[0..pipe], .end = 0, .closing = false, .self_closing = false }, row_style)
                    else
                        row_style;
                    swatch_foreground = content.swatch_color;
                    if (!try self.swatchCellSourceAllowed(content.text)) swatch_allowed = false;
                    const background_fallback = if (content.rowspan == 1) row_background else null;
                    const background = if (cellAttributePipe(raw_cell)) |pipe| try self.tableCellBackground(.{ .name = "td", .attrs = raw_cell[0..pipe], .end = 0, .closing = false, .self_closing = false }, background_fallback) else background_fallback;
                    current = .{ .spans = &.{}, .header = header, .colspan = content.colspan, .rowspan = content.rowspan, .background = background };
                    try self.appendWikiTableFosteredCopy(&cell_source, &cell_copies, tracked, content.text);
                    if (split_at == line.len) break;
                    offset = split_at + 2;
                }
            } else if (if (syntax.tagAt(line, 0)) |tag| !tag.closing and tag.is("tr") else false) {
                try self.finishWikiTableCaption(&caption, &caption_source, &caption_pending, caption_style, caption_formatting);
                swatch_allowed = false;
                // A trailing malformed caption must not leave partial effects
                // from this row fragment or the preceding fostered source.
                var recover_raw_row = !htmlTableCaptionsComplete(line);
                if (!recover_raw_row) if (try self.semanticTagAt(line, 0)) |tag| {
                    if (tag.is("tr") and !tag.closing) {
                        const pair = optionalTableEnd(line, tag);
                        recover_raw_row = nextHtmlTableCell(line[0..pair.inner_end], tag.end) == null;
                    }
                };
                if (recover_raw_row) {
                    // No cells commit this row. Keep its source for the
                    // same later fostering or full-body rowless recovery,
                    // without registering references before recovery.
                    try self.finishCell(&cells, &cell_source, &cell_copies, &current, cell_formatting, cell_style);
                    if (outside_source.items.len != 0) try outside_source.append(self.a, '\n');
                    try self.appendWikiTableFosteredCopy(&outside_source, &outside_copies, tracked, raw_line);
                    continue;
                }
                try self.flushWikiTableFostered(&fostered, &outside_source, &outside_copies);
                try self.finishCell(&cells, &cell_source, &cell_copies, &current, cell_formatting, cell_style);
                if (cells.items.len != 0) try rows.append(self.a, .{ .cells = try cells.toOwnedSlice(self.a) });
                if (try self.htmlTable(line, &fostered, true, row_style, row_background, null)) |table| {
                    // Reuse the already-rendered caption, including its effects
                    // and scoped spans, in the same source order as wiki captions.
                    try self.appendTableCaption(&caption, table.caption);
                    if (table.caption.len != 0) has_caption = true;
                    try rows.appendSlice(self.a, table.rows);
                }
            } else if (caption_pending) {
                if (caption_source.items.len != 0) try caption_source.append(self.a, '\n');
                try caption_source.appendCopied(self.a, tracked, raw_line);
            } else if (current != null) {
                if (!try self.swatchCellSourceAllowed(raw_line)) swatch_allowed = false;
                // A marker after an empty cell opener starts a block list;
                // the same marker on the opener's own line stays inline text.
                if (cell_source.items.len != 0 or (raw_line.len != 0 and (raw_line[0] == ' ' or std.mem.indexOfScalar(u8, "#*:;", raw_line[0]) != null or self.tableCellHeading(raw_line) != null)))
                    try cell_source.append(self.a, '\n');
                try self.appendWikiTableFosteredCopy(&cell_source, &cell_copies, tracked, raw_line);
            } else {
                // Ordinary text outside a wiki cell is fostered before the
                // table, just as the HTML-table path retains non-cell text.
                if (outside_source.items.len != 0) try outside_source.append(self.a, '\n');
                try self.appendWikiTableFosteredCopy(&outside_source, &outside_copies, tracked, raw_line);
            }
        }
        try self.finishWikiTableCaption(&caption, &caption_source, &caption_pending, caption_style, caption_formatting);
        try self.finishCell(&cells, &cell_source, &cell_copies, &current, cell_formatting, cell_style);
        // Rowless recovery already renders the full body; avoid rendering its
        // outside text twice (including reference-registration side effects).
        if (has_caption or rows.items.len != 0 or cells.items.len != 0)
            try self.flushWikiTableFostered(&fostered, &outside_source, &outside_copies);
        if (body_end == input.len) self.fallbacks.malformed_table = true;
        if (cells.items.len != 0) try rows.append(self.a, .{ .cells = try cells.toOwnedSlice(self.a) });
        try self.resolveZeroRowspans(rows.items, 0);
        const table_value: Table = .{ .caption = try caption.toOwnedSlice(self.a), .rows = try rows.toOwnedSlice(self.a) };
        const feature = if (swatch_allowed and fostered.items.len == 0 and body_end != input.len) try self.swatchFeature(table_value, swatch_background, swatch_foreground) else null;
        return .{ .table = table_value, .feature = feature, .end = pos, .body_end = body_end, .fostered = try fostered.toOwnedSlice(self.a), .has_caption = has_caption };
    }
    // Wiki row/cell attributes share the existing small font declaration
    // contract. Apply before rendering so nested normal overrides remain exact.
    fn wikiTableForeground(self: *Renderer, tag: syntax.Tag, inherited: Style) Error!Style {
        var effective = inherited;
        const foreground = try self.authoredColor(tag, "color", null, inherited.foreground);
        effective.foreground = foreground.value;
        if (foreground.specified) effective.foreground_set = true;
        return effective;
    }
    fn wikiTableFontFormatting(self: *Renderer, attrs: []const u8, inherited: SpanFlags) Error!SpanFlags {
        const tag: syntax.Tag = .{ .name = "td", .attrs = attrs, .end = 0, .closing = false, .self_closing = false };
        var result = inherited;
        if (try self.htmlFontWeight(tag)) |bold| result.bold = bold;
        if (try self.htmlFontStyle(tag)) |italic| result.italic = italic;
        return result;
    }

    fn finishCell(self: *Renderer, cells: *std.ArrayList(Cell), source: *MissingBuffer, copies: *std.ArrayList(HeadingSourceCopy), current: *?Cell, formatting: SpanFlags, style: Style) Error!void {
        if (current.*) |value| {
            if (!self.spend()) {
                source.* = .empty;
                copies.clearRetainingCapacity();
                current.* = null;
                return;
            }
            var cell = value;
            try self.registerHeadingSourceCopies(source.items, copies.items);
            cell.spans = scoped: {
                const inherited_formatting = self.block_formatting;
                const inherited_poem_italic = self.poem_base_style.italic;
                const inherited_language_direction = self.body_language_direction;
                const inherited_attributes = self.body_formatting_attributes;
                defer self.body_language_direction = inherited_language_direction;
                defer self.body_formatting_attributes = inherited_attributes;
                self.body_language_direction = style;
                defer self.block_formatting = inherited_formatting;
                defer self.poem_base_style.italic = inherited_poem_italic;
                self.block_formatting = formatting;
                if (self.poem_depth != 0) self.poem_base_style.italic = formatting.italic;
                break :scoped try self.cellContentSpansWithMissing(source.view(), &cell.blocks);
            };
            try cells.append(self.a, cell);
            source.* = .empty;
            copies.clearRetainingCapacity();
            current.* = null;
        }
    }

    fn tableCellHeading(self: *Renderer, line: []const u8) ?Heading {
        const control_matcher: ?syntax.ControlMatcher = if (self.context.behavior_switches) |registry| .{
            .ctx = registry,
            .match = struct {
                fn match(raw: ?*const anyopaque, value: []const u8, at: usize) ?usize {
                    const profile: *const @import("namespace_registry").behavior_switches.Registry = @ptrCast(@alignCast(raw.?));
                    return profile.matchAt(std.heap.page_allocator, value, at) catch null;
                }
            }.match,
            .toc_match = struct {
                fn match(raw: ?*const anyopaque, value: []const u8, at: usize) ?usize {
                    const profile: *const @import("namespace_registry").behavior_switches.Registry = @ptrCast(@alignCast(raw.?));
                    return profile.tocMatchAt(std.heap.page_allocator, value, at) catch null;
                }
            }.match,
        } else null;
        return headingLineControlled(line, control_matcher);
    }

    fn cellSpansWithMissing(self: *Renderer, tracked: MissingText) Error![]const Span {
        return self.cellContentSpansWithMissing(tracked, null);
    }
    fn cellContentSpansWithMissing(self: *Renderer, tracked: MissingText, blocks: ?*?[]const Block) Error![]const Span {
        const previous = self.body_missing;
        self.body_missing = tracked;
        defer self.body_missing = previous;
        return self.cellContentSpans(tracked.bytes, blocks);
    }
    fn cellSpans(self: *Renderer, source: []const u8) Error![]const Span {
        return self.cellContentSpans(source, null);
    }
    fn blocksNeedCellRetention(blocks: []const Block) bool {
        for (blocks) |block_value| {
            if (block_value.kind == .heading) return true;
            if (block_value.table != null) return true;
        }
        return false;
    }
    fn hasCellHtmlHeading(source: []const u8) bool {
        var at: usize = 0;
        while (std.mem.indexOfScalarPos(u8, source, at, '<')) |open| {
            if (syntax.protectedEnd(source, open)) |end| {
                at = end;
                continue;
            }
            const tag = syntax.tagAt(source, open) orelse {
                at = open + 1;
                continue;
            };
            at = tag.end;
            if (!tag.closing and !tag.self_closing and tag.name.len == 2 and
                std.ascii.toLower(tag.name[0]) == 'h' and tag.name[1] >= '1' and tag.name[1] <= '6') return true;
        }
        return false;
    }
    fn cellContentSpans(self: *Renderer, source: []const u8, retained: ?*?[]const Block) Error![]const Span {
        // Cells are local inline domains. Preserve ordinary cell-opener text,
        // but retain real later heading blocks rather than flattening identity.
        const previous_target = self.body_link_target;
        self.body_link_target = "";
        defer self.body_link_target = previous_target;
        var no_more_nowiki_close = false;
        var has_blocks = false;
        var pos: usize = 0;
        while (pos < source.len) {
            const end = syntax.logicalEndCached(source, pos, &no_more_nowiki_close);
            if (pos != 0 and end != pos and (source[pos] == ' ' or std.mem.indexOfScalar(u8, "#*:;", source[pos]) != null or self.tableCellHeading(source[pos..end]) != null)) has_blocks = true;
            pos = if (end < source.len) end + 1 else end;
        }
        if (retained != null and hasCellHtmlHeading(source)) has_blocks = true;
        if (!has_blocks and std.mem.indexOf(u8, source, "{|") == null) return self.parseBodySpans(source, .{});
        const parent = self.spans;
        self.spans = .empty;
        defer self.spans = parent;
        var body = source;
        var prefix: []const Span = &.{};
        const first_end = syntax.logicalEnd(source, 0);
        if (source.len != 0 and (std.mem.indexOfScalar(u8, "#*:;", source[0]) != null or self.tableCellHeading(source[0..first_end]) != null)) {
            prefix = try self.parseBodySpans(source[0..first_end], .{});
            body = source[if (first_end < source.len) first_end + 1 else first_end..];
        }
        const tracked_body = if (self.body_missing) |missing_parent| try self.missingSliceWithHeadingSource(missing_parent, body) else MissingText.untracked(body);
        const blocks = try self.renderBodyWithOrphanOrigin(tracked_body, body.ptr == source.ptr);
        if (retained) |output| if (blocksNeedCellRetention(blocks)) {
            if (prefix.len == 0) {
                output.* = blocks;
            } else {
                const ordered = try self.a.alloc(Block, blocks.len + 1);
                ordered[0] = .{ .kind = .paragraph, .spans = prefix };
                @memcpy(ordered[1..], blocks);
                output.* = ordered;
            }
            return &.{};
        };
        try self.spans.appendSlice(self.a, prefix);
        if (prefix.len != 0 and body.len != 0) try self.lineBreak(.{});
        try self.blocksInline(blocks, .{});
        return self.spans.toOwnedSlice(self.a);
    }

    fn resolveZeroRowspans(self: *Renderer, rows: []Row, group_start: usize) Error!void {
        for (rows[group_start..], group_start..) |*row, index| {
            var has_zero = false;
            for (row.cells) |cell| {
                if (cell.rowspan == 0) has_zero = true;
            }
            if (!has_zero) continue;
            // Cells are const slices; copy only rows needing normalization.
            const cells = try self.a.dupe(Cell, row.cells);
            for (cells) |*cell| {
                if (cell.rowspan == 0) cell.rowspan = @intCast(@min(rows.len - index, 100));
            }
            row.cells = cells;
        }
    }
    fn tableSpanAttr(self: *Renderer, tag: syntax.Tag, name: []const u8) Error!u16 {
        const raw = (try self.semanticAttribute(tag, name)) orelse return 1;
        const parsed = std.fmt.parseInt(u16, raw, 10) catch 1;
        // Zero is build-only: the completed row group resolves it before encoding.
        if (parsed == 0 and std.mem.eql(u8, name, "rowspan")) return 0;
        return @max(1, @min(100, parsed));
    }

    fn cellAttributePipe(raw: []const u8) ?usize {
        // logicalEnd can include a whole multiline HTML wrapper. Attributes
        // belong only to the cell's opening physical line, not its nested body.
        const end = std.mem.indexOfAny(u8, raw, "\r\n") orelse raw.len;
        const line = raw[0..end];
        const interesting = [_]u8{ '|', '<', '{', '[' };
        var i: usize = 0;
        while (i < line.len) {
            i += std.mem.indexOfAny(u8, line[i..], &interesting) orelse return null;
            if (line[i] == '|') return i;
            if (line[i] == '<') {
                if (syntax.protectedEnd(line, i)) |protected_end| {
                    i = protected_end;
                    continue;
                }
                if (syntax.tagAt(line, i)) |tag| {
                    i = tag.end;
                    continue;
                }
            }
            if (starts(line[i..], "{{") or starts(line[i..], "[[")) {
                if (syntax.balanced(line, i)) |pair| {
                    i = pair.end;
                    continue;
                }
                return null;
            }
            i += 1;
        }
        return null;
    }

    // Wiki table cells are split before internal links. Link/template token
    // balancing therefore cannot hide raw table separators. Earlier strip
    // regions stay opaque; allowed HTML attributes are armored by Sanitizer.
    // Earlier strip regions and Sanitizer-armored attributes can contain raw
    // LF in this compiler input. Ordinary link/template/container balancing
    // cannot hide a physical wiki-table marker before the internal-link pass.
    fn wikiTableLineEnd(input: []const u8, start: usize) usize {
        var no_more_nowiki_close = false;
        var opaque_scan: syntax.OpaqueScan = .{};
        var at = start;
        while (at < input.len) {
            const relative = std.mem.indexOfAny(u8, input[at..], "\n<") orelse return input.len;
            at += relative;
            if (input[at] == '\n') return at;
            if (opaque_scan.protectedEnd(input, at, &no_more_nowiki_close)) |end| {
                at = end;
                continue;
            }
            if (opaque_scan.tagAt(input, at, &no_more_nowiki_close)) |tag| {
                if (wikiTableArmoredTag(tag)) {
                    at = tag.end;
                    continue;
                }
            }
            at += 1;
        }
        return input.len;
    }
    fn wikiTableArmoredTag(tag: syntax.Tag) bool {
        return oneOf(tag.name, &.{
            "b",      "bdi",  "del",  "i",    "ins",    "u",          "font", "big",  "small", "sub",   "sup",
            "h1",     "h2",   "h3",   "h4",   "h5",     "h6",         "cite", "code", "em",    "s",     "strike",
            "strong", "tt",   "var",  "div",  "center", "blockquote", "ol",   "ul",   "dl",    "table", "caption",
            "pre",    "ruby", "rb",   "rp",   "rt",     "rtc",        "p",    "span", "abbr",  "dfn",   "kbd",
            "samp",   "data", "time", "mark", "br",     "wbr",        "hr",   "li",   "dt",    "dd",    "tr",
            "td",     "th",   "q",    "bdo",
        }) or (tag.is("meta") and tag.attr("itemprop") != null and tag.attr("content") != null) or
            (tag.is("link") and tag.attr("itemprop") != null and tag.attr("href") != null);
    }

    fn wikiCellDelimiter(line: []const u8, needle: []const u8, start: usize) ?usize {
        var no_more_nowiki_close = false;
        var opaque_scan: syntax.OpaqueScan = .{};
        var i = start;
        while (i < line.len) {
            if (starts(line[i..], needle)) return i;
            if (line[i] == '<') {
                if (opaque_scan.protectedEnd(line, i, &no_more_nowiki_close)) |end| {
                    i = end;
                    continue;
                }
                if (opaque_scan.tagAt(line, i, &no_more_nowiki_close)) |tag| {
                    if (wikiTableArmoredTag(tag)) {
                        i = tag.end;
                        continue;
                    }
                }
            }
            i += 1;
        }
        return null;
    }

    fn cellContent(self: *Renderer, raw: []const u8) Error!CellContent {
        if (cellAttributePipe(raw)) |pipe| {
            const tag: syntax.Tag = .{ .name = "td", .attrs = raw[0..pipe], .end = 0, .closing = false, .self_closing = false };
            return .{
                .text = trim(raw[pipe + 1 ..]),
                .colspan = try self.tableSpanAttr(tag, "colspan"),
                .rowspan = try self.tableSpanAttr(tag, "rowspan"),
                .swatch_color = try self.swatchCssHex(tag, "color"),
            };
        }
        return .{ .text = trim(raw) };
    }

    fn appendTableInlineSpans(self: *Renderer, spans: []const Span, background: ?[]const u8, remaining: *usize) Error!void {
        if (spans.len > remaining.*) return error.RenderLimit;
        remaining.* -= spans.len;
        for (spans) |span| {
            var painted = span;
            if (painted.background == null) painted.background = background;
            try self.spans.append(self.a, painted);
        }
    }
    fn tableInlineWithBudget(self: *Renderer, table: Table, style: Style, leading_row_break: bool, background: ?[]const u8, depth: usize, remaining: *usize) Error!void {
        if (depth >= @import("blob_encoder").presentation_types.max_table_depth or !htmlNestedSpend(remaining)) return error.RenderLimit;
        // A child caption is inside its containing cell but outside its own
        // cells. Structural separators never acquire a cell's paint.
        try self.appendTableInlineSpans(table.caption, background, remaining);
        for (table.rows, 0..) |row, ri| {
            if (!htmlNestedSpend(remaining)) return error.RenderLimit;
            if (leading_row_break or ri != 0 or table.caption.len != 0) try self.lineBreak(style);
            for (row.cells, 0..) |cell, ci| {
                if (!htmlNestedSpend(remaining)) return error.RenderLimit;
                if (ci != 0) try self.text(" · ", style);
                const cell_background = cell.background orelse background;
                if (cell.blocks) |blocks| {
                    try self.cellBlocksInlineWithBudget(blocks, style, cell_background, depth, remaining);
                } else {
                    try self.appendTableInlineSpans(cell.spans, cell_background, remaining);
                    if (cell.nested_table) |child|
                        try self.tableInlineWithBudget(child, style, false, cell_background, depth + 1, remaining);
                }
            }
        }
    }
    fn cellBlocksInlineWithBudget(self: *Renderer, blocks: []const Block, style: Style, background: ?[]const u8, depth: usize, remaining: *usize) Error!void {
        for (blocks, 0..) |block_value, index| {
            if (!htmlNestedSpend(remaining)) return error.RenderLimit;
            if (index != 0) try self.lineBreak(style);
            const label_start = self.spans.items.len;
            if (block_value.list_path.len != 0) switch (block_value.list_path[block_value.list_path.len - 1]) {
                '*' => try self.text("• ", style),
                '#' => if (block_value.number.len != 0) {
                    try self.text(block_value.number, style);
                    try self.text(". ", style);
                },
                else => {},
            };
            for (self.spans.items[label_start..]) |*span| if (span.background == null) {
                span.background = background;
            };
            try self.appendTableInlineSpans(block_value.spans, background, remaining);
            if (block_value.table) |child| try self.tableInlineWithBudget(child, style, false, background, depth + 1, remaining);
        }
    }
    fn tableInline(self: *Renderer, table: Table, style: Style, leading_row_break: bool) Error!void {
        var remaining: usize = 1 << 20;
        try self.tableInlineWithBudget(table, style, leading_row_break, null, 0, &remaining);
    }

    // Span-only containment keeps table reading order and explicit row/cell
    // boundaries; its text projection does not recreate table geometry.
    fn blocksInline(self: *Renderer, blocks: []const Block, style: Style) Error!void {
        for (blocks, 0..) |b, index| {
            if (index != 0) try self.lineBreak(style);
            // List labels live on blocks, while DPR2 table cells hold spans.
            // Continuation paths (ending in ':') carry no repeated label.
            if (b.list_path.len != 0) switch (b.list_path[b.list_path.len - 1]) {
                '*' => try self.text("• ", style),
                '#' => if (b.number.len != 0) {
                    try self.text(b.number, style);
                    try self.text(". ", style);
                },
                else => {},
            };
            try self.spans.appendSlice(self.a, b.spans);
            if (b.table) |table| try self.tableInline(table, style, false);
        }
    }
};
const Heading = struct { level: u8, title: []const u8 };
fn headingLine(line: []const u8) ?Heading {
    return headingLineControlled(line, null);
}

fn headingLineControlled(line: []const u8, matcher: ?syntax.ControlMatcher) ?Heading {
    const heading = syntax.controlHeading(line, matcher) orelse return null;
    const title = trim(heading.title);
    if (title.len == 0) return null;
    return .{ .level = heading.level, .title = title };
}
const CellContent = struct { text: []const u8, colspan: u16 = 1, rowspan: u16 = 1, swatch_color: ?[]const u8 = null };

fn flattened(a: A, spans: []const Span) ![]u8 {
    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(a);
    for (spans) |s| try out.appendSlice(a, s.text);
    return out.toOwnedSlice(a);
}
test "reference identity fast paths remain exact" {
    try std.testing.expect(referenceStringEqual("", ""));
    try std.testing.expect(referenceStringEqual("r7", "r7"));
    try std.testing.expect(!referenceStringEqual("r7", "r8"));
    try std.testing.expect(referenceStringEqual("abc", "abc"));
    try std.testing.expect(!referenceStringEqual("abc", "abd"));
    try std.testing.expect(referenceStringEqual("abcdefgh", "abcdefgh"));
    try std.testing.expect(!referenceStringEqual("abcdefgh", "abcdxfgh"));
    try std.testing.expect(referenceStringEqual("abcdefghijklmnop", "abcdefghijklmnop"));
    try std.testing.expect(!referenceStringEqual("abcdefghijklmnop", "abcdefxhijklmnop"));
    try std.testing.expect(!referenceStringEqual("same", "same!"));
}

test "renderer resolves Wiktionary definitions links labels and multiline quotations" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var r: Renderer = .{ .a = a, .context = .{ .title = "cat activation noise" } };
    const blocks = try r.renderBody("{{en-noun}}\n\n#{{lb|en|Internet slang|humorous}} The '''[[trill]]''' sound.\n\n{{quote-text|en|year=2018|title=Why do cats trill?\n|passage=The {{m|en|cat}} makes a noise.}}\n");
    try std.testing.expectEqual(@as(usize, 3), blocks.len);
    try std.testing.expectEqual(Kind.definition, blocks[1].kind);
    try std.testing.expectEqualStrings("1", blocks[1].number);
    try std.testing.expectEqualStrings("(Internet slang, humorous) The trill sound.", try flattened(a, blocks[1].spans));
    try std.testing.expectEqual(Kind.quotation, blocks[2].kind);
    try std.testing.expectEqualStrings("The cat makes a noise.\nWhy do cats trill?, 2018\n", try flattened(a, blocks[2].spans));
    try std.testing.expectEqual(@as(usize, 4), r.rendered_templates);
    try std.testing.expectEqual(@as(usize, 0), r.unresolved_templates);
}
