        "\u{202f}", "\u{205f}", "\u{3000}",                "&nbsp;",                  "&#160;",                     "&#000160;",
        "&#xA0;",   "&#X00a0;", "&nb__NOEDITSECTION__sp;", "&__NOEDITSECTION__nbsp;", "&#000__NOEDITSECTION__160;", "&#x00__NOEDITSECTION__A0;",
    }) |separator| {
        var r: Renderer = .{ .a = a, .context = .{} };
