    try std.testing.expectEqualStrings("IPA wikidict-poem wikidict-poem-indent-2 wikidict-poem-dir-rtl", classes);
    // Raw-LF fallback resets depth only and keeps the enclosing direction.
    r.poem_depth = 1;
