        "not-font-weight: bold",                            "font-weight bold",                                 "font-weight: boldness",
        "font-weight:bold; --x:{x:0; font-weight:normal;}", "font-weight:normal; --x:{x:0; font-weight:bold;}", "font-weight:normal; --x:[x:0; font-weight:bold;]",
    };
