    };
    try std.testing.expect(seen);
    var images: Renderer = .{ .a = a, .context = .{} };
    const media = try images.parseSpans("<span class=\"template-chem2-su\"><span>[[File:Charge.png|−]]</span><span>2</span></span>", .{ .classes = "chemf" });
    try ChemicalScriptStackTest.unscripted(media);
    try std.testing.expectEqual(@as(usize, 1), images.media.items.len);
    try std.testing.expectEqualStrings("Charge.png", images.media.items[0].file);
    var unclosed: Renderer = .{ .a = a, .context = .{} };
    const open = try unclosed.parseSpans(exact[0 .. exact.len - "</span>".len], .{ .classes = "chemf" });
    try std.testing.expectEqualStrings("−2", try FormattingScopeTest.text(a, open));
    try ChemicalScriptStackTest.unscripted(open);
    try std.testing.expect(unclosed.fallbacks.unclosed_formatting);
    // The existing one-sided HTML scripts retain their authored order and roles.
    var single: Renderer = .{ .a = a, .context = .{} };
    const one_sided = try single.renderBody("<span class=\"chemf\">H<sub class=\"template-chem2-sub\">2</sub><sup class=\"template-chem2-sup\">−</sup></span>");
    try FormattingScopeTest.word(a, one_sided, "2", .{ .classes = "chemf template-chem2-sub", .subscript = true });
    try FormattingScopeTest.word(a, one_sided, "−", .{ .classes = "chemf template-chem2-sup", .superscript = true });
}

test "closing-only external URL braces retain actions and isolate literal runs" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const cases = [_]struct { raw: []const u8, target: []const u8, visible: []const u8, literal: bool }{
        .{ .raw = "https://example.test/a}}tail", .target = "https://example.test/a}}tail", .visible = "https://example.test/a}}tail", .literal = true },
        .{ .raw = "https://example.test/a&#125;&#125;tail", .target = "https://example.test/a}}tail", .visible = "https://example.test/a}}tail", .literal = true },
        .{ .raw = "https://example.test/a%7D%7Dtail", .target = "https://example.test/a%7D%7Dtail", .visible = "https://example.test/a%7D%7Dtail", .literal = false },
    };
    for (cases) |item| {
        var r: Renderer = .{ .a = a, .context = .{} };
        try r.link(item.raw, item.raw, .{ .bold = true, .italic = true, .language = "okm", .direction = "rtl", .classes = "source-url", .role = .example }, 0, true);
        try std.testing.expectEqualStrings(item.visible, try plainText(a, r.spans.items));
        var literal_count: usize = 0;
        var parsed_count: usize = 0;
        for (r.spans.items) |span| {
            try std.testing.expect(span.kind == .external_link and span.flags.bold and span.flags.italic);
            try std.testing.expectEqualStrings(item.target, span.target);
            try std.testing.expectEqualStrings("okm", span.language);
            try std.testing.expectEqualStrings("rtl", span.direction);
            try std.testing.expectEqualStrings("source-url", span.classes);
            try std.testing.expect(span.role == .example);
            if (span.provenance == .protected_literal) {
                literal_count += 1;
                try std.testing.expectEqualStrings("}}", span.text);
            } else {
                parsed_count += 1;
                try std.testing.expect(span.provenance == .parsed);
            }
        }
        try std.testing.expectEqual(@as(usize, if (item.literal) 1 else 0), literal_count);
        try std.testing.expect(parsed_count != 0);
        try std.testing.expect(!r.fallbacks.rejected_external_target);
    }
    var labeled: Renderer = .{ .a = a, .context = .{} };
    try labeled.link("<b>clean</b> <i>label</i>", "https://example.test/a}}", .{}, 0, true);
    for (labeled.spans.items) |span| {
        try std.testing.expect(span.provenance == .parsed and span.kind == .external_link);
        if (std.mem.eql(u8, span.text, "clean")) try std.testing.expect(span.flags.bold);
        if (std.mem.eql(u8, span.text, "label")) try std.testing.expect(span.flags.italic);
    }
    try std.testing.expect(unresolvedActionTarget("https://example.test/a}}"));
    try std.testing.expect(unresolvedExternalActionTarget("not-a-url}}"));
    try std.testing.expect(unresolvedExternalActionTarget("https://example.test/{{missing}}"));
    var refused: Renderer = .{ .a = a, .context = .{} };
    try std.testing.expectError(error.UncompiledTemplate, refused.link("https://example.test/{{missing}}", "https://example.test/{{missing}}", .{}, 0, true));
}

test "HTML list font inheritance preserves nested overrides and continuation scope through DPR2" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const source = "<ul style='font-weight:bold;font-style:italic'><li>parent<ol><li>nested</li><li style='font-weight:normal;font-style:normal'>clear<ul><li>ordinary</li></ul></li></ol>tail</li><li>sibling</li></ul>outside";
    var renderer: Renderer = .{ .a = a, .context = .{} };
    const blocks = try renderer.renderBody(source);
    const stored = try FormattingScopeTest.encode(a, &renderer, blocks);
    for ([_][]const u8{ "parent", "nested", "tail", "sibling" }) |word| {
        try FormattingScopeTest.word(a, blocks, word, .{ .bold = true, .italic = true });
        try FormattingScopeTest.word(a, stored.entry.sections[0].blocks, word, .{ .bold = true, .italic = true });
    }
    for ([_][]const u8{ "clear", "ordinary", "outside" }) |word| {
        try FormattingScopeTest.word(a, blocks, word, .{});
        try FormattingScopeTest.word(a, stored.entry.sections[0].blocks, word, .{});
    }
    try std.testing.expect(!renderer.fallbacks.any());
    // Item font scope also encloses a nested typed table without styling later siblings.
    var table_renderer: Renderer = .{ .a = a, .context = .{} };
    const table_blocks = try table_renderer.renderBody("<ul><li style='font-weight:bold;font-style:italic'>lead<table><tr><td>cell</td></tr></table>end</li><li>plain</li></ul>");
    const TableCheck = struct {
        fn check(allocator: A, values: anytype) !void {
            var table_count: usize = 0;
            for (values) |value| if (value.table) |table| {
                table_count += 1;
                try std.testing.expectEqual(@as(usize, 1), table.rows.len);
                try std.testing.expectEqual(@as(usize, 1), table.rows[0].cells.len);
                const cell = table.rows[0].cells[0];
                try std.testing.expect(cell.spans.len != 0);
                try std.testing.expectEqualStrings("cell", try FormattingScopeTest.text(allocator, cell.spans));
                for (cell.spans) |span| {
                    const bold = if (@hasField(@TypeOf(span), "flags")) span.flags.bold else span.bold;
                    const italic = if (@hasField(@TypeOf(span), "flags")) span.flags.italic else span.italic;
                    try std.testing.expect(bold and italic);
                }
            };
            try std.testing.expectEqual(@as(usize, 1), table_count);
        }
    };
    try TableCheck.check(a, table_blocks);
    const table_stored = try FormattingScopeTest.encode(a, &table_renderer, table_blocks);
    try TableCheck.check(a, table_stored.entry.sections[0].blocks);
    try FormattingScopeTest.word(a, table_blocks, "end", .{ .bold = true, .italic = true });
    try FormattingScopeTest.word(a, table_blocks, "plain", .{});
    try FormattingScopeTest.word(a, table_stored.entry.sections[0].blocks, "end", .{ .bold = true, .italic = true });
    try FormattingScopeTest.word(a, table_stored.entry.sections[0].blocks, "plain", .{});
    // Weight overrides mirror the existing italic scopes on typed table parts.
    const TableScopeCheck = struct {
        fn check(allocator: A, values: anytype, row_cells: []const usize, texts: []const []const u8, weights: []const bool, caption_text: []const u8) !void {
            var table_count: usize = 0;
            for (values) |value| if (value.table) |table| {
                table_count += 1;
                try std.testing.expectEqualStrings(caption_text, try FormattingScopeTest.text(allocator, table.caption));
                for (table.caption) |span| {
                    const bold = if (@hasField(@TypeOf(span), "flags")) span.flags.bold else span.bold;
                    const italic = if (@hasField(@TypeOf(span), "flags")) span.flags.italic else span.italic;
                    try std.testing.expect(!bold and italic);
                }
                try std.testing.expectEqual(row_cells.len, table.rows.len);
                var cell_index: usize = 0;
                for (table.rows, row_cells) |row, wanted_cells| {
                    try std.testing.expectEqual(wanted_cells, row.cells.len);
                    for (row.cells) |cell| {
                        try std.testing.expect(!cell.header);
                        try std.testing.expect(cell.spans.len != 0);
                        try std.testing.expect(cell_index < texts.len);
                        try std.testing.expectEqualStrings(texts[cell_index], try FormattingScopeTest.text(allocator, cell.spans));
                        for (cell.spans) |span| {
                            const bold = if (@hasField(@TypeOf(span), "flags")) span.flags.bold else span.bold;
                            const italic = if (@hasField(@TypeOf(span), "flags")) span.flags.italic else span.italic;
                            try std.testing.expectEqual(weights[cell_index], bold);
                            try std.testing.expect(italic);
                        }
                        cell_index += 1;
                    }
                }
                try std.testing.expectEqual(texts.len, cell_index);
            };
            try std.testing.expectEqual(@as(usize, 1), table_count);
        }
    };
    const table_cases = [_]struct { body: []const u8, rows: []const usize, texts: []const []const u8, weights: []const bool, caption: []const u8 = "" }{
        .{ .body = "<table><tr><td style='font-weight:normal'>reset</td><td>inherited</td></tr><tr style='font-weight:normal'><td>rowPlain</td><td style='font-weight:bold'>local</td></tr><tr><td>restored</td><td>final</td></tr></table>", .rows = &.{ 2, 2, 2 }, .texts = &.{ "reset", "inherited", "rowPlain", "local", "restored", "final" }, .weights = &.{ false, true, false, true, true, true } },
        .{ .body = "<table style='font-weight:normal'><caption>caption</caption><tr><td>container</td></tr></table>", .rows = &.{1}, .texts = &.{"container"}, .weights = &.{false}, .caption = "caption" },
        .{ .body = "<table><caption style='font-weight:normal'>caption</caption><tr><td>body</td></tr></table>", .rows = &.{1}, .texts = &.{"body"}, .weights = &.{true}, .caption = "caption" },
    };
    for (table_cases) |case| {
        const scoped_source = try std.fmt.allocPrint(a, "<ul><li style='font-weight:bold;font-style:italic'>lead{s}scopeEnd</li><li>scopeSibling</li></ul>scopeOutside", .{case.body});
        var scoped_renderer: Renderer = .{ .a = a, .context = .{} };
        const scoped_blocks = try scoped_renderer.renderBody(scoped_source);
        const scoped_stored = try FormattingScopeTest.encode(a, &scoped_renderer, scoped_blocks);
        try TableScopeCheck.check(a, scoped_blocks, case.rows, case.texts, case.weights, case.caption);
        try TableScopeCheck.check(a, scoped_stored.entry.sections[0].blocks, case.rows, case.texts, case.weights, case.caption);
        try FormattingScopeTest.word(a, scoped_blocks, "scopeEnd", .{ .bold = true, .italic = true });
        try FormattingScopeTest.word(a, scoped_stored.entry.sections[0].blocks, "scopeEnd", .{ .bold = true, .italic = true });
        for ([_][]const u8{ "scopeSibling", "scopeOutside" }) |word| {
            try FormattingScopeTest.word(a, scoped_blocks, word, .{});
            try FormattingScopeTest.word(a, scoped_stored.entry.sections[0].blocks, word, .{});
        }
        try std.testing.expect(!scoped_renderer.fallbacks.any());
    }
    // A lexical prefix forces the shorthand wrapper through the inline HTML
    // route, where inherited Style fonts need not already be block flags.
    const inline_source = "prefix <b><i><ul><li>lead<table><tr><td>inheritedCell</td><td style='font-weight:normal;font-style:normal'>normalCell</td></tr></table>itemTail</li><li style='font-weight:normal;font-style:normal'>normalItem</li><li>afterItem</li></ul></i></b> suffix";
    var inline_renderer: Renderer = .{ .a = a, .context = .{} };
    const inline_blocks = try inline_renderer.renderBody(inline_source);
    const inline_stored = try FormattingScopeTest.encode(a, &inline_renderer, inline_blocks);
    for ([_][]const u8{ "lead", "inheritedCell", "itemTail", "afterItem" }) |word| {
        try FormattingScopeTest.word(a, inline_blocks, word, .{ .bold = true, .italic = true });
        try FormattingScopeTest.word(a, inline_stored.entry.sections[0].blocks, word, .{ .bold = true, .italic = true });
    }
    for ([_][]const u8{ "prefix", "normalCell", "normalItem", "suffix" }) |word| {
        try FormattingScopeTest.word(a, inline_blocks, word, .{});
        try FormattingScopeTest.word(a, inline_stored.entry.sections[0].blocks, word, .{});
    }
    try std.testing.expect(!inline_renderer.fallbacks.any());
}

test "captured Bleoh swatches and BEN dialect colors preserve typed RGB through DPR4" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const source = "== Englisc bleoh ==\n\n{| cellpadding=\"5\" cellspacing=\"0\" border=\"1\"\n|-  bgcolor=\"#eeeeee\"\n| [[blæc]]\n| bgcolor=\"black\" | &nbsp;\n|-  bgcolor=\"#eeeeee\"\n| [[grǣg]]\n| bgcolor=\"gray\" | &nbsp;\n|- bgcolor=\"#eeeeee\"\n| [[hwīt]]\n| bgcolor=\"white\" | &nbsp;\n|- bgcolor=\"#eeeeee\"\n| [[Seolfor|seolfor]]\n| bgcolor=\"silver\" | &nbsp;\n|- bgcolor=\"#eeeeee\"\n| [[gold]]\n| bgcolor=\"gold\" | &nbsp;\n|- bgcolor=\"#eeeeee\"\n| [[rēod]]\n| bgcolor=\"red\" | &nbsp;\n|- bgcolor=\"#eeeeee\"\n| [[basu]]\n| bgcolor=\"purple\" | &nbsp;\n|- bgcolor=\"#eeeeee\"\n| [[hǣwen]]\n| bgcolor=\"blue\" | &nbsp;\n|- bgcolor=\"#eeeeee\"\n| [[grēne]]\n| bgcolor=\"green\" | &nbsp;\n|- bgcolor=\"#eeeeee\"\n| [[geolu]]\n| bgcolor=\"yellow\" | &nbsp;\n|- bgcolor=\"#eeeeee\"\n| [[geolorēad]]\n| bgcolor=\"orange\" | &nbsp;\n|}\n\n\n[[Category:Portas]]";
    const labels = [_][]const u8{ "blæc", "grǣg", "hwīt", "seolfor", "gold", "rēod", "basu", "hǣwen", "grēne", "geolu", "geolorēad" };
    const targets = [_][]const u8{ "blæc", "grǣg", "hwīt", "Seolfor", "gold", "rēod", "basu", "hǣwen", "grēne", "geolu", "geolorēad" };
    const colors = [_][]const u8{ "#000000", "#808080", "#ffffff", "#c0c0c0", "#ffd700", "#ff0000", "#800080", "#0000ff", "#008000", "#ffff00", "#ffa500" };
    const Check = struct {
        fn table(blocks: anytype, expected_labels: []const []const u8, expected_targets: []const []const u8, expected_colors: []const []const u8) !void {
            var found: usize = 0;
            for (blocks) |block| if (block.table) |table_value| {
                found += 1;
                try std.testing.expectEqual(@as(usize, 11), table_value.rows.len);
                for (table_value.rows, expected_labels, expected_targets, expected_colors) |row, label, target, color| {
                    try std.testing.expectEqual(@as(usize, 2), row.cells.len);
                    const left = row.cells[0];
                    const right = row.cells[1];
                    try std.testing.expectEqualStrings("#eeeeee", left.background.?);
                    try std.testing.expectEqualStrings(color, right.background.?);
                    try std.testing.expectEqual(@as(usize, 1), left.spans.len);
                    try std.testing.expectEqual(@as(usize, 1), right.spans.len);
                    try std.testing.expectEqualStrings(label, left.spans[0].text);
                    try std.testing.expectEqualStrings(target, left.spans[0].target);
                    try std.testing.expect(left.spans[0].kind == .link);
                    try std.testing.expectEqualStrings(" ", right.spans[0].text);
                    try std.testing.expect(right.spans[0].kind == .text and right.spans[0].target.len == 0);
                    for (row.cells) |cell| {
                        try std.testing.expect(!cell.header and cell.colspan == 1 and cell.rowspan == 1);
                        try std.testing.expect(cell.spans[0].foreground == null);
                    }
                }
            };
            try std.testing.expectEqual(@as(usize, 1), found);
        }
        fn ben(allocator: A, blocks: anytype) !void {
            var seen = [_]bool{ false, false, false, false };
            const words = [_][]const u8{ "berda", "asul", "turquesa", "bas aiguanebar" };
            const expected = [_][]const u8{ "#008000", "#1c39bb", "#01796f", "#ff4040" };
            var tables: usize = 0;
            for (blocks) |block| if (block.table) |table_value| {
                tables += 1;
                try std.testing.expectEqual(@as(usize, 2), table_value.rows.len);
                for (table_value.rows, 0..) |row, row_index| for (row.cells) |cell| {
                    try std.testing.expectEqualStrings(if (row_index == 0) "#e2e4c0" else "#f0f0f0", cell.background.?);
                    try std.testing.expect(cell.colspan == (if (row_index == 0) @as(u16, 8) else 1));
                    for (cell.spans) |span| for (words, expected, 0..) |word, color, i| if (std.mem.eql(u8, span.text, word)) {
                        try std.testing.expectEqualStrings(color, span.foreground.?);
                        if (comptime @hasField(@TypeOf(span), "flags")) {
                            if (i == 3) try std.testing.expect(span.flags.bold) else try std.testing.expect(span.flags.small);
                        } else {
                            if (i == 3) try std.testing.expect(span.bold) else try std.testing.expect(span.small);
                        }
                        seen[i] = true;
                    };
                };
                const caption_text = try FormattingScopeTest.text(allocator, table_value.rows[0].cells[0].spans);
                try std.testing.expectEqualStrings("En color berda les diferensies dan el primer, en asul les que ten dan el segundo. Dan el turquesa se marquen les que fan diferensia d'es dos.", caption_text);
            };
            for (seen) |present| try std.testing.expect(present);
            try std.testing.expectEqual(@as(usize, 1), tables);
        }
    };
    var renderer: Renderer = .{ .a = a, .context = .{} };
    const blocks = try renderer.renderBody(source);
    try Check.table(blocks, &labels, &targets, &colors);
    const stored = try FormattingScopeTest.encode(a, &renderer, blocks);
    try Check.table(stored.entry.sections[0].blocks, &labels, &targets, &colors);
    var ben_renderer: Renderer = .{ .a = a, .context = .{} };
    const ben_blocks = try ben_renderer.renderBody("<table style=\"background:#F0F0F0\"><tr><th colspan=\"8\" style=\"background:#e2e4c0\"><small>En color <span style=\"color:#008000;\">berda</span> les diferensies dan el primer, en <span style=\"color:#1C39BB;\">asul</span> les que ten dan el segundo. Dan el <span style=\"color:#01796F;\">turquesa</span> se marquen les que fan diferensia d'es dos.</small></th></tr><tr><td><span style=\"color:#FF4040;\">'''bas aiguanebar'''</span></td></tr></table>");
    try Check.ben(a, ben_blocks);
    const ben_stored = try FormattingScopeTest.encode(a, &ben_renderer, ben_blocks);
    try Check.ben(a, ben_stored.entry.sections[0].blocks);
}

test "authored RGB declaration precedence preserves scopes actions and unrelated CSS" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var renderer: Renderer = .{ .a = a, .context = .{} };
    const source = "{| class=wikitable bgcolor='#abc'\n|- bgcolor='#eeeeee'\n| style=\"font-family:'x;y';background-color:RED\" | [[A|red]]\n| style='background-color:blue!important;background-color:green' | [[B|blue]]\n| style='background-color:transparent' | row\n| style='background:url(x)' | unsupported\n|-\n| fallback\n|}";
    const blocks = try renderer.renderBody(source);
    const stored = try FormattingScopeTest.encode(a, &renderer, blocks);
    const Check = struct {
        fn table(blocks_value: anytype) !void {
            var tables: usize = 0;
            for (blocks_value) |block| if (block.table) |table_value| {
                tables += 1;
                try std.testing.expectEqual(@as(usize, 2), table_value.rows.len);
                try std.testing.expectEqual(@as(usize, 4), table_value.rows[0].cells.len);
                const cells = table_value.rows[0].cells;
                try std.testing.expectEqualStrings("#ff0000", cells[0].background.?);
                try std.testing.expectEqualStrings("#0000ff", cells[1].background.?);
                try std.testing.expectEqualStrings("#eeeeee", cells[2].background.?);
                try std.testing.expect(cells[3].background == null);
                try std.testing.expectEqualStrings("A", cells[0].spans[0].target);
                try std.testing.expectEqualStrings("B", cells[1].spans[0].target);
                try std.testing.expectEqualStrings("#aabbcc", table_value.rows[1].cells[0].background.?);
            };
            try std.testing.expectEqual(@as(usize, 1), tables);
        }
        fn spans(values: anytype) !void {
            var text: std.ArrayList(u8) = .empty;
            defer text.deinit(std.testing.allocator);
            var actions: usize = 0;
            var green: usize = 0;
            var blue: usize = 0;
            var reset: usize = 0;
            for (values) |span| {
                try text.appendSlice(std.testing.allocator, span.text);
                if (span.target.len != 0) {
                    actions += 1;
                    try std.testing.expectEqualStrings("A", span.target);
                    try std.testing.expectEqualStrings("#008000", span.foreground.?);
                }
                if (std.mem.indexOf(u8, span.text, "green") != null) {
                    green += 1;
                    try std.testing.expectEqualStrings("#008000", span.foreground.?);
                }
                if (std.mem.eql(u8, span.text, "blue")) {
                    blue += 1;
                    try std.testing.expectEqualStrings("#1c39bb", span.foreground.?);
                }
                if (std.mem.eql(u8, span.text, "reset")) {
                    reset += 1;
                    try std.testing.expect(span.foreground == null);
                }
            }
            try std.testing.expectEqualStrings("green link italicbluegreenresetgreen plain", text.items);
            try std.testing.expect(actions == 1 and green == 3 and blue == 1 and reset == 1);
            try std.testing.expect(values[values.len - 1].foreground == null);
        }
    };
    try Check.table(blocks);
    try Check.table(stored.entry.sections[0].blocks);
    var inline_renderer: Renderer = .{ .a = a, .context = .{} };
    const inline_blocks = try inline_renderer.renderBody("<span class=note style=\"font-family:'x;y';color:#008000\">green [[A|link]] <i>italic</i><span style='color:#1C39BB'>blue</span>green<span style='color:initial'>reset</span>green</span> plain");
    try Check.spans(inline_blocks[0].spans);
    const inline_stored = try FormattingScopeTest.encode(a, &inline_renderer, inline_blocks);
    try Check.spans(inline_stored.entry.sections[0].blocks[0].spans);
    // Local declaration parsing must not discover color inside a quoted value.
    const tag: syntax.Tag = .{ .name = "td", .attrs = "class=wikitable style=\"font-family:'x;background-color:blue';background-color:red;background-image:url(x)\"", .end = 0, .closing = false, .self_closing = false };
    try std.testing.expectEqualStrings("#ff0000", (try renderer.tableCellBackground(tag, "#ffffff")).?);
    const reset_tag: syntax.Tag = .{ .name = "td", .attrs = "style='background-color:red;background:var(--sample)'", .end = 0, .closing = false, .self_closing = false };
    try std.testing.expect((try renderer.tableCellBackground(reset_tag, "#ffffff")) == null);
    const shorthand: syntax.Tag = .{ .name = "td", .attrs = "class=wikitable style='background:#c0e4c0;background-image:none'", .end = 0, .closing = false, .self_closing = false };
    try std.testing.expectEqualStrings("#c0e4c0", (try renderer.tableCellBackground(shorthand, null)).?);
    const invalid: syntax.Tag = .{ .name = "font", .attrs = "color=red style='color:banana!important;color:green'", .end = 0, .closing = false, .self_closing = false };
    try std.testing.expectEqualStrings("#008000", (try renderer.authoredColor(invalid, "color", "color", null)).value.?);
    const legacy: syntax.Tag = .{ .name = "font", .attrs = "color=red style='color:banana'", .end = 0, .closing = false, .self_closing = false };
    try std.testing.expectEqualStrings("#ff0000", (try renderer.authoredColor(legacy, "color", "color", null)).value.?);
    const unsupported: syntax.Tag = .{ .name = "td", .attrs = "style='background-color:rgba(0,0,0,0.5)'", .end = 0, .closing = false, .self_closing = false };
    try std.testing.expect((try renderer.tableCellBackground(unsupported, "#eeeeee")) == null);
    var span_renderer: Renderer = .{ .a = a, .context = .{} };
    const spanning = try span_renderer.renderBody("<table><tr bgcolor=red><td rowspan=2>unresolved</td><td rowspan=2 bgcolor=blue>own</td></tr><tr bgcolor=green></tr></table>");
    try std.testing.expect(spanning[0].table.?.rows[0].cells[0].background == null);
    try std.testing.expectEqualStrings("#0000ff", spanning[0].table.?.rows[0].cells[1].background.?);
}

test "HTML heading single physical colon items retain heading depth and protected literal controls" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const branches = [_]struct { target: []const u8, label: []const u8 }{
        .{ .target = "templlar/conj.BEN", .label = "la conchugazión benasquesa" },
        .{ .target = "templlar/conj.RIB", .label = "la conchugazión ribagorzana" },
    };
    for (branches) |branch| {
        const source = try std.fmt.allocPrint(a, "<h4>__NOEDITSECTION__\n:''Se beiga '''[[{s}|{s}]]''' d'este berbo.''</h4>after", .{ branch.target, branch.label });
        const expected = try std.fmt.allocPrint(a, "Se beiga {s} d'este berbo.", .{branch.label});
        var renderer: Renderer = .{ .a = a, .context = .{} };
        const blocks = try renderer.renderBody(source);
        const saved = try FormattingScopeTest.encode(a, &renderer, blocks);
        inline for (.{ blocks, saved.entry.sections[0].blocks }) |actual| {
            try std.testing.expectEqual(@as(usize, 2), actual.len);
            const heading_block = actual[0];
            try std.testing.expectEqualStrings("heading", @tagName(heading_block.kind));
            try std.testing.expectEqual(@as(u8, 4), heading_block.level);
            try std.testing.expectEqual(@as(u8, 1), heading_block.depth);
            try std.testing.expectEqualStrings(":", heading_block.list_path);
            try std.testing.expectEqualStrings(expected, try FormattingScopeTest.text(a, heading_block.spans));
            var actions: usize = 0;
            for (heading_block.spans) |span| {
                const italic = if (@hasField(@TypeOf(span), "flags")) span.flags.italic else span.italic;
                try std.testing.expect(italic);
                if (span.kind == .link) {
                    actions += 1;
                    try std.testing.expectEqualStrings(branch.target, span.target);
                    try std.testing.expectEqualStrings(branch.label, span.text);
                    const bold = if (@hasField(@TypeOf(span), "flags")) span.flags.bold else span.bold;
                    try std.testing.expect(bold);
                }
            }
            try std.testing.expectEqual(@as(usize, 1), actions);
            try std.testing.expectEqualStrings("paragraph", @tagName(actual[1].kind));
            try std.testing.expectEqual(@as(u8, 0), actual[1].depth);
            try std.testing.expectEqualStrings("after", try FormattingScopeTest.text(a, actual[1].spans));
        }
        try std.testing.expect(!renderer.fallbacks.any());
    }
    const literals = [_][]const u8{
        "<h4>:literal</h4>",
        "<h4>\n&#58;literal</h4>",
        "<h4><nowiki>\n:literal</nowiki></h4>",
    };
    for (literals) |source| {
        var renderer: Renderer = .{ .a = a, .context = .{} };
        const blocks = try renderer.renderBody(source);
        const saved = try FormattingScopeTest.encode(a, &renderer, blocks);
        inline for (.{ blocks, saved.entry.sections[0].blocks }) |actual| {
            try std.testing.expectEqual(@as(usize, 1), actual.len);
            try std.testing.expectEqualStrings("heading", @tagName(actual[0].kind));
            try std.testing.expectEqual(@as(u8, 0), actual[0].depth);
            try std.testing.expectEqualStrings("", actual[0].list_path);
            try std.testing.expect(std.mem.indexOfScalar(u8, try FormattingScopeTest.text(a, actual[0].spans), ':') != null);
        }
    }
    var declined: Renderer = .{ .a = a, .context = .{} };
    for ([_][]const u8{ "visible\n:item", "\n::item", "\n*:item", "\n:first\n:second", "<pre>\n:literal</pre>", "<nowiki>\n:literal</nowiki>", "\n&#58;literal", ":same-line" }) |raw| {
        try std.testing.expect((try declined.headingColonListBody(raw)) == null);
    }
}

test "active missing internal targets produce nonaction diagnostics while intentional literals survive" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const cases = [_]struct { source: []const u8, visible: []const u8, diagnosed: bool, unresolved: usize = 1 }{
        .{ .source = "[[{{{Othera_declinunga}}}|{{{Othera_declinunga}}}]]", .visible = "[missing parameter]", .diagnosed = true, .unresolved = 2 },
        .{ .source = "[[{{{7}}}|meaningful authored label]]", .visible = "meaningful authored label [missing parameter]", .diagnosed = true },
        .{ .source = "[[{{{7}}}|label]]s", .visible = "labels [missing parameter]", .diagnosed = true },
        .{ .source = "[[{{{7}}}]]s", .visible = "[missing parameter]s", .diagnosed = true },
        .{ .source = "[[{{{7}}}|{{{7}}}]]s", .visible = "[missing parameter]s", .diagnosed = true, .unresolved = 2 },
        .{ .source = "[[{{{7}}}]]", .visible = "[missing parameter]", .diagnosed = true },
        .{ .source = "[[{{{outer|{{{inner}}}}}}|label]]", .visible = "label [missing parameter]", .diagnosed = true },
        .{ .source = "[[&#123;&#123;&#123;7&#125;&#125;&#125;|label]]", .visible = "{{{7}}}|label [malformed link]", .diagnosed = false },
        .{ .source = "<nowiki>[[{{{7}}}|label]]</nowiki>", .visible = "[[{{{7}}}|label]]", .diagnosed = false },
        .{ .source = "[[<nowiki>{{{7}}}</nowiki>|label]]", .visible = "{{{7}}}|label [malformed link]", .diagnosed = false },
        .{ .source = "[rīmcræftig]]", .visible = "rīmcræftig [malformed link]", .diagnosed = false },
    };
    for (cases) |case| {
        var renderer: Renderer = .{ .a = a, .context = .{} };
        const spans = try renderer.parseSpans(case.source, .{});
        try std.testing.expectEqualStrings(case.visible, try flattened(a, spans));
        try std.testing.expectEqual(case.diagnosed, renderer.fallbacks.missing_template);
        if (case.diagnosed) {
            try std.testing.expect(renderer.fallbacks.literal_markup);
            try std.testing.expectEqual(case.unresolved, renderer.unresolved_templates);
        }
        for (spans) |span| {
            try std.testing.expect(span.kind == .text);
            try std.testing.expectEqualStrings("", span.target);
        }
    }
    var trailing: Renderer = .{ .a = a, .context = .{} };
    const trailing_spans = try trailing.parseSpans("[[{{{7}}}|label]]s", .{ .small = true, .italic = true, .language = "an" });
    try std.testing.expectEqualStrings("labels [missing parameter]", try flattened(a, trailing_spans));
    var found_suffix = false;
    for (trailing_spans) |span| {
        try std.testing.expect(span.kind == .text and span.flags.small and span.flags.italic);
        try std.testing.expectEqualStrings("", span.target);
        try std.testing.expectEqualStrings("an", span.language);
        found_suffix = found_suffix or std.mem.eql(u8, span.text, "s");
    }
    try std.testing.expect(found_suffix);
    var standalone: Renderer = .{ .a = a, .context = .{} };
    const standalone_spans = try standalone.parseSpans("{{{stem}}}", .{ .small = true, .italic = true, .language = "an" });
    try std.testing.expectEqualStrings("[missing parameter]", try flattened(a, standalone_spans));
    try std.testing.expect(standalone.fallbacks.missing_template and !standalone.fallbacks.literal_markup);
    try std.testing.expectEqual(@as(usize, 1), standalone.unresolved_templates);
    try std.testing.expect(standalone_spans[0].flags.small and standalone_spans[0].flags.italic);
    try std.testing.expectEqualStrings("an", standalone_spans[0].language);
    for ([_][]const u8{ "{{{stem|retained default}}}", "<nowiki>{{{stem}}}</nowiki>", "&#123;&#123;&#123;stem&#125;&#125;&#125;" }, [_][]const u8{ "retained default", "{{{stem}}}", "{{{stem}}}" }) |source, visible| {
        var literal: Renderer = .{ .a = a, .context = .{} };
        const literal_spans = try literal.parseSpans(source, .{});
        try std.testing.expectEqualStrings(visible, try flattened(a, literal_spans));
        try std.testing.expect(!literal.fallbacks.missing_template);
        try std.testing.expectEqual(@as(usize, 0), literal.unresolved_templates);
    }
    var styled: Renderer = .{ .a = a, .context = .{} };
    const spans = try styled.parseSpans("[[{{{7}}}|<b><i><small>label</small></i></b>]]", .{});
    try std.testing.expectEqualStrings("label [missing parameter]", try flattened(a, spans));
    try std.testing.expect(spans[0].flags.bold and spans[0].flags.italic and spans[0].flags.small);
    var defaults: Renderer = .{ .a = a, .context = .{} };
    try std.testing.expect((try defaults.internalTargetHasUnboundParameter("{{{safe|resolved default}}}", 0)) == .none);
    try std.testing.expect(!defaults.fallbacks.render_limit);
    var nested: std.ArrayList(u8) = .empty;
    try nested.appendSlice(a, "[[");
    for (0..max_depth + 1) |_| try nested.appendSlice(a, "{{{safe|");
    try nested.appendSlice(a, "resolved");
    for (0..max_depth + 1) |_| try nested.appendSlice(a, "}}}");
    try nested.appendSlice(a, "|meaningful label]]s");
    var limited: Renderer = .{ .a = a, .context = .{} };
    const limited_spans = try limited.parseSpans(nested.items, .{});
    try std.testing.expectEqualStrings("meaningful labels [render nesting limit]", try flattened(a, limited_spans));
    try std.testing.expect(limited.fallbacks.render_limit and limited.fallbacks.literal_markup);
    try std.testing.expectEqual(@as(usize, 0), limited.unresolved_templates);
    for (limited_spans) |span| {
        try std.testing.expect(span.kind == .text);
        try std.testing.expectEqualStrings("", span.target);
    }
    var protected: Renderer = .{ .a = a, .context = .{} };
    try std.testing.expect((try protected.internalTargetHasUnboundParameter("<syntaxhighlight>{{{7}}}</syntaxhighlight>", 0)) == .none);
    try std.testing.expect((try protected.internalTargetHasUnboundParameter("<span title='{{{7}}}'>literal</span>", 0)) == .none);
}

test "raw malformed source diagnostics preserve surrounding words and independent children" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const cases = [_]struct { source: []const u8, visible: []const u8, actions: usize }{
        .{ .source = "before {Wendung|en|run}} after", .visible = "before [malformed template] after", .actions = 0 },
        .{ .source = "[rīmcræftig]] (cræftig in [[rīmung]]e)", .visible = "rīmcræftig [malformed link] (cræftig in rīmunge)", .actions = 2 },
        .{ .source = "([[[[irregular]]]])", .visible = "(irregular [malformed link])", .actions = 1 },
        .{ .source = "'''[[[[taking]]s]]'''", .visible = "takings [malformed link]", .actions = 2 },
        .{ .source = "[[prefix [[taking]] suffix]]", .visible = "prefix taking suffix [malformed link]", .actions = 1 },
        .{ .source = "[[[[taking]]|label]]", .visible = "taking|label [malformed link]", .actions = 1 },
        .{ .source = "[[Engle]] [[-", .visible = "Engle [malformed link] -", .actions = 1 },
        .{ .source = "[[bótian]] (bet weorðan]]", .visible = "bótian (bet weorðan [malformed link]", .actions = 1 },
        .{ .source = "[[khrisma]", .visible = "khrisma [malformed link]", .actions = 0 },
        .{ .source = "[[gacat\nto]]w", .visible = "gacat tow [malformed link]", .actions = 0 },
    };
    for (cases) |case| {
        var r: Renderer = .{ .a = a, .context = .{} };
        const spans = try r.parseSpans(case.source, .{ .small = true });
        try std.testing.expectEqualStrings(case.visible, try flattened(a, spans));
        try std.testing.expect(r.fallbacks.literal_markup);
        try std.testing.expect(!r.fallbacks.missing_template);
        var actions: usize = 0;
        for (spans) |item| {
            try std.testing.expect(item.flags.small);
            if (item.kind == .link) actions += 1;
            if (std.mem.indexOf(u8, item.text, "[malformed") != null) {
                try std.testing.expect(item.kind == .text);
                try std.testing.expectEqualStrings("", item.target);
            }
        }
        try std.testing.expectEqual(case.actions, actions);
    }
    for ([_][]const u8{
        "<nowiki>{Wendung|en|run}} [rīmcræftig]] [[[[irregular]]]]</nowiki>",
        "&#123;Wendung|en|run&#125;&#125; &#91;rīmcræftig&#93;&#93;",
    }) |source| {
        var r: Renderer = .{ .a = a, .context = .{} };
        const spans = try r.parseSpans(source, .{});
        try std.testing.expect(std.mem.indexOf(u8, try flattened(a, spans), "[malformed") == null);
        try std.testing.expect(!r.fallbacks.literal_markup);
    }
    var unmatched: Renderer = .{ .a = a, .context = .{} };
    try std.testing.expectEqualStrings("[malformed template] next", try flattened(a, try unmatched.parseSpans("{{open|\nnext", .{})));
    var wrong_close: Renderer = .{ .a = a, .context = .{} };
    try std.testing.expectEqualStrings("ru:Able [malformed link]", try flattened(a, try wrong_close.parseSpans("[[ru:Able}}", .{})));
    var wrong_close_later: Renderer = .{ .a = a, .context = .{} };
    const later_spans = try wrong_close_later.parseSpans("[[able]] [[ru:Able}}\n[[Category:English]]", .{});
    try std.testing.expectEqualStrings("able ru:Able [malformed link]", trim(try flattened(a, later_spans)));
    var later_actions: usize = 0;
    for (later_spans) |span| if (span.kind == .link) {
        later_actions += 1;
        try std.testing.expectEqualStrings("able", span.target);
    };
    try std.testing.expectEqual(@as(usize, 1), later_actions);
    try std.testing.expect(wrong_close_later.fallbacks.literal_markup);
    // The deterministic edge-fuzz iteration 6 ends in this ordinary suffix.
    // Recovery must retain the separator and tail instead of consuming to EOF.
    for ([_][]const u8{ "{{broken EDGE_SENTINEL", "{{{broken EDGE_SENTINEL" }) |source| {
        var trailing: Renderer = .{ .a = a, .context = .{} };
        const trailing_spans = try trailing.parseSpans(source, .{ .small = true });
        try std.testing.expectEqualStrings("[malformed template] EDGE_SENTINEL", try flattened(a, trailing_spans));
        try std.testing.expect(trailing.fallbacks.literal_markup);
        for (trailing_spans) |span| try std.testing.expect(span.kind == .text and span.target.len == 0 and span.flags.small);
    }
    var utf8_tail: Renderer = .{ .a = a, .context = .{} };
    const utf8_tail_spans = try utf8_tail.parseSpans("{{broken é猫 EDGE_SENTINEL", .{});
    const utf8_tail_text = try flattened(a, utf8_tail_spans);
    try std.testing.expectEqualStrings("[malformed template] é猫 EDGE_SENTINEL", utf8_tail_text);
    try std.testing.expect(std.unicode.utf8ValidateSlice(utf8_tail_text));
    // Every recovered link body uses ordinary control and magic-link handling;
    // single-open/double-close, single-close and wrong-curly-close agree.
    for ([_][]const u8{
        "[[x__NOEDITSECTION__]",
        "[x__NOEDITSECTION__]]",
        "[[x__NOEDITSECTION__}}",
    }) |source| {
        var switched: Renderer = .{ .a = a, .context = .{} };
        const switched_spans = try switched.parseSpans(source, .{ .small = true });
        try std.testing.expectEqualStrings("x [malformed link]", trim(try flattened(a, switched_spans)));
        for (switched_spans) |span| {
            try std.testing.expect(span.kind == .text and span.target.len == 0);
            try std.testing.expect(span.provenance == .parsed and span.flags.small);
        }
        try std.testing.expect(switched.fallbacks.literal_markup);
    }
    for ([_][]const u8{ "[RFC 2616]]", "[[RFC 2616]" }) |source| {
        var recovered_magic: Renderer = .{ .a = a, .context = .{} };
        const recovered_spans = try recovered_magic.parseSpans(source, .{ .small = true });
        try std.testing.expectEqualStrings("RFC 2616 [malformed link]", trim(try flattened(a, recovered_spans)));
        var actions: usize = 0;
        for (recovered_spans) |span| {
            try std.testing.expect(span.provenance == .parsed and span.flags.small);
            if (span.kind == .external_link) {
                actions += 1;
                try std.testing.expectEqualStrings("https://datatracker.ietf.org/doc/html/rfc2616", span.target);
            } else try std.testing.expect(span.kind == .text and span.target.len == 0);
        }
        try std.testing.expectEqual(@as(usize, 1), actions);
    }
    for ([_][]const u8{
        "<nowiki>[[x__NOEDITSECTION__] [RFC 2616]]</nowiki>",
        "&#91;&#91;x&#95;&#95;NOEDITSECTION&#95;&#95;&#93; &#91;&#82;&#70;&#67;&#32;&#50;&#54;&#49;&#54;&#93;&#93;",
    }) |source| {
        var authored_literal: Renderer = .{ .a = a, .context = .{} };
        const literal_spans = try authored_literal.parseSpans(source, .{});
        try std.testing.expectEqualStrings("[[x__NOEDITSECTION__] [RFC 2616]]", try flattened(a, literal_spans));
        for (literal_spans) |span| try std.testing.expect(span.kind == .text and span.target.len == 0);
        try std.testing.expect(!authored_literal.fallbacks.literal_markup);
    }
    // A later category must not change independent magic-link semantics
    // inside an earlier rejected wrapper. The wrapper itself stays nonaction.
    for ([_][]const u8{
        "[[RFC 2616}}",
        "[[RFC 2616}}\n[[Category:English]]",
    }) |source| {
        var paired: Renderer = .{ .a = a, .context = .{} };
        const paired_spans = try paired.parseSpans(source, .{ .small = true, .language = "en", .classes = "body-scope" });
        try std.testing.expectEqualStrings("RFC 2616 [malformed link]", trim(try flattened(a, paired_spans)));
        var rfc_actions: usize = 0;
        var markers: usize = 0;
        for (paired_spans) |span| {
            try std.testing.expect(span.provenance == .parsed);
            try std.testing.expect(span.flags.small);
            try std.testing.expectEqualStrings("en", span.language);
            try std.testing.expectEqualStrings("body-scope", span.classes);
            if (span.kind == .external_link) {
                rfc_actions += 1;
                try std.testing.expectEqualStrings("RFC 2616", span.text);
                try std.testing.expectEqualStrings("https://datatracker.ietf.org/doc/html/rfc2616", span.target);
                try std.testing.expect(!span.generated_diagnostic);
            } else {
                try std.testing.expect(span.kind == .text);
                try std.testing.expectEqualStrings("", span.target);
            }
            if (span.generated_diagnostic) {
                markers += 1;
                try std.testing.expectEqualStrings(" [malformed link]", span.text);
            }
            try std.testing.expect(std.mem.indexOf(u8, span.text, "Category:") == null);
        }
        try std.testing.expectEqual(@as(usize, 1), rfc_actions);
        try std.testing.expectEqual(@as(usize, 1), markers);
        try std.testing.expect(paired.fallbacks.literal_markup);
        try std.testing.expect(!paired.fallbacks.missing_template);
    }
    for ([_][2][]const u8{
        .{ "[[]]<b>]</b>", "[malformed link] ]" },
        .{ "{{broken]", "[malformed template] ]" },
        .{ "[<b>[[]]</b>", "[ [malformed link]" },
    }) |boundary| {
        var emitted: Renderer = .{ .a = a, .context = .{} };
        const emitted_spans = try emitted.parseSpans(boundary[0], .{});
        try std.testing.expectEqualStrings(boundary[1], try flattened(a, emitted_spans));
        for (emitted_spans) |span| try std.testing.expect(span.kind == .text and span.target.len == 0);
    }
    var encoded: Renderer = .{ .a = a, .context = .{} };
    try std.testing.expectEqualStrings("[[literal]]", try flattened(a, try encoded.parseSpans("&#91;&#91;literal&#93;&#93;", .{})));
    try std.testing.expect(!encoded.fallbacks.literal_markup);
    var ordinary: Renderer = .{ .a = a, .context = .{} };
    try std.testing.expectEqualStrings("a {set} | b", try flattened(a, try ordinary.parseSpans("a {set} | b", .{})));
    var magic: Renderer = .{ .a = a, .context = .{} };
    const magic_spans = try magic.parseSpans("RFC 2616 {Broken|x}} ISBN&nbsp;9780306406157 2020", .{});
    try std.testing.expectEqualStrings("RFC 2616 [malformed template] ISBN 9780306406157 2020", try flattened(a, magic_spans));
    var rfc = false;
    var isbn = false;
    for (magic_spans) |item| {
        rfc = rfc or (item.kind == .external_link and std.mem.eql(u8, item.target, "https://datatracker.ietf.org/doc/html/rfc2616"));
        isbn = isbn or (item.kind == .link and std.mem.eql(u8, item.target, "Special:BookSources/9780306406157"));
    }
    try std.testing.expect(rfc and isbn);
    var storm: std.ArrayList(u8) = .empty;
    for (0..8_000) |_| try storm.appendSlice(a, "{x[");
    try storm.appendSlice(a, "EDGE_SENTINEL}}");
    var bounded: Renderer = .{ .a = a, .context = .{} };
    const storm_spans = try bounded.parseSpans(storm.items, .{});
    try std.testing.expect(std.mem.indexOf(u8, try flattened(a, storm_spans), "EDGE_SENTINEL") != null);
}

test "HTML list items retain typed heading ancestry through DPR2" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const sources = [_][]const u8{
        "<ul><li>before<h3>[[A|heading]]</h3>after</li></ul>",
        "<ul><li>before\n=== [[A|heading]] ===\nafter\n</li></ul>",
        "<ul><li>before\r\n=== [[A|heading]] ===\r\nafter\r\n</li></ul>",
        "<ul><li><div>before<h3>[[A|heading]]</h3>after</div></li></ul>",
    };
    // A final physical LF or CRLF in an item collapses to one ordinary space.
    const tails = [_][]const u8{ "after", "after ", "after ", "after" };
    for (sources, tails) |source, tail| {
        var r: Renderer = .{ .a = a, .context = .{} };
        const blocks = try r.renderBody(source);
        const saved = try FormattingScopeTest.encode(a, &r, blocks);
        inline for (.{ blocks, saved.entry.sections[0].blocks }) |actual| {
            try std.testing.expectEqual(@as(usize, 3), actual.len);
            try std.testing.expectEqualStrings("list_item", @tagName(actual[0].kind));
            try std.testing.expectEqualStrings("heading", @tagName(actual[1].kind));
            try std.testing.expectEqualStrings("list_detail", @tagName(actual[2].kind));
            try std.testing.expectEqualStrings("*", actual[0].list_path);
            try std.testing.expectEqualStrings("*:", actual[1].list_path);
            try std.testing.expectEqualStrings("*:", actual[2].list_path);
            try std.testing.expectEqual(@as(u8, 3), actual[1].level);
            try std.testing.expectEqualStrings("before", try FormattingScopeTest.text(a, actual[0].spans));
            try std.testing.expectEqualStrings("heading", try FormattingScopeTest.text(a, actual[1].spans));
            try std.testing.expectEqualStrings(tail, try FormattingScopeTest.text(a, actual[2].spans));
            try FormattingScopeTest.word(a, actual, "heading", .{ .kind = .link, .target = "A" });
        }
        try std.testing.expect(!r.fallbacks.any());
    }
    const controls = [_][]const u8{
        "<ul><li><nowiki><h3>literal</h3></nowiki></li></ul>",
        "<ul><li>[[A|<h3>label</h3>]]</li></ul>",
        "<ul><li>[https://example.org <h3>label</h3>]</li></ul>",
        "<ul><li>&lt;h3&gt;literal&lt;/h3&gt;</li></ul>",
        "<ul><li>=== inline literal ===</li></ul>",
    };
    const control_text = [_][]const u8{ "<h3>literal</h3>", "label", "label", "<h3>literal</h3>", "=== inline literal ===" };
    for (controls, control_text, 0..) |source, expected_text, index| {
        var r: Renderer = .{ .a = a, .context = .{} };
        const blocks = try r.renderBody(source);
        const saved = try FormattingScopeTest.encode(a, &r, blocks);
        inline for (.{ blocks, saved.entry.sections[0].blocks }) |actual| {
            try std.testing.expectEqual(@as(usize, 1), actual.len);
            try std.testing.expectEqualStrings("list_item", @tagName(actual[0].kind));
            try std.testing.expectEqualStrings(expected_text, trim(try FormattingScopeTest.text(a, actual[0].spans)));
            if (index == 1) try FormattingScopeTest.word(a, actual, "label", .{ .kind = .link, .target = "A" });
            if (index == 2) try FormattingScopeTest.word(a, actual, "label", .{ .kind = .external_link, .target = "https://example.org" });
        }
        try std.testing.expect(!r.fallbacks.any());
    }
}

test "allocated translation and fostered headings retain authored source offsets" {
    const cases = [_]struct { source: []const u8, title_start: []const u8 }{
        .{ .source = "<table class=translations><tr><td>\n==Noun==\nbody\n</td></tr></table>", .title_start = "Noun" },
        .{ .source = "<table class=translations><tr><td>\n==No<td>un==\nbody\n</td></tr></table>", .title_start = "No<td>" },
        .{ .source = "<table><h3>Noun</h3><tr><td>cell</td></tr></table>", .title_start = "Noun" },
        .{ .source = "<ref>unmatched\n===Noun===\nbody", .title_start = "Noun" },
        .{ .source = "{|\n|-\n|<div>\n==Noun==\n{|\n! head !! other\n|-\n| one || two\n|}\n</div>\n|}", .title_start = "Noun" },
    };
    for (cases) |case| {
        var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
        defer arena.deinit();
        var renderer: Renderer = .{ .a = arena.allocator(), .context = .{}, .heading_source = case.source };
        const blocks = try renderer.renderBody(case.source);
        const Check = struct {
            fn visit(a: A, values: []const Block, expected: usize, found: *usize) anyerror!void {
                for (values) |block_value| {
                    if (block_value.kind == .heading) {
                        found.* += 1;
                        try std.testing.expectEqualStrings("Noun", try plainText(a, block_value.spans));
                        try std.testing.expectEqual(@as(?usize, expected), block_value.heading_source_offset);
                    }
                    if (block_value.table) |table| try visitTable(a, table, expected, found);
                }
            }
            fn visitTable(a: A, table: Table, expected: usize, found: *usize) anyerror!void {
                for (table.rows) |row| for (row.cells) |cell| {
                    if (cell.blocks) |ordered| {
                        try visit(a, ordered, expected, found);
                    } else if (cell.nested_table) |child| try visitTable(a, child, expected, found);
                };
            }
        };
        var found: usize = 0;
        try Check.visit(arena.allocator(), blocks, std.mem.indexOf(u8, case.source, case.title_start).?, &found);
        try std.testing.expectEqual(@as(usize, 1), found);
    }
}

test "wiki table fostered copies retain distinct heading offsets without mapping generated newlines" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    // The malformed closer ends the row, leaving later headings fostered.
    // Repeated labels must keep their distinct authored byte positions.
    const source = "{|\n==Noun==\n| cell\n|-}\n==Noun==\nbody\n===Verb===\nrest";
    var renderer: Renderer = .{ .a = a, .context = .{}, .heading_source = source };
    const blocks = try renderer.renderBody(source);
    const first = std.mem.indexOf(u8, source, "Noun").?;
    const second = std.mem.indexOfPos(u8, source, first + 4, "Noun").?;
    const expected = [_]usize{ first, second, std.mem.indexOf(u8, source, "Verb").? };
    var headings: usize = 0;
    var tables: usize = 0;
    for (blocks) |block_value| {
        if (block_value.kind == .heading) {
            try std.testing.expect(headings < expected.len);
            try std.testing.expectEqual(@as(?usize, expected[headings]), block_value.heading_source_offset);
            try std.testing.expectEqualStrings(if (headings == 2) "Verb" else "Noun", try plainText(a, block_value.spans));
            headings += 1;
        }
        if (block_value.table) |table| {
            tables += 1;
            try std.testing.expectEqual(@as(usize, 1), table.rows.len);
            try std.testing.expectEqual(@as(usize, 1), table.rows[0].cells.len);
            try std.testing.expectEqualStrings("cell", try plainText(a, table.rows[0].cells[0].spans));
        }
    }
    try std.testing.expectEqual(expected.len, headings);
    try std.testing.expectEqual(@as(usize, 1), tables);
    try std.testing.expect(renderer.fallbacks.malformed_table);

    var copied: MissingBuffer = .empty;
    var copies: std.ArrayList(HeadingSourceCopy) = .empty;
    try renderer.appendWikiTableFosteredCopy(&copied, &copies, MissingText.untracked(source), source[first .. first + 4]);
    try copied.append(a, '\n');
    try renderer.appendWikiTableFosteredCopy(&copied, &copies, MissingText.untracked(source), source[second .. second + 4]);
    const detached = try copied.take(a);
    try renderer.registerHeadingSourceCopies(detached.bytes, copies.items);
    try std.testing.expectEqual(@as(?usize, first), renderer.headingSourceOffset(detached.bytes[0..4]));
    try std.testing.expectEqual(@as(?usize, null), renderer.headingSourceOffset(detached.bytes[4..5]));
    try std.testing.expectEqual(@as(?usize, second), renderer.headingSourceOffset(detached.bytes[5..9]));
}

test "unmatched opaque escaping maps the first entity byte to its authored heading start" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const source = "===<ref>literal===\nbody";
    var renderer: Renderer = .{ .a = arena.allocator(), .context = .{}, .heading_source = source };
    const blocks = try renderer.renderBody(source);
    try std.testing.expectEqual(@as(usize, 2), blocks.len);
    try std.testing.expectEqual(Kind.heading, blocks[0].kind);
    try std.testing.expectEqualStrings("<ref>literal", try plainText(arena.allocator(), blocks[0].spans));
    try std.testing.expectEqual(@as(?usize, 3), blocks[0].heading_source_offset);

    var probe: Renderer = .{ .a = arena.allocator(), .context = .{}, .heading_source = source };
    const prepared = try probe.prepareUnmatchedOpaqueWithMissing(MissingText.untracked(source));
    const entity_at = std.mem.indexOf(u8, prepared.bytes, "&lt;").?;
    try std.testing.expectEqual(@as(?usize, 3), probe.headingSourceOffset(prepared.bytes[entity_at..]));
    try std.testing.expectEqual(@as(?usize, null), probe.headingSourceOffset(prepared.bytes[entity_at + 1 ..]));
}

test "heading source aliases compose through allocated copies and ignore generated bytes" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const source = "start No<td>un finish";
    var renderer: Renderer = .{ .a = a, .context = .{}, .heading_source = source };
    var first: std.ArrayList(u8) = .empty;
    var first_copies: std.ArrayList(HeadingSourceCopy) = .empty;
    try renderer.appendHeadingSourceCopy(&first, &first_copies, source[6..8]);
    try renderer.appendHeadingSourceCopy(&first, &first_copies, source[12..14]);
    try renderer.registerHeadingSourceCopies(first.items, first_copies.items);
    var second: std.ArrayList(u8) = .empty;
    var second_copies: std.ArrayList(HeadingSourceCopy) = .empty;
    try second.appendSlice(a, "generated ");
    try renderer.appendHeadingSourceCopy(&second, &second_copies, first.items);
    try renderer.registerHeadingSourceCopies(second.items, second_copies.items);
    try std.testing.expectEqual(@as(?usize, 6), renderer.headingSourceOffset(second.items[10..]));
    try std.testing.expectEqual(@as(?usize, 12), renderer.headingSourceOffset(second.items[12..]));
    try std.testing.expectEqual(@as(?usize, null), renderer.headingSourceOffset(second.items[0..]));
    try std.testing.expectEqual(@as(?usize, source.len), renderer.headingSourceOffset(source[source.len..]));
}

test "tracked body slices preserve missing coordinates and page heading IDs" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const source: []const u8 = "prefix\n==Noun==\nbody\n<div lang=fr>\n==Noun==\nbody\n</div>\n{|\n| cell\n|}\n";
    const body_at = std.mem.indexOf(u8, source, "body").?;
    const ranges = [_]missing_dependency.Range{.{ .start = @intCast(body_at), .end = @intCast(body_at + 4), .occurrence = 1 }};
    const tracked: MissingText = .{ .bytes = source, .ranges = &ranges, .unknown = true };
    var renderer: Renderer = .{ .a = a, .context = .{}, .heading_source = source };
    const copied = try renderer.missingSliceWithHeadingSource(tracked, source[7..]);
    try std.testing.expect(copied.bytes.ptr != source[7..].ptr);
    try std.testing.expectEqualStrings(source[7..], copied.bytes);
    try std.testing.expectEqual(@as(usize, 1), copied.ranges.len);
    try std.testing.expectEqual(@as(u32, @intCast(body_at - 7)), copied.ranges[0].start);
    try std.testing.expectEqual(@as(u32, @intCast(body_at + 4 - 7)), copied.ranges[0].end);
    try std.testing.expectEqual(@as(u32, 1), copied.ranges[0].occurrence);
    try std.testing.expect(copied.unknown);
    try std.testing.expectEqual(@as(?usize, std.mem.indexOf(u8, source, "Noun")), renderer.headingSourceOffset(copied.bytes[2..]));
    try std.testing.expectEqual(@as(u32, @intCast(body_at)), tracked.ranges[0].start);
    try std.testing.expectEqual(@as(u32, @intCast(body_at + 4)), tracked.ranges[0].end);

    const document = @import("presentation_document.zig");
    const observation = try document.observeHeadingAnchorsAlloc(a, "entry", tracked, .{}, null, null, null, .{}, null);
    try std.testing.expectEqual(@as(usize, 2), observation.items.len);
    try std.testing.expectEqual(std.mem.indexOf(u8, source, "Noun").?, observation.items[0].source_offset);
    try std.testing.expectEqual(std.mem.lastIndexOf(u8, source, "Noun").?, observation.items[1].source_offset);
    try std.testing.expectEqualStrings("Noun", observation.items[0].anchor);
    try std.testing.expectEqualStrings("Noun_2", observation.items[1].anchor);
    for (observation.items) |item| try std.testing.expectEqualStrings("", item.anchor_fallback);
}

test "flattened nested cells retain only their own opaque background runs" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var r: Renderer = .{ .a = a, .context = .{} };
    const first = [_]Span{
        .{ .kind = .link, .text = "deep", .target = "Target", .background = "#0000ff", .flags = .{ .italic = true } },
        .{ .text = "own" },
    };
    const second = [_]Span{.{ .text = "sibling" }};
    const caption = [_]Span{.{ .text = "caption" }};
    const cells = [_]Cell{
        .{ .spans = &first, .background = "#ff0000" },
        .{ .spans = &second, .background = "#008000" },
        .{ .spans = &.{}, .background = "#123456" },
    };
    const rows = [_]Row{.{ .cells = &cells }};
    const blocks = [_]Block{.{ .kind = .table, .table = .{ .caption = &caption, .rows = &rows } }};
    try r.blocksInline(&blocks, .{});
    var painted: usize = 0;
    for (r.spans.items) |span| {
        if (span.background != null) painted += 1;
        if (std.mem.eql(u8, span.text, "deep")) {
            try std.testing.expectEqualStrings("#0000ff", span.background.?);
            try std.testing.expect(span.kind == .link and span.flags.italic);
            try std.testing.expectEqualStrings("Target", span.target);
        } else if (std.mem.eql(u8, span.text, "own")) {
            try std.testing.expectEqualStrings("#ff0000", span.background.?);
        } else if (std.mem.eql(u8, span.text, "sibling")) {
            try std.testing.expectEqualStrings("#008000", span.background.?);
        } else try std.testing.expect(span.background == null);
    }
    try std.testing.expectEqual(@as(usize, 3), painted);
    try std.testing.expect(first[1].background == null and second[0].background == null);
    // No dummy text or paint extent is invented for an empty colored cell.
    try std.testing.expectEqualStrings("caption\ndeepown · sibling · ", try flattened(a, r.spans.items));
}

test "nested HTML cells flatten own row and table paint without coloring the outer tail" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var r: Renderer = .{ .a = a, .context = .{} };
    const source = "<table><tr><td bgcolor='#aaaaaa'>" ++
        "<table class='IPA' bgcolor='#112233'><caption>[[Caption|caption]]</caption><tr bgcolor='#223344'>" ++
        "<td colspan='2' rowspan='2' bgcolor='#334455'>[[Own|own]]s<br>[[Second|second]]" ++
        "<table bgcolor='#445566'><tr><td>[[Deep|deep]]</td></tr></table></td>" ++
        "<td>[[Row|row]]</td></tr><tr><td>[[Table|table]]</td><td rowspan='2'>[[NoFallback|no fallback]]</td></tr></table>" ++
        "[[Tail|tail]]</td></tr></table>";
    const blocks = try r.renderBody(source);
    try std.testing.expectEqual(@as(usize, 1), blocks.len);
    const outer = blocks[0].table.?;
    try std.testing.expectEqual(@as(usize, 1), outer.rows.len);
    const cell = outer.rows[0].cells[0];
    try std.testing.expectEqualStrings("#aaaaaa", cell.background.?);
    const targets = [_][]const u8{ "Own", "Second", "Deep", "Row", "Table", "Tail", "Caption", "NoFallback" };
    const colors = [_]?[]const u8{ "#334455", "#334455", "#445566", "#223344", "#112233", null, null, null };
    var seen: [targets.len]bool = @splat(false);
    var painted_break = false;
    for (cell.spans) |span| {
        for (targets, colors, 0..) |target, expected, index| if (std.mem.eql(u8, span.target, target)) {
            seen[index] = true;
            if (std.mem.eql(u8, target, "Tail")) {
                try std.testing.expectEqualStrings("", span.classes);
                try std.testing.expectEqual(Role.normal, span.role);
            } else {
                try std.testing.expectEqualStrings("IPA", span.classes);
                try std.testing.expectEqual(Role.pronunciation, span.role);
            }
            if (expected) |color| try std.testing.expectEqualStrings(color, span.background.?) else try std.testing.expect(span.background == null);
        };
        if (span.kind == .line_break and span.background != null and std.mem.eql(u8, span.background.?, "#334455")) painted_break = true;
    }
    for (seen) |present| try std.testing.expect(present);
    try std.testing.expect(painted_break);
    const text = try flattened(a, cell.spans);
    for ([_][]const u8{ "owns", "second", "deep", "row", "table", "tail" }) |word|
        try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, text, word));
}

test "inline nested HTML paint preserves empty tables and protected literal controls" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    for ([_][]const u8{
        "<nowiki><table bgcolor='#ff0000'><tr><td>literal</td></tr></table></nowiki>",
        "<pre><table bgcolor='#ff0000'><tr><td>literal</td></tr></table></pre>",
        "<!-- <table bgcolor='#ff0000'><tr><td>literal</td></tr></table> -->plain",
        "&lt;table bgcolor='#ff0000'&gt;literal&lt;/table&gt;",
        "<span title=\"literal <table bgcolor='#ff0000'>\">plain</span>",
        "<table></table>plain",
        "<table/>plain",
    }) |source| {
        var r: Renderer = .{ .a = a, .context = .{} };
        const spans = try r.cellSpans(source);
        for (spans) |span| try std.testing.expect(span.background == null);
    }
    var empty: Renderer = .{ .a = a, .context = .{} };
    const empty_spans = try empty.cellSpans("before<table></table>after");
    try std.testing.expectEqualStrings("before\nafter", try flattened(a, empty_spans));
    var protected: Renderer = .{ .a = a, .context = .{} };
    const literal = "<table bgcolor='#ff0000'><tr><td>literal</td></tr></table>";
    const protected_spans = try protected.cellSpans("<nowiki>" ++ literal ++ "</nowiki>");
    try std.testing.expectEqualStrings(literal, try flattened(a, protected_spans));
}

test "synthetic list formatting prefixes preserve seeded quote coordinates" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const source = "# <small>[[mimer|mimes]] {{small|form}}\n''next'' <nowiki>''literal''</nowiki></small>\n# [[Tail|tail]]";
    var ordinary: Renderer = .{ .a = a, .context = .{} };
    const baseline = try ordinary.renderBodySlice(source, false, false, null, null);
    var scan = QuoteBoundaryScan.initWithContext(source, null, .{});
    const initial = try scan.at(a, 0, null);
    var seeded: Renderer = .{ .a = a, .context = .{} };
    const actual = try seeded.renderBodySlice(source, false, false, null, initial);
    try std.testing.expectEqual(baseline.len, actual.len);
    var mimes = false;
    var next = false;
    var literal = false;
    var tail = false;
    for (baseline, actual) |expected_block, block| {
        try std.testing.expectEqual(expected_block.kind, block.kind);
        try std.testing.expectEqualStrings(expected_block.list_path, block.list_path);
        try std.testing.expectEqualStrings(try flattened(a, expected_block.spans), try flattened(a, block.spans));
        try std.testing.expectEqual(expected_block.spans.len, block.spans.len);
        for (expected_block.spans, block.spans) |expected, span| {
            try std.testing.expectEqual(expected.kind, span.kind);
            try std.testing.expectEqualStrings(expected.target, span.target);
            try std.testing.expectEqual(expected.flags, span.flags);
            try std.testing.expectEqual(expected.provenance, span.provenance);
            if (std.mem.eql(u8, span.target, "mimer")) {
                mimes = true;
                try std.testing.expect(span.flags.small and !span.flags.italic);
            }
            if (std.mem.eql(u8, span.text, "next")) {
                next = true;
                try std.testing.expect(span.flags.small and span.flags.italic);
            }
            if (std.mem.eql(u8, span.text, "''literal''")) {
                literal = true;
                try std.testing.expect(span.flags.small and !span.flags.italic and span.provenance == .protected_literal);
            }
            if (std.mem.eql(u8, span.target, "Tail")) {
                tail = true;
                try std.testing.expect(!span.flags.small and !span.flags.italic);
            }
        }
    }
    try std.testing.expect(mimes and next and literal and tail);
}

test "double quoted HTML names escape angles while body formatting and actions continue" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const cases = [_]struct { source: []const u8, visible: []const u8 }{
        .{ .source = "<li\">'''word'''</li> [[Tail|tail]]", .visible = "<li\">word tail" },
        .{ .source = "<dIv\"name>'''word'''</li> [[Tail|tail]]", .visible = "<dIv\"name>word tail" },
        .{ .source = "</li\">'''word''' [[Tail|tail]]", .visible = "</li\">word tail" },
        .{ .source = "<x\"y\">'''word''' [[Tail|tail]]", .visible = "<x\"y\">word tail" },
    };
    for (cases) |case| {
        var renderer: Renderer = .{ .a = a, .context = .{} };
        const spans = try renderer.parseSpans(case.source, .{});
        try std.testing.expectEqualStrings(case.visible, try flattened(a, spans));
        var bold = false;
        var tail = false;
        var angles: usize = 0;
        for (spans) |span| {
            if (std.mem.eql(u8, span.text, "word") and span.flags.bold) bold = true;
            if (span.kind == .link and std.mem.eql(u8, span.target, "Tail") and std.mem.eql(u8, span.text, "tail")) tail = true;
            if (std.mem.eql(u8, span.text, "<") or std.mem.eql(u8, span.text, ">")) {
                angles += 1;
                try std.testing.expect(span.kind == .text and span.target.len == 0 and span.provenance == .entity_literal);
            }
        }
        try std.testing.expect(bold and tail and angles == 2 and renderer.fallbacks.literal_markup);
    }
    var valid: Renderer = .{ .a = a, .context = .{} };
    try std.testing.expectEqualStrings("• word\n", try flattened(a, try valid.parseSpans("<li>word</li>", .{})));
    var literal: Renderer = .{ .a = a, .context = .{} };
    try std.testing.expectEqualStrings("<li\">'''word'''</li>", try flattened(a, try literal.parseSpans("<nowiki><li\">'''word'''</li></nowiki>", .{})));
    try std.testing.expect(!literal.fallbacks.literal_markup);
    var entity: Renderer = .{ .a = a, .context = .{} };
    try std.testing.expectEqualStrings("<li\">word", try flattened(a, try entity.parseSpans("&lt;li\"&gt;'''word'''", .{})));
    try std.testing.expect(!entity.fallbacks.literal_markup);
}

